const D: MvBook[] = [{"u":"Молитва Пресвятій Богородиці перед іконою «Охтирська»","e":"Prayer to the Theotokos before her icon “Okhtyrka”","secs":[{"h":"Тропар, глас 4","ps":["Преблагослове́нная Ді́во, Богороди́тельнице Чи́стая, / у Креста́ Си́на Твоєго́ і Бо́га на́шего предстоя́щи, / скорб ве́лію претерпі́ла єси́ / і благода́ть от Него́ прия́ла єси́ су́щия в ско́рбіх утіша́ти. / Ті́мже на пречи́стий о́браз Твой благогові́йно взира́юще / і ізображе́нную Тя на нем пред Кресто́м Спа́са на́шего ви́дяще, / умиле́нно к Тебі́ вопіє́м: / Засту́пнице усе́рдная, блага́я і ми́лостивая! / Ускори́ ізба́вити ни от вся́кия ско́рби, ну́жди і болі́зні / і спаси́ ду́ші на́ша, // да Тя со благодаре́нієм сла́вим во ві́ки."]},{"h":"Кондак, глас 8","ps":["Притеце́м, ві́рнії, к благода́тному ми́лостей і щедро́т істо́чнику - / чудотво́рному Пречи́стия Ді́ви о́бразу: / сей бо нам сви́ше дарова́ся, / душа́м і тілесе́м во спасе́ніє, / єму́же покланя́ющеся с любо́вію, возопіє́м к Богоро́диці: / о Всепі́тая Ма́ти, о Цари́ці Всеми́лостивая, / покри́й і соблюди́ нас от вся́каго зла // Твої́м к Бо́гу Ма́тернім предста́тельством."]},{"h":"Молитва","ps":["О Преблагослове́нная і Многоми́лостивая Влади́чице ми́ра! Се ми грі́шнії на святи́й о́браз Твой взира́юще і на нем Тя в ско́рбі і сострада́нії расп'я́тому за нас Христу́ Спаси́телю предстоя́щу ви́дяще, усе́рдно мо́лим Тя ізві́стную о нас к Си́ну Твоєму́ моли́твенницю: не оста́ви нас в день іспита́нія і ско́рби, но во іскуше́ніїх і напа́стіх нам бива́ємих огради́ нас всечестни́м покро́вом Твої́м от враг ви́димих і неви́димих і даждь нам си́лу, во є́же всесоверше́нную і благу́ю во́лю Творця́ і ми́ра Влади́ки твори́ти. Зри́ши бо, ми́лостивая Засту́пнице на́ша, коли́ко гріха́м вся́чеським подве́ржені єсьми́: не то́кмо бо во́лею согріша́єм, но і нево́лею в многоразли́чния прегріше́нія впада́єм. Сего́ ра́ди к Тебі́ держа́вній устрої́тельнице спасе́нія христия́нськаго прибіга́єм і умиле́нно вопіє́м: ум наш позна́нієм Боже́ственния і́стини просвіти́, се́рдце на́ше теплото́ю христия́нськия любві́ і спаси́тельних жела́ній согріва́й, во́лю же на́шу в нелицеме́рном за́повідей Госпо́дніх ісполне́нії утверди́. Єй, Госпоже́ Преми́лостивая, прини́кни с висоти́ небе́сния к воздиха́нієм і моли́тві нас грі́шних: ісціли́ болі́зні неду́жних, умири́ сердця́ озло́бленних, даждь терпі́ніє стра́ждущим, внуши́ страх Бо́жий оби́дящим, укріпи́ гони́мия за пра́вду, си́роти і вдо́ви защити́, пода́ждь утіше́ніє пла́чущим, іспроси́ проще́ніє ка́ющимся, де́монськую же бу́рю страсте́й во грі́шних душа́х ути́ши і в сердця́х чту́щих Тя Христо́ву кро́тость і любо́во вкорени́ і ду́хом милосе́рдія і сострада́нія сія́ утверди́: отпа́дшия же от ві́ри єретики́ і отсту́пники к позна́нію і́стини напра́ви і уста́ нечести́вих, ху́лящих Святу́ю Це́рков і ві́ру правосла́вную понося́щих загради́. Отше́дшим от житія́ сего́ отце́м і бра́тіям і се́страм на́шим, о Ма́ти Бо́жия, проще́ніє гріхо́в і преднача́тіє блаже́нства ві́чнаго іспроси́. Єгда́ же і на́шея кончи́ни час прибли́житься, тогда́ у́бо, о Влади́чице, прийми́ ду́шу на́шу і в со́нмі пра́ведних сію́ упоко́й, іді́же ли́ци А́нгел і святи́х уго́дник немо́лчно славосло́в'ять держа́ву і ми́лость Отця́ і Си́на і Свята́го Ду́ха і Твоє́ ма́тернеє о нас предста́тельство і заступле́ніє, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Благодатне Небо»","e":"Prayer to the Theotokos before her icon “Blessed Heaven”","secs":[{"h":"Тропар, глас 6","ps":["Что Тя нарече́м, о Благода́тная? / Не́бо? – я́ко возсія́ла єси́ Со́лнце Пра́вди; / рай? – я́ко прозябла́ єси́ Цвіт нетлі́нія; / Ді́ву? – я́ко пребила́ єси́ нетлі́нна; / Чи́стую Ма́тер? – я́ко імі́ла єси́ на святи́х Твої́х об'я́тіях Си́на, всіх Бо́га. / Того́ моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, да не постиді́мся."]},{"h":"Молитва","ps":["Что Тя нарече́м, о Благода́тная Богома́ти Богоотрокови́це, Пренепоро́чная Марі́є? Ки́їми піснопі́нії возвели́чим Тя, возвели́ченную Не́бом і земле́ю, А́нгелами і челові́ки? Яви́ся бо на Тебі́ несли́шанноє от ві́ка на землі́ і несві́домоє А́нгелами на Небесі́ та́їнство, па́че ума́ і сло́ва, вочелові́ченія Бо́га Сло́ва, рожде́ннаго сискони́ от Безнача́льнаго Отця́ без ма́тері і воплоще́ннаго в Твоє́й утро́бі і с нетлі́нною печа́тію ді́вства Твоєго́ роди́вшагося. О, чу́до всіх дре́вніх і но́вих чуде́с! Непрело́жноє сло́во Сама́го Бо́га о победоно́сном сі́мені жени́ і іспо́лнися і соверши́ся в Безму́жней Ді́ві. О, неізміри́мая глубина́ прему́дрості і вели́чія Бо́жия! Ки́їми імени́ нарече́м Тя, о Неві́сто Неневі́стная? Заре́ю ли нарече́м Тя восходя́щаго на не́бі со́лнця? Но Ти — са́моє Не́бо, із Тебе́ бо возсія́ Со́лнце Пра́вди — Христо́с Бог наш, Спаси́тель грі́шних. Імену́єм ли Тя врата́ми, вводя́щими в поте́рянний прароди́телями рай, оби́ловавший всі́ми блага́ми? Но Ти Сама́ єси́ благода́тний рай, проізрасти́вшая Цвіт нетлі́нія, врачу́ющий і отгоня́ющий смерде́ніє гріха́ і злово́ніє прароди́тельськаго тлі́нія. Нарече́м ли Тя ю́ною Непоро́чною Ді́вою, не позна́вшей бра́ка? Но Ти і до ста́рости пребила́ Неіскусобра́чною і ді́вственною до рожде́нія, і в рожде́нії, і по рожде́нії Си́на пребила́ єси́. Наймену́єм ли Тя Чи́стою і Свято́ю Ма́рією, превозше́дшею Своє́ю чистото́ю всіх ма́терей і прама́терей? Но Ти не то́кмо родила́ Того́ Младе́нця Христа́, но і носи́ла Єго́ при Свої́х пе́рсіх, і пита́ла Твої́м матероде́вственним млеко́м, Того́, І́же пита́єть вся́коє созда́ніє, Єму́же со стра́хом і тре́петом предстоя́ть Небе́сния си́ли і Єго́ же хва́лить вся́коє диха́ніє і твар. О, воі́стину Ти ди́вная єси́ в жена́х, чу́дная в ді́вах, неподража́ємая в ма́теріх! К Тебі́ пред Твої́м Боже́ственним ли́ком припа́даєм і пред Твої́ми святи́ми стопа́ми поверга́єм і слага́єм все на́ші ми́слі, жела́нія, намі́ренія і чу́вства. Освяти́ їх Твої́м Богома́тернім призрі́нієм і вознеси́ їх, я́ко же́ртву на́шего смире́ннаго се́рдця, я́ко малоце́нную ле́пту на́шей духо́вной нищети́, к Престо́лу Си́на Твоєго́, Спаси́теля на́шего, да і́миже вість судьба́ми упра́вить наш путь ко спасе́нію і наслі́дію Ца́рствія Єго́, не іму́щаго конця́ во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Боголюбська»","e":"Prayer to the Theotokos before her icon “Bogolyubovo”","secs":[{"h":"Тропар, глас 1","ps":["Боголюби́вая Цари́це, / Неіскусому́жная Ді́во Богоро́дице Марі́є! / Моли́ за ни Тебе́ Возлюби́вшаго / і ро́ждшагося от Тебе́ Си́на Твоєго́ Христа́ Бо́га на́шего, / пода́ти нам оставле́ніє прегріше́ній, / і ми́рові мир, землі́ плодо́в ізоби́ліє, / па́стирем святи́ню / і всему́ челові́чу ро́ду спасе́ніє. / Гра́ди на́ша і страни́ Українськия от нахожде́нія іноплеме́нних заступи́ / і от междоусо́бния бра́ні сохрани́. / О Ма́ти Боголюби́вая Ді́во! / О Цари́ці Всепі́тая! / Ри́зою Твоє́ю покри́й нас от вся́каго зла, / от ви́димих і неви́димих враг защити́, // і спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 1","ps":["Всепі́тая і Всесла́вная Цари́це Богоро́дице, / Ма́ти всея́ тва́рі Соді́теля, / христия́нськая Наде́ждо і Засту́пнице, / печа́льних Утіше́ніє, ненаді́ющихся і отча́явшихся ско́роє наді́яніє, / мо́лим Тя: ми́лостива бу́ди нам грі́шним, / і не оста́ви раб Свої́х, / і не отри́ни моле́нія ві́рних, / в ско́рб'ях і біда́х пред честни́м о́бразом Твої́м ізбавле́нія тре́бующих. / О Влади́чице, Блага́я Помо́щнице! / Ри́зою Твоє́ю честно́ю нас защити́ і от всіх зол ізба́ви, / моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, // да спасе́ть ду́ші на́ша, я́ко Милосе́рд."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь предстої́ть Си́ну, / ру́ці Свої́ к Нему́ проостира́ющи, / святи́й князь Андре́й ра́дується, / і с ним Українськая страна́ торжеству́єть, // нас бо ра́ди мо́лить Богоро́диця преве́чного Бо́га."]},{"h":"Молитва перша","ps":["О, Пречи́стая Госпоже́ Богоро́дице, Ма́ти Боголюби́вая, наде́ждо на́шего спасе́нія! Воззри́ ми́лостивно на предстоя́щия с ві́рою і любо́вію і покланя́ющіяся пречи́стому о́бразу Твоєму́; прийми́ на́ше хвале́бноє пі́ніє сіє́ і проле́й те́плую Твою́ моли́тву о нас грі́шних ко Го́споду, да, презрі́во вся на́ша согріше́нія, спасе́ть і поми́луєть нас! О, Преди́вная Влади́чице! Покажи́ на нас чу́дния ми́лості Твоя́. Мо́лим Тя умиле́нно, ізба́ви нас от вся́кия ско́рби, наста́ви на путь вся́кия доброді́телі і благости́ні, спаси́ от іскуше́ній, бід і болі́зней, ізми́ от нас оклевета́нія і ссо́ри; сохрани́ от молнієно́снаго гро́ма, от запале́нія о́гненнаго, от гла́да, тру́са, пото́па і смертоно́сния я́зви; пода́й нам Свою́ ми́лостивую по́мощ на путі́, в мо́рі і на су́ші, да не поги́бнем лю́ті. О, Всеми́лостивая Боголюби́вая Ма́ти, с тве́рдим упова́нієм возсила́єм к Тебі́ на́шу смире́нную моли́тву! Не отри́ни на́ших слез і воздиха́ній, не забу́ди нас во вся дні живота́ на́шего, но всегда́ пребива́й с на́ми, і Твої́м заступле́нієм і хода́тайством у Го́спода пода́ждь нам отра́ду, утіше́ніє, защи́ту і по́мощ, да ви́ну сла́вим і велича́єм Преблагослове́нноє і Всепі́тоє і́м'я Твоє́. Амі́нь."]},{"h":"Молитва друга","ps":["О Чу́дная і Ви́сшая всіх тва́рей Цари́це Богоро́дице, Небе́снаго Царя́ Христа́ Бо́га на́шего Ма́ти! Усли́ши нас, грі́шних і недосто́йних раб Твої́х, в час сей моля́щихся і припа́дающих к Тебі́ с воздиха́нієм і слеза́ми і уми́льно глаго́лющих; ізведи́ нас от ро́ва страсте́й, Влади́чице; ізба́ви нас от вся́кия ско́рби і печа́лі; огради́ от вся́кия напа́сти і злих клеве́ть, от непра́ведного і лю́таго наві́та вра́жия. Мо́жеши бо, о Благода́тная Ма́тер на́ша, не то́чію от вся́каго зла сохрани́ти лю́ди Твоя́, но і вся́ким благодія́нієм снабди́ти і спасти́: ра́зві Тебе́ іни́я Предста́тельниці в біда́х і обстоя́ніїх і те́плия Хода́тайці о нас, грі́шних, не і́мами к Си́ну Твоєму́, Христу́ Бо́гу на́шему, Єго́же умоли́, Влади́чице, да спасе́ннії Тобо́ю сла́вим і в бу́дущем ві́ці Всесвято́є І́м'я Си́на Твоєго́ і Бо́га на́шего, ку́пно со Отце́м і Святи́м Ду́хом, ни́ні і в бесконе́чния ві́ки. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой святи́й, / єго́же благові́рний князь Андре́й даде́ нам на враги́ в побі́ду / і всім ві́рним во спасе́ніє."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Взискання погибших»","e":"Prayer to the Theotokos before her icon “Seeker of the Lost”","secs":[{"h":"Тропар, глас 7","ps":["Ра́дуйся, Благода́тная Богоро́дице Ді́во, / во об'я́тіях Свої́х Предві́чнаго Младе́нця і Бо́га носи́вшая. / Проси́ Єго́ да́ти ми́ру умире́ніє / і душа́м на́шим спасе́ніє. / Син бо Тебе́, Богома́ти, віща́єть, / я́ко вся проше́нія Твоя́ во благо́є іспо́лнить. / Сего́ ра́ди і ми припа́дающе, мо́лимся / і наді́ющіїся на Тя, да не поги́бнем, / і́м'я Твоє́ імену́єм: / Ти бо єси́ Влади́чице, // Взиска́ніє поги́бших."]},{"h":"Інший тропар, глас 4","ps":["Взищи́ нас, погиба́ющих, Пресвята́я Ді́во, / не по гріхо́м бо на́шим наказу́єши нас, / но по человіколю́бію ми́луєши, / ізба́ви нас от а́да, болі́зні і ну́жди // і спаси́ нас."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, / ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Інший кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Пречи́стая Ді́во, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Молитва перша","ps":["О Пресвята́я і Преблагослове́нная Ді́во, Влади́чице Богоро́дице! При́зри ми́лостивним Твої́м о́ком на нас, предстоя́щих пред свято́ю іко́ною Твоє́ю і со умиле́нієм моля́щихся Тебі́; воздви́гни нас із глубини́ гріхо́вния, просвіти́ ум наш, омраче́нний страстьми́, і уврачу́й я́зви душ і тіле́с на́ших. Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице. Ти ві́си вся не́мощі і согріше́нія на́ша, к Тебі́ прибіга́єм і вопіє́м: не оста́ви нас Твоє́ю Небе́сною по́мощію, но предста́ни нам при́сно і Твої́м неізрече́нним милосе́рдієм і щедро́тами спаси́ і поми́луй нас, погиба́ющих. Да́руй нам ісправле́ніє гріхо́вния жи́зні на́шея і ізба́ви нас от скорбе́й, бід і болі́зней, от внеза́пния сме́рті, а́да і ві́чния му́ки. Ти бо, Цари́це і Влади́чице, ско́рая Помо́щниця і Засту́пниця єси́ всім притека́ющим к Тебі́ і крі́пкоє прибі́жище грі́шников ка́ющихся. Пода́ждь у́бо нам, Преблага́я і Всенепоро́чная Ді́во, христия́нський коне́ць житія́ на́шего ми́рен і непости́ден і сподо́би нас Твої́м хода́тайством всели́тися в Оби́телях Небе́сних, іді́же непреста́нний глас пра́зднующих ра́достію сла́вить Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Засту́пнице Усе́рдная, Благоутро́бная Го́спода Ма́ти, к Тебі́ прибіга́ю аз, окая́нний і па́че всіх челові́ко грішні́йший; воньми́ гла́су моле́нія моєго́, вопль мой і стена́ніє усли́ши. Я́ко беззако́нія моя́ превзидо́ша главу́ мою́, і аз, я́коже кора́бль в пучи́ні, погружа́юся в мо́ре гріхо́в мої́х. Но Ти, Всеблага́я і Милосе́рдная Влади́чице, не пре́зри мене́, отча́яннаго і во грісі́х погиба́ющаго; поми́луй м'я, ка́ющагося в злих ді́ліх мої́х, і обрати́ на путь пра́вий заблу́дшую окая́нную ду́шу мою́. На Тебі́, Влади́чице моя́, Богоро́дице, возлага́ю все упова́ніє моє́. Ти, Ма́ти Бо́жия, сохрани́ і соблюди́ м'я под кро́вом Твої́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О Пресвята́я Влади́чице і Богоро́дице, Ви́сшая Херуви́м і Честні́йшая Серафи́м, Богоізбра́нная Отрокови́це, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте! Пода́ждь утіше́ніє і нам, в поги́белі і ско́рби су́щим; ра́зві бо Тебе́ іно́го прибі́жища і по́мощі не і́мами. Ти єди́на єси́ ра́дости на́шея Хода́тайця, і я́ко Ма́тер Бо́жия і Ма́ти милосе́рдія, предстоя́щи у Престо́ла Пресвяти́я Тро́йці, мо́жеши нам помощі́, нікто́же бо притека́яй к Тебі́ посра́млен отхо́дить. Усли́ши у́бо і нас ни́ні в день поги́белі і печа́лі пред Твоє́ю іко́ною припа́дающих і со слеза́ми Тебі́ моля́щихся: отжени́ от нас належа́щия на нас ско́рби і бі́ди в сей вре́менній жи́зні, не лише́ни же сотвори́ Твої́м всеси́льним хода́тайством і ві́чния несконча́ємая ра́дости в Ца́рствії Си́на Твоєго́ і Бо́га на́шего. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Володимирська»","e":"Prayer to the Theotokos before her icon “Vladimir”","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється сла́внійший град Київ, / я́ко зарю́ со́лнечную восприє́мши, Влади́чице, чудотво́рную Твою́ іко́ну, / к не́йже ни́ні ми притека́юще і моля́щеся Тебі́, взива́єм си́це: / о, пречу́дная Влади́чице Богоро́дице! / Моли́ся із Тебе́ воплоще́нному Христу́ Бо́гу на́шему, / да ізба́вить град сей і вся гра́ди і страни́ христия́нськия невреди́ми от всіх наві́т вра́жиїх, // і спасе́ть ду́ші на́ша, я́ко Милосе́рд."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих прише́ствієм Твоєго́ честна́го о́браза, / Влади́чице Богоро́дице, / сві́тло сотворя́єм пра́зднество срі́тенія Твоєго́ / і оби́чно зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Інший кондак, глас 8","ps":["К Взбра́нней Воєво́ді і Засту́пнице, Ді́ві і Богоро́дице, / в чи́стій со́вісти, ві́рою утверди́вшеся, українськії наро́ди, / невозвра́тно наде́жду іму́ще, притеце́м, / к чудотво́рному Єя́ і пречи́стому о́бразу, і возопіє́м Єй: / ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["О Всеми́лостивійшая Госпоже́ Богоро́дице, Небе́сная Цари́це, Всемо́щная Засту́пнице, непости́дноє на́ше Упова́ніє! Благодаря́ще Тя о всіх вели́ких благодія́ніях, в ро́ди родо́в лю́дем українським от тебе́ би́вших, пред пречи́стим о́бразом Твої́м мо́лим Тя: сохрани́ град сей (іли́: весь сію́, іли́: святу́ю оби́тель сію́) і предстоя́щия раби́ Твоя́ і всю Зе́млю Українськую от гла́да, губи́тельства, землі́ трясе́нія, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні. Сохрани́ і спаси́, Госпоже́, Вели́кого Господи́на і Отця́ на́шего (ім’я), Святе́йшего Патріарха Київського і всієї України і Господи́на на́шего (ім’я), Преосвяще́ннейшего єпи́скопа (іли́: архієпи́скопа, іли́: митрополи́та) (ти́тул), і вся Преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи правосла́вния. Даждь їм Це́рков Українськую до́брі упра́вити, ві́рния о́вці Христо́ви неги́блеми соблюсти́. Пом'яни́, Влади́чице, і весь свяще́нничеський і мона́шеський чин, согрі́й сердця́ їх ре́вностію о Бо́зі і досто́йно зва́нія своєго́ ходи́ти коєго́ждо укріпи́. Спаси́, Госпоже́, і поми́луй і вся раби́ Твоя́ і да́руй нам путь земна́го по́прища без поро́ка прейти́. Утверди́ нас во ві́рі Христо́вой і во усе́рдії ко Правосла́вной Це́ркві, вложи́ в сердця́ на́ша дух стра́ха Бо́жия, дух благоче́стія, дух смире́нія, в напа́стіх терпі́ніє нам пода́ждь, во благоде́нствії – воздержа́ніє, к бли́жнім любо́в, ко враго́м всепроще́ніє, в до́брих ді́ліх преуспі́яніє. Ізба́ви нас от вся́кого іскуше́нія і от окамене́ннаго нечу́вствія, в стра́шний же день Суда́ сподо́би нас хода́тайством Твої́м ста́ти одесну́ю Си́на Твоєго́, Христа́ Бо́га на́шего, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Всеблаженна» («Памакариста»)","e":"Prayer to the Theotokos before her icon “Most Blessed” (“Pammakaristos”)","secs":[{"h":"Тропар, глас 4","ps":["Торжество́ днесь пра́зднуєм сві́тлоє, / се бо предлежи́ть, о Всеблаже́нная, іко́на Твоя́ всечестна́я, / к не́йже любо́вію се́рдця всі приходя́ще, Влади́чице, / покланя́ємся і те́плі Тебі́ вопіє́м: // ізба́ви нас от бід і обстоя́ній."]},{"h":"Кондак, глас 4","ps":["В пра́здник Твой соше́дшеся, ві́рнії, / свяще́нноє ко сла́ві Бо́жієй торжество́ Твоє́, Влади́чице, / днесь всеблагогові́йно соверша́єм, / любо́вію же чту́ще честну́ю іко́ну Твою́, / Тебі́ пісносло́вим всі в ра́дості: // ра́дуйся, Ді́во, Честна́я, Всеблаже́нная."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода Ви́шніх сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея всемо́щная Засту́пнице! Прийми́ хвале́бноє пі́ніє сіє́ от нас недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить благода́ть Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланя́ющимся пречи́стому о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рій Засту́пниці на́шей: усли́ши нас моля́щихся Тебі́, удиви́ над на́ми вели́кия і бога́тия ми́лості Твоя́, яви́ нам небе́сную по́мощ Твою́ і заступле́ніє, і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиренному́дріє, супру́гом любо́в і согла́сіє, ча́дом послуша́ніє, оби́димим терпі́ніє, оби́дящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє; нам же всім низпосли́ дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пречи́стая! Умилосе́рдися на немощни́я лю́ди Твоя́, рассе́янния собери́, заблу́ждшия на путь пра́вий наста́ви, неду́гующия уврачу́й, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й, і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ші ко зрі́нію спасе́нія. Ми́лостива нам бу́ди зді і на стра́шнім суді́ Си́на Твоєго́, преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со а́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, сла́ва небе́сних і упова́ніє земни́х, Ти по Бо́зі на́ша Наде́жда і Засту́пниця всіх притека́ющих к Тебі́ с ві́рою. Тебі́ у́бо мо́лимся, і Тебі́, я́ко всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і всю жизнь на́шу предає́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Всіх скорботних Радість»","e":"Prayer to the Theotokos before her icon “Joy of All Who Sorrow”","secs":[{"h":"Тропар, глас 8","ps":["Ко істо́чнику приснотеку́щему милосе́рдія, Пречи́стій Ді́ві Богоро́диці, / притеце́м, лю́діє всі, свяще́нници же і і́ноці, / му́жіє, і же́ни, і ча́да, здра́вії і боля́щії, / в покая́нії вопію́ще і уми́льно глаго́люще: / Влади́чице, помози́ грі́шним рабо́м Твої́м, / яви́ я́ко Блага́я сла́ву Твою́, / при́сно потщи́ся умилосе́рдитися на ни, / іспроси́ти очище́ніє душ і тіле́с на́ших / от Істо́чника жи́зні на́шея, Бо́га, // Єго́же родила́ єси́, єди́на Благослове́нная."]},{"h":"Інший тропар, глас 4","ps":["Днесь пресві́тло красу́ється сла́внійший град Київ, / імі́я чудотво́рную іко́ну Влади́чиці на́шея Богоро́диці: / та бо, ві́рним явля́ющи чудеса́, / низпосила́єть да́ри ціле́бния. / Сего́ ра́ди і ми с ві́рою припа́дающе мо́лимся, / і на Тоя́ пречи́стий о́браз взира́юще, / я́ко і́стинную Са́мую зрим Влади́чицю на́шу Присноді́ву Богоро́дицю, / і уми́льно глаго́лем: / воззри́, Ма́ти Бо́жия, о́ком ми́лости, / простри́ к нам ру́ці Твої́ пречи́стия, / я́коже на і́коні Твоє́й сіє́ зри́ться, / і пода́ждь всім скорб'я́щим ра́дость, / больни́м от всіх неду́гов ісціле́ніє і от бід ізбавле́ніє, // я́ко Ти єси́ ско́рая Предста́тельниця о душа́х на́ших."]},{"h":"Інший тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грішні́ї і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній. / Не отврати́ Твоя́ раби́ тщи, // Тя бо і єди́ну наде́жду і́мами."]},{"h":"Інший тропар, глас 4","ps":["Не умолчи́м нікогда́, Богоро́дице, / си́ли Твоя́ глаго́лати недосто́йнії: / а́ще бо Ти не би предстоя́ла моля́щи, / кто би нас ізба́вил от толи́ких бід; / кто же би сохрани́л дони́ні свобо́дні; / не отсту́пим, Влади́чице, от Тебе́: // Твоя́ бо раби́ спаса́єши при́сно от вся́ких лю́тих."]},{"h":"Стихира, що співається замість тропаря, глас 2","ps":["Всіх скорб'я́щих Ра́досте, / і оби́димих Засту́пнице, / і а́лчущих Пита́тельнице, / стра́нних Утіше́ніє, / обурева́ємих Приста́нище, / больни́х посіще́ніє, / не́мощних покро́в і засту́пнице, / Жезл ста́рости, / Ма́ти Бо́га Ви́шняго Ти єси́, Пречи́стая: // потщи́ся, мо́лимся, спасти́ся рабо́м Твої́м."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице. / Ти нам помози́: / на Тебі́ наді́ємся і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Молитва перша","ps":["О Пресвята́я і Преблагослове́нная Ді́во, Влади́чице Богоро́дице! При́зри ми́лостивним Твої́м о́ком на нас, предстоя́щих пред свято́ю іко́ною Твоє́ю і со умиле́нієм моля́щихся Тебі́; воздви́гни нас із глубини́ гріхо́вния, просвіти́ ум наш, омраче́нний страстьми́, і уврачу́й я́зви душ і тіле́с на́ших. Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице. Ти ві́си вся не́мощі і согріше́нія на́ша, к Тебі́ прибіга́єм і вопіє́м: не оста́ви нас Твоє́ю Небе́сною по́мощію, но предста́ни нам при́сно і Твої́м неізрече́нним милосе́рдієм і щедро́тами спаси́ і поми́луй нас, погиба́ющих. Да́руй нам ісправле́ніє гріхо́вния жи́зні на́шея і ізба́ви нас от скорбе́й, бід і болі́зней, от внеза́пния сме́рті, а́да і ві́чния му́ки. Ти бо, Цари́це і Влади́чице, ско́рая Помо́щниця і Засту́пниця єси́ всім притека́ющим к Тебі́ і крі́пкоє прибі́жище грі́шников ка́ющихся. Пода́ждь у́бо нам, Преблага́я і Всенепоро́чная Ді́во, христия́нський коне́ць житія́ на́шего ми́рен і непости́ден і сподо́би нас Твої́м хода́тайством всели́тися в Оби́телях Небе́сних, іді́же непреста́нний глас пра́зднующих ра́достію сла́вить Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Засту́пнице Усе́рдная, Благоутро́бная Го́спода Ма́ти, к Тебі́ прибіга́ю аз, окая́нний і па́че всіх челові́ко грішні́йший; воньми́ гла́су моле́нія моєго́, вопль мой і стена́ніє усли́ши. Я́ко беззако́нія моя́ превзидо́ша главу́ мою́, і аз, я́коже кора́бль в пучи́ні, погружа́юся в мо́ре гріхо́в мої́х. Но Ти, Всеблага́я і Милосе́рдная Влади́чице, не пре́зри мене́, отча́яннаго і во грісі́х погиба́ющаго; поми́луй м'я, ка́ющагося в злих ді́ліх мої́х, і обрати́ на путь пра́вий заблу́дшую окая́нную ду́шу мою́. На Тебі́, Влади́чице моя́, Богоро́дице, возлага́ю все упова́ніє моє́. Ти, Ма́ти Бо́жия, сохрани́ і соблюди́ м'я под кро́вом Твої́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О Пресвята́я Влади́чице і Богоро́дице, Ви́сшая Херуви́м і Честні́йшая Серафи́м, Богоізбра́нная Отрокови́це, поги́бших Взиска́ніє і всіх скорб'я́щих Ра́досте! Пода́ждь утіше́ніє і нам, в поги́белі і ско́рби су́щим; ра́зві бо Тебе́ іно́го прибі́жища і по́мощі не і́мами. Ти єди́на єси́ ра́дости на́шея Хода́тайця, і я́ко Ма́тер Бо́жия і Ма́ти милосе́рдія, предстоя́щи у Престо́ла Пресвяти́я Тро́йці, мо́жеши нам помощі́, нікто́же бо притека́яй к Тебі́ посра́млен отхо́дить. Усли́ши у́бо і нас ни́ні в день поги́белі і печа́лі пред Твоє́ю іко́ною припа́дающих і со слеза́ми Тебі́ моля́щихся: отжени́ от нас належа́щия на нас ско́рби і бі́ди в сей вре́менній жи́зні, не лише́ни же сотвори́ Твої́м всеси́льним хода́тайством і ві́чния несконча́ємая ра́дости в Ца́рствії Си́на і Бо́га на́шего. Амі́нь."]},{"h":"Молитва четверта","ps":["Цари́це моя́ Преблага́я, Наде́ждо моя́, Богоро́дице, Прия́телище си́рих і стра́нних Предста́тельнице, скорб'я́щих Ра́досте, оби́димих Покрови́тельнице! Зри́ши мою́ біду́, зри́ши мою́ скорб; помози́ мі, я́ко не́мощну, окорми́ м'я, я́ко стра́нна! Оби́ду мою́ ві́си, разріши́ ту, я́ко во́лиши: я́ко не і́мам іни́я по́мощі, ра́зві Тебе́, ні іни́я Предста́тельниці, ні благи́я Уті́шительниці, то́кмо Тебі́, о Богома́ти! Я́ко да сохрани́ши м'я і покри́єши во ві́ки віко́в. Амі́нь."]},{"h":"Молитва п’ята","ps":["О Влади́чице Преблагослове́нная, Защи́тнице ро́да христия́нськаго, прибі́жище і спасе́ніє прибіга́ющих к Тебі́! Вім, воі́стину вім, я́ко зіло́ согріши́х і прогні́вах, Преми́лостивая Госпоже́, рожде́ннаго пло́тію от Тебе́ Си́на Бо́жия. Но і́мам мно́гія о́брази пре́жде мене́ прогні́вавших Єго́ милосе́рдіє: митарі́, блудни́ці і про́чія грі́шники, і́мже даде́ся проще́ніє гріхо́в їх покая́нія ра́ди і іспові́данія. Ти́я у́бо о́брази поми́лованних очесе́м грі́шния ду́ші моєя́ представля́я і на толи́коє Бо́жиє милосе́рдіє, о́ния приє́мшеє, взира́я, дерзну́х і аз грі́шний прибі́гну с покая́нієм ко Твоєму́ благосе́рдію. О, Всеми́лостивая Влади́чице! Пода́ждь мі ру́ку по́мощі і іспроси́ у Си́на Твоєго́ і Бо́га ма́терніми і святі́йшими Твої́ми моли́твами тя́жким мої́м гріхо́м проще́ніє. Ві́рую і іспові́дую, я́ко Той, Єго́же родила́ єси́, Син Твой єсть воі́стину Христо́с, Син Бо́га жива́го, Судія́ живи́х і ме́ртвих, воздая́й коєму́ждо по діло́м єго́; ві́рую же па́ки і іспові́дую Тебі́ би́ти і́стинную Богоро́дицю, милосе́рдія істо́чник, утіше́ніє пла́чущих, взиска́ніє поги́бших, си́льную і непрестаю́шую к Бо́гу хода́таїцю, зіло́ лю́б'ящую род христия́нський, і спору́чницю покая́нія; воі́стину бо ність нам іни́я по́мощі і покро́ва, ра́зві Тебе́, Госпоже́ Преми́лостивая, і нікто́же, упова́я на Тя, постиді́ся когда́, і Тобо́ю умоля́я Бо́га, нікто́же оста́влен бисть. Того́ ра́ди і аз Твою́ неісче́тную бла́гость молю́: отве́рзи две́рі милосе́рдія Твоєго́ мні заблу́ждшему і па́дшему в тимі́ніє глубини́, не возгнуша́йся мене́ скве́рнаго, не пре́зри грі́шнаго моле́нія моєго́, не оста́ви мене́ окая́ннаго, я́ко в поги́бель зло́бний враг похи́тити м'я і́щеть, но умоли́ о мні рожде́ннаго от Тебе́ милосе́рдаго Си́на Твоєго́ і Бо́га, да прости́ть вели́кия моя́ гріхи́ і ізба́вить м'я от па́губи моєя́, я́ко да і аз, со всі́ми получи́вшими проще́ніє, воспою́ і просла́влю безмі́рноє милосе́рдіє Бо́жиє і Твоє́ непости́дноє о мні заступле́ніє в жи́зні сей і в несконча́ємом ві́ці. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Всецариця» (Пантанасса)","e":"Prayer to the Theotokos before her icon “Queen of All” (Pantanassa)","secs":[{"h":"Тропар, глас 4","ps":["О́бразом радостотво́рним че́стния Всецари́ці, / жела́нієм те́плим взиска́ющих благода́ті Твоєя́, спаси́, Влади́чице; / ізба́ви от обстоя́ній к Тебі́ прибіга́ющих, / от вся́кия напа́сти огради́ ста́до Твоє́, / к заступле́нію Твоєму́ взива́ющеє при́сно."]},{"h":"Молитва перша","ps":["О всеблага́я, досточу́дная Богоро́дице, Пантана́сса, Всецари́це! Нісьм досто́їн да вни́деши под кров мой, но я́ко ми́лостиваго Бо́га любоблагоутро́бная Ма́ти, рци сло́во, да ісціли́ться душа́ моя́ і укріпи́ться немощству́ющеє ті́ло моє́. І́маши бо держа́ву непобіди́мую і не ізнемо́жеть у Тебе́ всяк глаго́л, о Всецари́ці! Ти за м'я упроси́, Ти за м'я умоли́, да прославля́ю пресла́вноє і́м'я Твоє́ всегда́, ни́ні і в бесконе́чния ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О Пречи́стая Богома́ти, Всецари́це! Усли́ши многоболі́зненноє воздиха́ніє на́ше пред чудотво́рною іко́ною Твоє́ю, із уде́ла Афо́нськаго в Україну принесе́нною, при́зри на чад Твої́х, неісці́льними неду́ги стра́ждущих, ко свято́му о́бразу Твоєму́ с ві́рою припа́дающих! Я́коже пти́ця крило́ма покрива́єть птенці́ своя́, та́ко і Ти ни́ні, при́сно жива́ су́щи, покри́й нас многоціле́бним Твої́м омофо́ром. Та́мо, іді́же наде́жда ісчеза́єть, несумні́нною Наде́ждою бу́ди. Та́мо, іді́же лю́тия ско́рби превозмога́ють, Терпі́нієм і Осла́бою яви́ся. Та́мо, іді́же мрак отча́янія в душі́ всели́ся, да возсія́єть неізрече́нний світ Божества́! Малоду́шния уті́ши, немощни́я укріпи́, ожесточе́нним сердця́м ум'ягче́ніє і просвіще́ніє да́руй. Ісціли́ боля́щия лю́ди Твоя́, о Всеми́лостивая Цари́це! Ум і ру́ки врачу́ющих нас благослови́, да послу́жать ору́дієм Всемо́щнаго Врача́, Христа́ Спа́са на́шего. Я́ко живі́й Ті, су́щей с на́ми, мо́лимся пред іко́ною Твоє́ю, о Влади́чице! Простри́ ру́ці Твої́, іспо́лненния ісціле́нія і врачби́, Ра́досте скорб'я́щих, в печа́ліх Утіше́ніє, да чудотво́рную по́мощ ско́ро получи́вше, прославля́єм Живонача́льную Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Глинська»","e":"Prayer to the Theotokos before her icon “Glinsk”","secs":[{"h":"Тропар, глас 4","ps":["Днесь благові́рнії лю́діє, осіня́ємії святи́м Богома́тері о́бразом, во умиле́нії глаго́лем: Влади́чице, помози́ рабо́м Твої́м в напа́стіх, ско́рбіх і болі́зніх, обремене́ни бо гріхми́ мно́гими, і ізба́ви ни от вся́каго зла, моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["А́ще і мно́гажди іко́на Твоя́, Богоро́дице, уноси́ма бисть с мі́ста явле́нія, оба́че чуде́сне в пусти́ню возвраща́шеся, отону́дуже всім ві́рним подає́ть бла́го потре́бноє."]},{"h":"Молитва перша","ps":["О Пресвята́я Влади́чице, Христа́ Спаси́теля на́шего Богоізбра́нная Ма́ти, у Бо́га святи́ми моли́твами іспро́шенная, Бо́гу посвяще́нная і Бо́гом возлю́бленная! Кто Тебі́ не ублажи́ть іли́ кто не воспоє́ть Твоєго́ пресла́вного рождества́? Рождество́ бо Твоє́ бисть нача́лом спасе́нія челові́ков, і ми, сидя́щиє во тьмі согріше́ній, зрим Тя, Непристу́пнаго Сві́та жили́ще. Сего́ ра́ди вити́йствующий язи́к не мо́жеть пісносло́вити Тя по достоя́нію, па́че бо Серафи́м возви́силася єси́, Пречи́стая. Оба́че прийми́ недосто́йних раб Твої́х ни́нішнєє похвале́ніє і не отри́ни мольби́ на́ші. Твоє́ вели́чіє іспові́дуєм, Тебі́ во умиле́нії припа́даєм і ско́рую в заступле́нії чадолюби́вую і благосе́рдую Ма́тер дерзнове́нно про́сим: умоли́ Си́на Твоєго́ і Бо́га на́шего дарова́ти нам, мно́го согреша́ющим, і́скреннєє покая́ніє і благоче́стноє житіє́, да возмо́жем твори́ти вся Бо́гу уго́дная і душа́м на́шим поле́зная, возненави́дим вся зла́я, укрепля́ємії Боже́ственною благода́тію во благо́м проізволе́нії на́шем. Ти, непости́дная Наде́ждо на́ша, в час сме́рти, да́руй нам христия́нськую кончи́ну, безбі́дноє ше́ствіє на стра́шних мита́рствах возду́шних і наслі́діє ві́чних і неізрече́нних благ Ца́рствія Небе́снаго, да со всі́ми святи́ми немо́лчно іспові́дуєм Твоє́ о нас заступле́ніє і да сла́вим єди́наго І́стиннаго Бо́га, во Святі́й Тро́йці покланя́ємаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["Преблагослове́нная Ді́ва Марі́є, Цари́це Небесе́ і землі́, Твоєму́ чудотво́рному о́бразу припа́дающе, уми́льно глаго́лем: при́зри ми́лостиво на раби́ Твоя́ і Твої́м всеси́льним хода́тайством ниспосли́ кому́ждо потре́бная: вся ві́рная ча́да Святи́я Це́ркви спаси́, неві́рния обрати́, заблу́дшия на путь пра́вий наста́ви, ста́рость і сла́бость сил поддержи́, ю́них во ві́рі свято́й возрасти́, муже́й ко бла́гу напра́ви; грі́шников к покая́нію приведи́ і всіх христия́н мольби́ усли́ши; боля́щия уврачу́й, ско́рби утоли́, путеше́ствующим спутеше́ствуй. Ти ві́си, Всеми́лостивая, я́ко не́мощни, я́ко грі́шни, я́ко озлобля́ємі і досто́йни преще́нія Бо́жия; оба́че бу́ди нам на по́мощ, прельще́нії прогніва́єм Бо́га. Тя і́мами предста́тельницю, Ю́же не отри́неть Госпо́дь, а́ще бо восхо́щеши, вся дарова́ти нам мо́жеши, я́ко благода́тний істо́чник ві́рно пою́щих Тя і превознося́щих пресла́вноє Твоє́ рождество́. Ізба́ви, Влади́чице, гріхопаде́ній і бід всіх благоче́стно призива́ющих Свято́є і́м'я Твоє́ і поклоня́ющихся честно́му о́бразу твоєму́, ти бо моли́твами Свої́ми, беззако́нія на́ша ту́не очища́ющи. Ті́мже тебе́ припа́даєм і па́ки вопіє́м: отжени́ от нас вся́каго врага́ і супоста́та, вся́кия напа́сти і губи́тельния пове́трія, моли́твами Свої́ми подаю́щи дожди́ благовре́менни і землі́ оби́льноє плодоприноше́ніє; вложи́в сердця́ на́ша страх Боже́ственний к ісполне́нію за́повідей Госпо́дніх, да всі в христия́нськой любві́, благоче́стії і чистоті́ благоде́нственно, ти́хо і ми́рно поживе́м во спасе́ніє душ на́ших, во бла́го бли́жніх і во сла́ву Го́спода. Єму́ бо, я́ко Творцю́, Промисли́телю і Спаси́телю на́шему вся́кая подоба́єть сла́ва, честь і поклоне́ніє ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і ду́ші на́ша к Бо́гу возво́диши."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Грузинська» (Красногорська)","e":"Prayer to the Theotokos before her icon “Georgian” (Krasnogorsk)","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється оби́тель Красного́рськая, / і с не́ю ликовству́єть Раї́фськая пу́стиня, / я́ко зарю́ со́лнечную, от восто́ка возсія́вшую, восприї́мши, Влади́чице, / чудотво́рную Твою́ іко́ну, / є́юже разгоня́єши мглу іскуше́ній і бід от вопію́щих ві́рно: / ізба́ви оби́тель на́шу і вся страни́ христия́нськия от всіх наві́т вра́жиїх // і спаси́ ду́ші на́ша, я́ко Милосе́рдная Засту́пниця ро́да христия́нського."]},{"h":"Інший тропар, глас 5","ps":["Веселя́ться правосла́внії наро́ди, / ви́дяще, Влади́чице Ді́во Богоро́дице, / Твою́ пречу́дную і чудотво́рную іко́ну, / і приє́млють врачевство́ душе́вноє і тіле́сноє Твоє́ю ми́лостію всегда́. / Ті́мже і ми, покланя́ющеся о́ній, усе́рдно Тебі́ вопіє́м: / поми́луй, Блага́я Ма́ти, смире́нния раби́ Твоя́ / і ізба́ви нас от вся́каго зла і наві́та вра́жия, / моля́щи Си́на Твоєго́, Го́спода Ісу́са, / да, спа́сшеся зді, Небе́сноє жи́тельство получи́м // человіколю́бієм і благода́тію Єго́."]},{"h":"Кондак, глас 8","ps":["Тебі́, Ізбра́нній от всіх родо́в, Бо́жієй Ма́тері, / благода́рственная пі́нія прино́сим, / прише́ствієм честни́я Твоєя́ іко́ни, раби́ Твої́, Богоро́дице, озаря́ємі, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: / ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Інший кондак, глас 6","ps":["А́ще попуще́нієм Боже́ственним / от рук неві́рних честна́я Твоя́, Влади́чице, іко́на / поруга́нію подве́ржеся / і копіє́м ва́рвар прободе́на бист, / оба́че во страні́ на́шей Правосла́вній / любоче́стно всі́ми прославля́ється / і благогові́йно почита́ється, / сего́ ра́ди Тобо́ю явля́єть сліпи́м зрі́ніє, / глухи́м сли́шаніє, німи́м глаго́ланіє, / хроми́м хожде́ніє, разсла́бленним укріпле́ніє, / ско́рбним утіше́ніє і отра́ду. / Сих ра́ди мо́лим Тя, Ми́лосердная Ма́ти, / до конця́ проба́ви ми́лості Твоя́ на нас, я́ко Блага́я."]},{"h":"Молитва перша","ps":["Прийми́, Всеблагомо́щная Пречи́стая Госпоже́, Влади́чице Богороди́тельнице, сія́ честни́я да́ри от нас, недосто́йних рабо́в Твої́х, к Твоєму́ цільбоно́сному о́бразу пі́ніє возсила́ющих со умиле́нієм, я́ко Тебі́ Само́й су́щей ту і послу́шающей моле́нія на́ша, подаю́щи с ві́рою прося́щим по коєму́ждо проше́нію ісполне́ніє: скорб'я́щим ско́рби облегча́єши, немощни́м здра́віє да́руєши, разсла́бленних і неду́жних ісціля́єши, і от бі́сних бі́си прогоня́єши, оби́димия от оби́д ізбавля́єши, і наси́луємих спаса́єши, грі́шних проща́єши, прокаже́нних очища́єши, і ма́лих діте́й ми́луєши, і непло́дния от непло́дства разріша́єши. Єще́, Госпоже́ Влади́чице, от уз і темни́ць свобожда́єши, і вся́кия многоразли́чния стра́сті ісціля́єши, і о́чния болі́зні уврачу́єши, і от смертоно́сния я́зви ізбавля́єши: вся бо возмо́жна суть хода́тайством Твої́м к Си́ну Твоєму́, Христу́ Бо́гу на́шему. О Всепі́тая Ма́ти, Пречи́стая Богоро́дице! Не преста́й моли́ти о нас, недосто́йних рабі́х Твої́х, сла́в'ящих Тя і почита́ющих, і покланя́ющихся пречи́стому о́бразу Твоєму́, і наде́жду іму́щих невозвра́тну і ві́ру несумне́нну к Тебі́, Присноде́вей, Пресла́вній і Непоро́чній, сла́в'ящих, і чту́щих, і пою́щих Тя во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["К Тебі́, Богоізбра́нная Отрокови́це, Пресвята́я Ді́во Богоро́дице, Небесе́ і землі́ Цари́це, припа́дающе вопіє́м: усли́ши моле́ній на́ших глас і не отврати́ лиця́ Твоєго́ от нас недосто́йних. Прийми́, Всеблага́я, от недосто́йних раб Твої́х, чту́щих всечестно́є і́м'я Твоє́, і с ві́рою покланя́ющихся Тебі́ пред чудотво́рним Твої́м о́бразом, приноси́моє ни́ні те́плоє моле́ніє на́ше: вознеси́ є к Престо́лу Си́на Твоєго́, Христа́ Бо́га на́шего, да ми́лостив бу́деть к непра́вдам на́шим і не возда́сть нам по діло́м на́шим, но да проба́вить щедро́ти Своя́. Ві́ми, я́ко ні́сми досто́йні, по гріхо́м на́шим, от Него́ поми́ловані би́ти, а́ще не Ти, Влади́чице, умо́лиши Єго́ о нас, вся бо мо́жеши іспроси́ти у Него́, ма́тернєє бо к Нему́ і́маши дерзнове́ніє. Сего́ ра́ди к Тебі́, я́ко всемо́щній і всеблаго́й Засту́пниці на́шей прибіга́єм, усе́рдно моля́щеся: іспроси́ у ро́ждшагося от Тебе́ Єдиноро́днаго Си́на Бо́жия, Христа́ Бо́га на́шего, всім нам в святооте́честій Правосла́вній ві́рі тве́рдоє, до конця́ дній на́ших пребива́ніє і во всіх за́повідіх Госпо́дніх неукло́нноє хожде́ніє, да про́чеє вре́м'я живота́ на́шего пожи́вше во вся́ком благоче́стії і чистоті́, сподо́бимся ми́рния христия́нськия кончи́ни і до́браго отві́та на стра́шнім Суді́ Си́на Твоєго́ і Бо́га на́шего і та́ко дости́гнем, под кро́вом Твоєя́ по́мощі, живота́ ві́чнаго во Ца́рствії Отця́ Сві́тов, Єму́же, ку́пно со Єдиноро́дним Єго́ Си́ном і Святи́м Ду́хом, подоба́єть сла́ва, честь і поклоне́ніє, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Державна»","e":"Prayer to the Theotokos before her icon “Derzhavna” (Sovereign)","secs":[{"h":"Тропар, глас 4","ps":["Гра́да Сіо́нська взиску́юще, / под Твой покро́в, Де́ваЧи́стая, днесь притека́єм, / і нікто́же возмо́жеть на ни, / я́ко ність град си́лен, а́ще не Су́щаго Бо́га, // і ність і́на крі́пость, а́ще не ми́лость Влади́чиці Ді́ви."]},{"h":"Інший тропар, глас 4","ps":["А́нгелов ли́ци благогові́йно Тебі́ слу́жать, / і вся Небе́сния си́ли немо́лчними гла́си Тя ублажа́ють, / Богоро́дице Ді́во; / усе́рдно мо́лим Тя, Влади́чице, / да пребу́деть Боже́ственная благода́ть / на честні́й іко́ні Твоє́й Держа́вній, / і світоза́рний луч сла́ви чуде́с Твої́х да нисхо́дить от нея́ / на всіх с ві́рою Тебі́ моля́щихся // і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді победи́тельния пі́сні прино́сим, / я́ко дарова́ся нам Держа́ва Твоя́, і нічесо́же устраші́мся, / не от ми́ра бо спасе́ніє на́ше, / но Превознесе́нния Влади́чиці милосе́рдієм огражда́ємся / і тому́ днесь ра́дуємся, // я́ко приї́де Засту́пниця на стра́жу землі́ Своєя́."]},{"h":"Інший кондак, глас 8","ps":["Взбра́нней Воєво́ді, Засту́пниці на́шей Держа́вній, / пі́сні благода́рственния прино́сим о дарова́нії нам іко́ни Єя́ святи́я, / є́юже огражда́єми, нічесо́же устраші́мся, / не от челові́к бо спасе́ніє на́ше, / но Преблагослове́нния Влади́чиці милосе́рдієм. / Ті́мже днесь ра́дуємся і пра́зднуєм сві́тло, / я́ко приї́де Держа́вная на стра́жу землі́ Своєя́."]},{"h":"Інший кондак, глас 8","ps":["Ізбра́нній от всіх родо́в Засту́пнице ро́да христия́нського, / покро́вом Своєя́ бла́гости покрива́ющей страну́ на́шу правосла́вную, / благода́рственная пі́нія прино́сим Ті, Влади́чице, / о явле́нії нам чу́дния іко́ни Твоєя́ Держа́вния. / Ти же, я́ко Всеми́лостивая Засту́пниця всіх, с ві́рою к Тебі́ притека́ющих, / от вся́ких нас бід свободи́, да зове́м Ті: / ра́дуйся, Ма́тер Бо́жия Держа́вная, / Засту́пнице Усе́рдная ро́да христия́нського."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим Держа́вний о́браз святи́ні Твоєя́, / і́мже подає́ши ве́лію ми́лость // всім, с ві́рою к нему́ притека́ющим."]},{"h":"Інше величання","ps":["Досто́йно єсть / велича́ти Тя, / Богоро́дице, / землі́ Українськия Цари́цю Небе́сную / і люде́й правосла́вних / Влади́чицю Держа́вную."]},{"h":"Молитва перша","ps":["О Держа́вная Влади́чице Пресвята́я Богоро́дице, на об'я́тіях Свої́х держа́щая Содержа́щаго дла́нію всю вселе́нную Царя́ Небе́снаго! Благодари́м Тя за неізрече́нноє милосе́рдіє Твоє́, я́ко благоволи́ла єси́ яви́ти нам, грі́шним, сію́ святу́ю і чудотво́рную іко́ну Твою́ во дні сії́. Благодари́м Тя, Засту́пнице, я́ко призрі́ла єси́ с висоти́ святи́я Своєя́ на чад правосла́вних, і, я́ко со́лнце сві́тлоє, увеселя́єши ізнемо́гшия от печа́лі очеса́ на́ша пресла́достним зрі́нієм держа́вного о́браза Твоєго́. О, Преблагослове́нная Ма́тер Бо́жия, Держа́вная Помо́щнице, Крі́пкая Засту́пнице, благодаря́ще Тя, со стра́хом і тре́петом, я́ко раби́ непотре́бнії, ми припа́даєм, со умиле́нієм, с сокруше́нієм серде́чним, со слеза́ми мо́лим Тя: вкорени́ в сердця́ всіх нас пра́вду, мир і ра́дость о Ду́сі Свя́те: водвори́ в страні́ на́шей тишину́, благоде́нствіє, безм'яте́жіє, любо́в друг ко дру́гу нелицемі́рную! Держа́вою Твоє́ю всеси́льною поддержи́ нас, сла́бих, малоду́шних, немощни́х, уни́лих, подкріпи́, возста́ви! Я́ко да под держа́вою Твоє́ю всегда́ храни́мі, поє́м, велича́єм і сла́вим Тя, Держа́вную Засту́пницю ро́да христия́нського во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О ми́ра Засту́пнице, Ма́тер Всепі́тая со стра́хом, ві́рою і любо́вію припа́дающе пред честно́ю іко́ною Твоє́ю Держа́вною, усе́рдно мо́лим Тя: не отврати́ лиця́ Твоєго́ от прибіга́ющих к Тебі́, умоли́, Милосе́рдная Ма́тер Сві́та, Си́на Твоєго́ і Бо́га на́шего, Сладча́йшего Го́спода Ісу́са Христа́, да сохрани́ть в ми́рі страну́ на́шу, да утверди́ть держа́ву на́шу в благоде́нствії, да ізба́вить нас от междоусо́бния бра́ні і укріпи́ть Святу́ю Це́рков на́шу Правосла́вную, да непози́блему соблюде́ть ю от неві́рія, раско́ла і єресе́й. Не і́мами бо іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Пречи́стая Ді́во: Ти єси́ Всеси́льная христия́н Засту́пниця пред Бо́гом, пра́ведний гнів Єго́ ум'ягча́ющая. Ізба́ви всіх, с ві́рою Тебі́ моля́щихся, от паде́ній гріхо́вних, от наві́та злих челові́к, от гла́да, скорбе́й і болі́зней. Да́руй нам дух сокруше́нія, смире́ніє се́рдця, чистоту́ помишле́ній, ісправле́ніє гріхо́вния жи́зні і оставле́ніє согріше́ній на́ших, да всі, благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго Ца́рствія і та́мо со всі́ми святи́ми просла́вим Пречестно́є і великолі́поє І́м'я в Тро́йці сла́вимаго Бо́га: Отця́, Си́на і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Донська»","e":"Prayer to the Theotokos before her icon “Don”","secs":[{"h":"Тропар, глас 4","ps":["Засту́пнице ві́рних Преблага́я і Ско́рая, / Пречи́стая Богоро́дице Ді́во! / Мо́лим Тя пред святи́м і чудотво́рним о́бразом Твої́м, / да, я́коже дре́вле от него́ заступле́ніє Твоє́ / граду Києву дарова́ла єси́, / та́ко і ни́ні нас от вся́ких бід і напа́стей ми́лостивно ізба́ви, // і спаси́ ду́ші на́ша, я́ко Милосе́рдая."]},{"h":"Інший тропар, глас 4","ps":["Всепі́тая і Всесла́вная Цари́це Богоро́дице, / Ма́ти всея́ тва́рі Соді́теля, / христия́нськая наде́ждо і Засту́пнице, / ненаде́ющимся і отча́явшимся ско́роє наді́яніє, мо́лим Тя: / ми́лостива бу́ди нам, грі́шним, / не оста́ви раб Твої́х і не отри́ни моле́нія недосто́йних. / Мо́лимся, взира́юще ко о́бразу Твоєму́ честно́му / святи́я і чудотво́рния іко́ни Твоєя́ і вопію́ще: / с пла́вающими і путеше́ствующими да пребу́деть ми́лость Твоя́. / О Влади́чице, ри́зою Твоє́ю честно́ю защити́, / і во вся́ких мі́стіх злих ві́рния соблюди́, / і моли́ся к Ро́ждшемуся із Тебе́ Христу́ Бо́гу на́шему, //  / да спасе́ть от гріх ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті, раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: / ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Інший кондак, глас 2","ps":["В Небе́сния оби́телі пресели́вшаяся с пло́тію, / су́щия на землі́ ніка́коже оста́вила єси́, Богоро́дице, / о́браз Боже́ственний і многочуде́сний Пречи́стаго Лиця́ Твоєго́ / зрі́ти лю́б'ящим Тя і покланя́тися дарова́ла єси́, / я́ко зна́меніє Твоєя́ благода́ті; // чтим єго́, лобиза́юще."]},{"h":"Молитва перша","ps":["О Всеми́лостивая Ма́ти, Пречи́стая Ді́во Богоро́дице! Ти єси́ світ ума́ моєго́, ра́дость се́рдця моєго́, си́ла во́лі моєя́. Усли́ши і прийми́ моле́ніє моє́. При́зри на я́зви душі́ і ті́ла моєго́, обогати́хся страстьми́, обнища́х смире́нієм. Іспо́лнен єсьм студа́ за зла́я діла́ і трепе́щу Суда́ Бо́жия. Гріси́ ю́ности, забве́ннії і утає́ннії гріси́ отягча́ють со́вість мою́. Оми́й м'я струя́ми сле́зними, сніми́ бре́м'я тя́жкоє, гріхо́вноє, да сотворю́ плоди́ досто́йния покая́нія. Те́рнієм скорбе́й уси́пан єсть путь мой. Вім, я́ко пра́вда Бо́жия наказу́єть м'я. Умоли́ милосе́рдіє Бо́жиє о мні, при́зри на сле́зи моя́ і іспра́ви і спаси́ м'я і ча́да моя́, бу́ди мі сокро́вище ві́ри і храни́лище благоче́стія. Да́руй несокруши́моє терпі́ніє в біда́х, от ві́ри проістека́ющеє, отими́ дух пра́здности, уни́нія, любонача́лія. Ізгони́ гнів, за́висть, пам'ятозло́біє, нечистоту́, лі́ность, си́ми і бо́льшими поро́ки неду́гуєть душа́ моя́. Примири́ вражду́ющия, оправда́й оклеве́танния. Просвіти́ нас сві́том Си́на Твоєго́ і даждь нам глаго́лати сло́во і́стини, тве́рдоє в пра́вді, ми́рноє любве́ ра́ди, растворе́нноє благоразу́мієм. Посіти́ в болі́зніх і печа́ліх су́щих, да всі, под держа́вним покро́вом Твої́м сохраня́ємі, безбі́дно Ца́рствія Небе́снаго дости́гнем, хвалу́ воздава́юще за вся Человіколю́бцю Бо́гу. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Влади́чице, Ді́во Богоро́дице, Засту́пнице на́ша блага́я і ско́рая! Воспіва́єм Ті всі благода́рственная за чу́дная діла́ Твоя́. Пісносло́вим от літ дре́вніх неот'є́млемоє заступле́ніє Твоє́ граду Києву і страні́ на́шей, чудотво́рним о́бразом Твої́м Донськи́м всегда́ явля́ємоє: в бі́гство обраща́ються полці́ чужди́х, гра́ди і ве́сі невреди́ми сохраня́ються, лю́діє же от лю́тия сме́рті ізбавля́ються. Осуша́ються о́чі слезя́щеї, умолка́ють стена́нія ві́рних, плач в ра́дость о́бщую претворя́ється. Бу́ди і нам, Пречи́стая Богоро́дице, утіше́ніє в бе́дствіїх, возрожде́ніє наде́жди, о́браз му́жества, істо́чник ми́лости і в ско́рбних обстоя́ніїх неістощи́моє терпі́ніє нам да́руй. Пода́ждь коєму́ждо по проше́нію і ну́жді єго́: младе́нці воспита́й, ю́ния уцілому́дри і стра́ху Бо́жию научи́, унива́ющия обо́дри і не́мощную ста́рость поддержи́. Посіти́ в болі́зніх і печа́ліх су́щия, зла́я сердца́ ум'ягчи́, братолю́біє укріпи́, ми́ра і любве́ всіх нас іспо́лни. Примири́, Благосе́рдая Ма́ти, вражду́ющия і оправда́й оклеве́танния. Істреби́ поро́ки, да не восхо́дять гріси́ на́ші пред Судіє́ю вся́чеських, да не пости́гнеть нас пра́ведний гнів Бо́жий. Твої́ми моли́твами, всемо́щним Твої́м покро́вом огради́ нас от наше́ствій вра́жиїх, от гла́да, губи́тельства, огня́, меча́ і вся́каго іно́го злострада́нія. Упова́єм моли́твами Твої́ми получи́ти от Всеви́шняго Бо́га гріхо́в проще́ніє і ізглажде́ніє і с Бо́гом примире́ніє. Умоли́ стяжа́ти нам Ца́рствіє Небе́сноє і по сконча́нії жи́зні на́шея одесну́ю Престо́ла Бо́жия ста́ти, іді́же Ти, о Всепі́тая Ді́во, Святі́й Тро́йці во ві́чній сла́ві предстої́ши. Удосто́й і нас с ли́ки А́нгелов і святи́х та́мо восхвали́ти Пречестно́є І́м'я Си́на Твоєго́, со Безнача́льним Єго́ Отце́м і Всесвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О Всеми́лостивая Ма́ти, Пречи́стая Ді́во Богоро́дице! Усли́ши і прийми́ моле́ніє моє́. При́зри на я́зви душі́ і ті́ла моєго́, гріси́ ю́ности, забве́ннії і утає́ннії, отягча́ють со́вість мою́, оми́й м'я струя́ми сле́зними, сніми́ бре́м'я тя́жкоє, укріпи́ м'я, да сотворю́ плоди́ досто́йния покая́нія. Те́рнієм скорбе́й уси́пан єсть путь мой. Вім, я́ко пра́вда Бо́жия нака́жеть м'я, умоли́ милосе́рдіє Бо́жиє о мні. При́зри на стена́ніє моє́, і іспра́ви путь мой, і спаси́ м'я і ча́да і бли́жнія моя́. Бу́ди мі сокро́вище ві́ри і Храни́тельниця благоче́стія. Да́руй несокруши́моє терпі́ніє в біда́х, от ві́ри проістека́ющеє. Ізгони́ гнів, за́висть, уни́ніє, пам'ятозло́біє, нечистоту́, лі́ность; си́ми і бо́льшими поро́ки неду́гуєть душа́ моя́! Примири́ вражду́ющих, оправда́й оклеве́танних, просвіти́ нас, Влади́чице, сві́том Си́на Своєго́ і даждь нам глаго́лати друго́м і ча́дом свої́м сло́во і́стини, тве́рдоє в пра́вді, ми́рноє любве́ ра́ди, растворе́нноє благоразу́мієм, посіти́ в болі́зніх і печа́ліх су́щих, да всі, под держа́вним покро́вом Твої́м сохраня́ємі, безбі́дно Ца́рствія Небе́снаго дости́гнем, хвалу́ воздаю́ще за вся Человіколю́бцю Бо́гу всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["Ко кому́ возопію́, Влади́чице, ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач мой і воздиха́ніє моє́ при́йметь, а́ще не Ти, Пренепоро́чная, наде́ждо христия́н і прибі́жище нам, грі́шним? Кто па́че Тебі́ в несча́стіях защити́ть? Усли́ши у́бо стена́ніє моє́, і приклони́ у́хо Твоє́ ко мні, Влади́чице Ма́ти Бо́га моєго́, і не пре́зри м'я, тре́бующаго Твоєя́ по́мощі, і не отри́ни мене́ грі́шнаго. Вразуми́ і научи́ м'я, Цари́це Небе́сная, не отступи́ от мене́, раба́ Твоєго́, Влади́чице, за ропта́ніє моє́, бу́ди мні Мать і покрови́тельниця. Вруча́ю себе́ ми́лостивому покро́ву Твоєму́, а́ще то́кмо восхо́щеши устро́їти о мні. Приведи́ м'я, грі́шнаго, к ти́хой і безм'яте́жной жи́зні, да пла́чуся о греха́х мої́х. Уви́ мні, ко кому́ прибі́гну пови́нний аз, то́кмо к Тебі́, упова́нію і прибі́жищу грі́шних, в наде́жді на неізрече́нную ми́лость Твою́ і щедро́ти? Ко́є ли сло́во за преступле́нія моя́ ізрещи́ возмогу́ к вели́честву сла́ви Твоєя́? О, Влади́чице, Цари́це Небе́сная, Ти мні Ма́ти і наде́жда, Ти мі упова́ніє і прибі́жище, покро́в, заступле́ніє і по́мощ. Цари́це моя́ Преблага́я і преби́страя Засту́пнице, покро́й Свої́м хода́тайством моя́ прегріше́нія, защити́ мене́ от враг ви́димих і неви́димих; ум'ягчи́ сердця́ злих челові́к, возстаю́щих на м'я. О, Ма́ти Го́спода моєго́ Творця́, Ти ко́рень ді́вства і неув'яда́ємий цвіт чистоти́. О, Богороди́тельнице, Ти пода́ждь мі по́мощ немощству́ющему плотськи́ми страстя́ми і болі́знующему се́рдцем: єди́но бо Твоє́, і с Тобо́ю Твоєго́ Си́на і Бо́га на́шего, імі́ю заступле́ніє, і Твої́м пречу́дним заступле́нієм да опра́вдан бу́ду, і да ізба́влюся от вся́кия біди́ і напа́сти всеси́льними Твої́ми моли́твами, Всечи́стая, і Непоро́чная, і Пресла́вная Бо́жия Ма́ти Марі́є. Ра́дуйся, Благода́тная, ра́дуйся, Обра́дованная, ра́дуйся, Преблагослове́нная, Госпо́дь с Тобо́ю. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже ди́вную побі́ду на ага́ряни правосла́вним дарова́ла єси́."]},{"h":"Інше величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже заступле́ніє ди́вноє гра́ду Твоєму́ дарова́ла єси́."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Достойно є» («Милуюча»)","e":"Prayer to the Theotokos before her icon “It Is Truly Meet” (“The Merciful”)","secs":[{"h":"Тропар, глас 4","ps":["Отце́во все Афо́нськоє мно́жество, / собері́теся, ві́рно пра́зднующе, / днесь ра́дующеся і сві́тло восклиця́юще всі во весе́лії, / Бо́жия бо Ма́ти ни́ні от А́нгела пресла́вно воспіва́ється. // Ті́мже, я́ко Бого́родицю, при́сно Сію́ сла́вим."]},{"h":"Інший тропар, глас 4","ps":["Притеце́м, ві́рнії, со дерзнове́нієм / к Ми́лующей Цари́це Богоро́дице / і умиле́нно воззове́м к Ней: / низпосли́ на ни ми́лості Твоя́ бога́тия: / град сей ізба́ви от вся́каго обстоя́нія, / мир да́руй ми́рові // і спасе́ніє душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Притеце́м, ві́рнії, со дерзнове́нієм / к ми́лующей Цари́це Богоро́дице / і уми́льно воззове́м к Ней: / низпосли́ на ни ми́лості Твоя́ бога́тия: / Це́рков на́шу сохрани́, / лю́ди во благоде́нствії соблюди́, / зе́млю на́шу ізба́ви от вся́каго обстоя́нія, / мир да́руй ми́рові // і спасе́ніє душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Пра́зднуєть днесь весь Афо́н, / я́ко піснь прия́т от А́нгела чу́дно / Тебі́, Чи́стій Богома́тері, // Ю́же вся твар чтить, сла́вящи."]},{"h":"Інший кондак, глас 8","ps":["Арха́нгельський глас вопіє́м Ті, Всецари́це: / досто́йно єсть, я́ко воі́стину, / блажи́ти Тя, Богоро́дицю, / Присноблаже́нную і Пренепоро́чную, // і Ма́тер Бо́га на́шего."]},{"h":"Молитва","ps":["О Пресвята́я і Преми́лостивая Влади́чице Богоро́дице! Припа́дая к святі́й іко́ні Твоє́й, смире́нно мо́лимся Тебі́, воньми́ гла́су моле́нія на́шего, виждь ско́рби, виждь біди́ на́ша і, я́ко любвеоби́льная Ма́ти, потщи́ся на по́мощ нам безпо́мощним, умоли́ Си́на Твоєго́ і Бо́га на́шего: да не погуби́ть нас за беззако́нія на́ша, но яви́ть нам человіколю́бно свою́ ми́лость. Іспроси́ нам, Влади́чице, у бла́гости Єго́ тіле́сноє здра́віє і душе́вноє спасе́ніє, і ми́рноє житіє́, землі́ плодоно́сіє, возду́ха благорастворе́ніє, і благослове́ніє сви́ше на вся блага́я діла́ і начина́нія на́ша. І я́коже дре́вле призрі́ла єси́ ми́лостиво на смире́нноє славосло́віє послу́шника Афо́нськаго, воспева́вшего Тя пред пречи́стою іко́ною Твоє́ю і посла́ла єси́ к нему́ А́нгела научи́ти єго́ пі́ти піснь небе́сную, є́юже славосло́в'ять Тя А́нгели; та́ко і ни́ні прийми́ на́ше усе́рдноє молитвосло́віє, Тебі́ приноси́моє. О Цари́ці Всепі́тая! Простри́ ко Го́споду богоно́сния Твоя́ ру́ці, і́миже Богомладе́нця Ісу́са Христа́ носи́ла єси́, і умоли́ Єго́ ізба́вити нас от вся́каго зла. Яви́, Влади́чице, Твою́ ми́лость к нам: боля́щия ісціли́, скорб'я́щия уті́ши, бе́дствующим помози́ і сподо́би нас благоче́стно житіє́ сіє́ земно́є соверши́ти, христия́нськую непости́дную кончи́ну получи́ти і Небе́сноє Ца́рствіє наслі́дити ма́тернім хода́тайством Твої́м к Ро́ждшемуся от Тебе́ Христу́ Бо́гу на́шему, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Досто́йно єсть / велича́ти Тя, / Богоро́дице, / Честні́йшую Херуви́м / і Сла́внійшую // без сравне́нія Серафи́м."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Єлецька-Харківська»","e":"Prayer to the Theotokos before her icon “Yelets-Kharkiv”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, грі́шнії і смире́ннії, і припаде́м, в покая́нії зову́ще із глубини́ ду́ші: Влади́чице, помози́, на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тя бо і єди́ну наде́жду і́мами."]},{"h":"Інший тропар, глас 6","ps":["Твоєго́ милосе́рдія дарова́нія воспомина́юще, Влади́чице, / і Твой чудотво́рний о́браз благогові́йно лобиза́юще, / упова́нієм же Твоєя́ по́мощі сердця́ на́ша веселя́ще, а́ки среди́ нас пребива́ющую Тя помишля́єм / і ві́рою Тебі́ вопіє́м: / Твоєго́ моли́ Си́на і Го́спода, / да научи́ть нас за́повіді Єго́ всегда́ твори́ти / і зли́я іскуше́нія побіжда́ти, / і Тебі́, Предста́тельницю на́шу, / досто́йно пі́ти і сла́вити во ві́ки."]},{"h":"Кондак, глас 5","ps":["На неув'яда́ємом дре́ві уго́днику яви́вшися, / Твоє́ же предста́тельство всім моля́щимся при́сно явля́ющи, Влади́чице, / і на́шего не отврати́ смире́ннаго моле́нія, / но прегріше́ній на́ших проще́нія іспроси́ / і, ско́рби душ на́ших от'є́мши, / благода́рственноє на́ше прийми́ поклоне́ніє, / да любо́вію Тя во ві́ки сла́вим, Всепі́тая."]},{"h":"Молитва","ps":["Премилосе́рдая на́ша Засту́пнице, і душ на́ших блага́я Храни́тельнице, і тіле́с на́ших милосе́рдая Ціли́тельнице, Богоро́дице Ді́во! Ві́ми, я́ко недосто́йни єсьми́, не то́чію Твої́х дарова́ній прича́стници би́ти, но і оче́й свої́х на чудотво́рний Твой о́браз возвісти́, зане́ ду́ші на́ша гріхо́в іспо́лнени суть і о́чі зави́стними і блу́дними воззрі́ньми оскверне́ні суть. Оба́че Твоє́ сострада́ніє челові́ком, в ну́ждах і ско́рбіх пребива́ющим, воспомина́юще, їм же Твоєго́ Боже́ственнаго Си́на на пе́рвоє чу́до в Ка́ні Галиле́йстій преклони́ла єси́, і да́же до днесь Того́ пра́ведний гнів от грі́шников отвраща́єши, па́ки і па́ки на мольбу́ Тебі́, пред чудотво́рним Твої́м о́бразом, подвиза́ємся і со смире́нним упова́нієм Тебі́ про́сим: іспроси́ гріхо́м на́шим проще́ніє, от па́губних страсте́й ісціле́ніє, от нечу́вствія і от сна духо́внаго пробужде́ніє і о доброді́теліх христия́нських ре́вность. Си́ми у́бо дарова́ньми ду́ші на́ша укра́сивши, ізба́ви нас от го́рестей в уни́ніє некре́пкая сердця́ на́ша поверга́ющих, ісціли́ болі́зні моля́щихся і о ни́хже моли́тву ті́ї прино́сять, от напра́сния сме́рті жизнь на́шу сохрани́ і сію́ христия́нською кончи́ною во вре́м'я подо́бно увеча́ти сподо́би. Но і земно́є на́ше пребива́ніє от взаї́мния зло́би і за́висти огради́, і в любві́ Христо́вой сіє́ препровожда́ти нам помози́. Це́рков Си́на Твоєго́ во всей вселе́нній умно́жи і утверди́, єретико́м обраще́ніє ко і́стині іспроси́, язи́ком же неві́рним ві́ри і́стинноє позна́ніє. Та́кожде і одолі́ніє на враги́ і супоста́ти да́руй, і всіх нас научи́, я́коже во дні весе́лія, та́ко і во дні печа́лі Тебі́ прославля́ти і о всіх Си́на Твоєго́ благодари́ти, житіє́ своє́ в Єго́ святу́ю во́лю вруча́ти со упова́нієм ві́чнаго спасе́нія ожида́ти, да і та́мо просла́вим Єго́ пресвято́є І́м'я і Твоє́ милосе́рдоє предста́тельство во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Жировицька»","e":"Prayer to the Theotokos before her icon “Zhyrovichy”","secs":[{"h":"Тропар, глас 5","ps":["Пред свято́ю Твоє́ю іко́ною, Влади́чице, / моля́щіїся ісціле́ній сподобля́ються, / ві́ри і́стинния позна́ніє приє́млють / і ага́рянськая наше́ствія отража́ють. / Ті́мже і нам, к Тебі́ припа́дающим, / гріхо́в оставле́нія іспроси́, / по́мислами благоче́стія сердця́ на́ша просвіти́ / і к Си́ну Твоєму́ моли́тву вознеси́ // о спасе́нії душ на́ших."]},{"h":"Інший тропар, глас 2","ps":["По́мощі от Тебе́ тре́бующия не пре́зри, Влади́чице, / і милосе́рдія бе́здну отве́рзи всім, / притека́ющим к цільбоно́сній іко́ні Твоє́й. / Печа́лі на́ша жите́йськія утоли́, Всеще́драя, / і от юдо́лі сея́ плаче́вния / к ра́дости ві́чній ві́рния Твоя́ преста́ви: / Тебі́ бо всі стяжа́хом, наде́жду і утвержде́ніє, // ми́лости істо́чник, покро́в і спасе́ніє душ на́ших."]},{"h":"Кондак, глас 4","ps":["Вели́чія Твоя́ кто іспові́сть, / Пресвята́я Ді́во, / Творця́ всіх Христа́ Бо́га Ро́ждшая? / Єди́на бо єси́ Ма́ти і Ді́ва, / Преблагослове́нная і Препросла́вленная, / упова́ніє на́ше, істо́чник благости́ні, // ві́рним прибі́жище і ми́ру спасе́ніє."]},{"h":"Молитва перша","ps":["О Премилосе́рдная Госпоже́, Ді́во Богоро́дице! Кі́їма устна́ма прикосну́ся ко святи́ні Твоє́й іли́ ки́їми словеси́ іспові́м щедро́ти Твоя́, лю́дем явля́ємия: нікто́же бо, притека́яй к Тебі́, отхо́дить тощ і не усли́шан. От ю́ности моєя́ взиска́х по́мощі і заступле́нія Твоєго́ і ніколи́же лише́н бих милосе́рдія Твоєго́. Зри́ши, Госпоже́, ско́рбі се́рдця моєго́ і я́зви душі́ моєя́ ві́си. І ни́ні, колінопреклоне́нно предстоя́ пред пречи́стим Твої́м о́бразом, моле́нія моя́ приношу́ Ті: не лиши́ м'я всеси́льнаго хода́тайства Твоєго́ в день ско́рби моєя́ і в день печа́лі моєя́ заступи́ м'я. То́ка слез мої́х не отврати́ся, Влади́чице, і ра́дости моє́ се́рдце іспо́лни. Прибі́жище і предста́тельство бу́ди мні, Ми́лостивая, і сві́та Твоєго́ заря́ми ум мой просвіти́. І не то́кмо молю́ Тя о себі́, но і о лю́діх, притека́ющих к заступле́нію Твоєму́. Це́рков Си́на Твоєго́ во бла́гости соблюди́ і огради́ ю от злоко́зненних наві́тов враг, возстаю́щих на ню. Архипа́стирем на́шим посли́ по́мощ Твою́ во апо́стольстві і сохрани́ їх здра́ви, долгоде́нствующи, пра́во пра́в'ящи сло́во і́стини Госпо́дні. Па́стирем іспроси́ у Бо́га, Си́на Твоєго́, ре́вность і бді́ніє о душа́х вруче́ннаго їм ста́да слове́снаго і дух ра́зума і благоче́стія, чистоти́ і пра́вди Боже́ственния їм низпосли́. Іспроси́ та́кожде, Влади́чице, у Го́спода власте́м предержа́щим і градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, всім же, притека́ющим к Тебі́, дух цілому́дрія, смиренному́дрія, терпі́нія і любве́. Єще́ же молю́ Тя, Премилосе́рдная, осіни́ страну́ на́шу кро́вом Твоєя́ благости́ні і ізба́ви ю от бі́дствій стихи́йних, наше́ствія іноплеме́нников і междоусо́бних нестроє́ній, да всі, живу́щії в ней, в любві́ і ми́ре пребива́юще, ти́хоє і безм'яте́жноє житіє́ поживу́ть і, благ ві́чних моли́твами Твої́ми унасле́дивше, возмо́гуть ку́пно с Тобо́ю восхваля́ти Бо́га на Небесі́ во ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О, Всепі́тая і Преблагослове́нная Ді́во, Ма́ти Христа́ Бо́га на́шего, прийми́ моле́нія на́ша Тебі́ прославля́ющих, Тебі́ благодаре́нія принося́щих і почита́ющих честну́ю іко́ну сію́, ю́же от літ дре́вніх в оби́телі Жировицькой явле́нную. Не таї́м благодія́нія Твоя́, Богоро́дице, і па́ки іспові́дуєм, я́ко сія́ іко́на Твоє́й благода́тной си́лой всім, с ве́рой приходя́щим к ней, істоча́єть неоску́дния ми́лості: просвіща́єть сердца́ благоче́стієм, укріпля́єть си́ли осла́бленния і ісціля́єть не́мощі духо́вния і тіле́сния.","О, Всепі́тая Цари́це Небе́сная, прийми́ благода́рственноє пі́ніє і нікогда́ не лиши́ нас Твоєго́ Небе́снаго покро́ва і заступле́нія - вся бо мо́жеть моли́тва Ма́тері к Милосе́рдному Боже́ственному Си́ну, о сем бо вели́ком заступле́нії возвіща́єть нам сія́ ма́лая іко́на, я́ко бесце́нноє сокро́вище, на сем мі́сті обріте́нноє.","Благода́тная Ма́ти Бо́жия, Ти, і в огні́ о́браз сей сохра́ншая, па́ки да́руєши єго́ в зало́г Твоє́й бли́зости к нам і всегда́шняго благода́тнаго заступле́нія.","Пречи́стая Влади́чице, ум'ягчи́ сердця́ на́ша, окамене́нния гріхо́м, да согре́тия благода́тними твої́ми моли́твами іспо́лним Боже́ственния за́повіді Си́на Твоєго́ Го́спода на́шего Ісу́са Христа́, і та́ко дости́гнем несконча́ємаго дне Ца́рствія Бо́жия, в онь же ми при́звани со всі́ми святи́ми. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і почита́єм честну́ю іко́ну Твою́, / ю́же от літ дре́вніх // во оби́телі Жиро́вицькой просла́вила єси́."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Живоносне Джерело»","e":"Prayer to the Theotokos before her icon “The Life-giving Spring”","secs":[{"h":"Тропар, глас 4","ps":["Почерпе́м, челові́ци, / цільби́ душа́м і ті́лом моли́твою, / Ріка́ бо всім предтече́ть – Пречи́стая Цари́ця Богоро́диця, / істоча́ющи нам чу́дную во́ду / і ізмива́ющи серде́ць че́рності, / гріхо́вния стру́пи очища́ющи, / ду́ші же освяща́ющи ві́рних // Боже́ственною благода́тію."]},{"h":"Інший тропар, глас 2","ps":["Істо́чник єси́ воі́стину / води́ живи́я, Влади́чице, / неду́ги бо душ і тіле́с лю́тия / прикоснове́нієм єди́ним Твої́м ізмива́єши, // Во́ду спасе́нія Христа́ ізлива́ющи."]},{"h":"Кондак, глас 8","ps":["От неістощи́мия / Ти, Істо́чниче Богоблагода́тний, подає́ши мі, точа́щи, во́ди / Твоєя́ благода́ті, / приснотеку́щий па́че сло́ва, / я́ко бо Сло́во ро́ждшая па́че сми́сла, / молю́тися, ороси́ м'я благода́тію, да зову́ Ті: // ра́дуйся, Водо́ спаси́тельная."]},{"h":"Молитва перша","ps":["О Пресвята́я Ді́во, Всеми́лостивая Госпоже́ Влади́чице Богоро́дице, Живоно́сний Істо́чник Твой, целе́бниє да́ри на здра́віє душ і тіле́с на́ших і на спасе́ніє ми́ру точа́щий, подала́ єси́ нам, ті́мже благода́рні су́ще усе́рдно мо́лим Тя, Цари́це Пресвята́я: моли́ Си́на Твоєго́ і Бо́га на́шего да́ти нам оставле́ніє прегріше́ній і вся́кой душе́ скорбя́щей і озло́бленній ми́лость і утіше́ніє, і от бід, скорбе́й і болі́зней свобожде́ніє. Пода́ждь, Госпоже́, (хра́му сему́ і) сим лю́дем покрове́ніє (і святі́й оби́телі сей соблюде́ніє), гра́ду сохране́ніє, страні́ на́шей от напа́стей ізбавле́ніє і огражде́ніє, да ми́рноє зді поживе́м житіє́, і в бу́дущем ві́ці сподо́бимся ви́діти Тебе́, Засту́пницю на́шу, во сла́ві Ца́рствія Си́на Твоєго́ і Бо́га на́шего, Єму́же сла́ва і держа́ва со Отце́м і Пресвяти́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода на́шего Ісу́са Христа́! Ти єси́ Ма́ти і покрови́тельниця всіх к Тебі́ прибіга́ющих, при́зри с благосе́рдієм на моли́тви грі́шних і смире́нних чад Твої́х. Ти, імену́ємая Живоно́сний Істо́чник благода́тних врачева́ній, ісціли́ болі́зні стра́ждущих і умоли́ Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, да низпосле́ть і всім притекающим к Тебі́ здра́віє душе́вноє і тіле́сноє і, прости́в нам во́льная і нево́льная согріше́нія на́ша, да́руєть нам вся я́же к ві́чній і вре́менній жи́зні потре́бная. Ти єси́ всіх скорб'я́щих ра́дость, усли́ши нас, ско́рбних; Ти єси́ утоле́ніє печа́лі, утоли́ і на́шу печа́ль; Ти єси́ взиска́ніє поги́бших, не попусти́ і нам поги́бнути в бе́здні гріхо́в на́ших, но всегда́ ізбавля́й нас от вся́ких скорбе́й і напа́стей і вся́каго зла́го обстоя́нія. Єй, Цари́це на́ша преблага́я, наде́ждо на́ша несокруши́мая і засту́пнице необори́мая, не отврати́ лиця́ Твоєго́ от нас за мно́жество прегріше́ній на́ших, но простри́ нам ру́ці Ма́терняго милосе́рдія Твоєго́ і сотвори́ с на́ми зна́меніє ми́лости Твоєя́ во бла́го: яви́ нам по́мощ Твою́ і благопоспіши́ во вся́ком ді́лі благо́м. От вся́каго же начина́нія гріхо́внаго і помишле́нія лука́ваго отврати́ нас, да всегда́ сла́вим пречестно́є і́м'я Твоє́, велича́юще Бо́га Отця́ і Си́на Єдиноро́днаго Го́спода Ісу́са Христа́ і Животворя́щаго Свята́го Ду́ха со всі́ми святи́ми во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Знамення»","e":"Prayer to the Theotokos before her icon “of the Sign”","secs":[{"h":"Тропар, глас 4","ps":["Я́ко необори́мую сті́ну і істо́чник чуде́с / стяжа́вше Тя раби́ Твої́, / Богоро́дице пречи́стая, / сопроти́вних ополче́нія низлага́єм. / Ті́мже мо́лим Тя: / мир гра́ду Твоєму́ да́руй // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Честна́го о́браза Твоєго́ зна́меніє / пра́зднующе лю́діє Твої́, Богороди́тельнице, / і́мже ди́вную побі́ду на сопроти́вния гра́ду Твоєму́ дарова́ла єси́. / Ті́мже Тебе́ ві́рою взива́єм: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Молитва перед іконою «Знамення» Корчемна","ps":["О, Пресвята́я Влади́чице Богоро́дице, Небе́снаго Царя́ Ма́ти, Богоізбра́нная Отрокови́це! Ненаде́жних наді́яніє, больни́х ісціле́ніє, си́рим предста́тельнице, скорб'я́щим утіше́ніє і ра́дость, оби́димим покрови́тельнице і всім в біда́х і напа́стях су́щим ско́роє поможе́ніє і заступле́ніє! Помози́, о Ма́ти Бо́жия, і нам грі́шним в ско́рбі на́шей, возвесели́ ра́достію сердца́ люде́й Твої́х; упра́ви в ми́рі і тишині́ жизнь на́шу і не даждь во отча́яніє впа́сти. Ти бо Єди́на єси́ па́че всіх святи́х і па́че всіх Го́рніх умо́в Предста́тельниця на́ша к Бо́гу, я́ко Всеблага́го Царя́ Блага́я Ма́ти. Ті́мже ми, грі́шнії, на Пречи́стий Твой о́браз Зна́менія взира́юще, умиле́нно преклоня́єм колі́на і, благогові́йно лобиза́юще, мо́лим Тя, Благосе́рдая Ма́ти: не отри́ни смире́ннаго моле́нія на́шего і яви́ нам зна́меніє ми́лости Твоєя́: нікто́же бо, к Тебі́ прибіга́я со упова́нієм, ісхо́дить от Тебе́ посра́млен, но про́сить благода́ті і приє́млеть дар к поле́зному проше́нію, прославля́я Си́на Твоєго́ і Бо́га, і Тебі́ с Ним, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва перед іконою «Знамення» Курська-Коренна","ps":["Цари́ця на́ша Преблага́я, наде́ждо на́ша, Богоро́дице, Прия́телище си́рих і стра́нних Предста́тельнице, скорб'я́щих Ра́досте, оби́димих Покрови́тельнице, зри́ши на́шу біду́, зри́ши на́шу скорб; помози́ нам, я́ко не́мощним, окорми́ нас, я́ко стра́нних, оби́ду на́шу ві́си, разріши́ ту, я́ко во́лиши, ізба́ви оте́чество на́ше, стра́ждущую зе́млю Українськую, от лю́таго безбо́жников обстоя́нія, спаси́ і сохрани́ рабо́в Твої́х (ім’я) і всіх нас, зді предстоя́щих і моля́щихся, і покри́й нас от вся́каго зла честни́м Твої́м Омофо́ром, я́ко не і́мами іни́я по́мощі ра́зві Тебе́, ні іни́я Предста́тельниці, ні благи́я Уті́шительниці, то́кмо Тебі́, о Богома́ти, я́ко да сохрани́ши нас і покри́єши во ві́ки віко́в. Амі́нь."]},{"h":"Молитва перед іконою «Знамення» Новгородська","ps":["О Пресвята́я і Преблагослове́нная Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Припа́даєм і поклоня́ємся Тебі́ пред свято́ю чудотво́рною іко́ною Твоє́ю, воспомина́юще ди́вноє зна́меніє Твоєго́ заступле́нія, вели́кому Нову́гра́ду от нея́ явле́нноє во дні ра́тнаго на сей град наше́ствія. Смире́нно мо́лим Тя, Всеси́льная ро́да на́шего Засту́пнице: я́коже дре́вле отце́м на́шим на по́мощ уско́рила єси́, та́ко і ни́ні нас, немощни́х і грі́шних, сподо́би Твоєго́ Ма́терняго заступле́нія і благопопече́нія. Спаси́ і сохрани́, Влади́чице, под кро́вом ми́лости Твоєя́ Це́рков Святу́ю, град Твой, всю страну́ на́шу правосла́вную і всіх нас, припа́дающих к Тебі́ с ві́рою і любо́вію умиле́нно прося́щих со слеза́ми Твоєго́ заступле́нія. Єй, Госпоже́ Всеми́лостивая! Умилосе́рдися на ни, обурева́ємия гріхи́ мно́гими, простри́ ко Христу́ Го́споду Богоприї́мния ру́ці Твоя́ і предста́тельствуй за нас пред бла́гостію Єго́, прося́щи нам проще́нія прегріше́ній на́ших, благоче́стнаго ми́рнаго житія́, благи́я христия́нськия кончи́ни і до́браго отві́та на Стра́шнім Суді́ Єго́, да, спаса́ємі всеси́льними Твої́ми к Нему́ моли́твами, блаже́нство ра́йськоє унаслі́дуєм і со всі́ми святи́ми воспоє́м Пречестно́є і Великолі́поє і́м'я Достопоклоня́ємия Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, і Твоє́ ве́ліє к нам милосе́рдіє во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Досто́йно єсть блажи́ти Тя, / Богоро́дице Ді́во, / честні́йшую Херуви́м / і сла́внійшую без сравне́нія Серафи́м. Іли́: Піснь вся́ку духо́вную принесе́м Богоро́дице."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже ди́вную побі́ду на сопрати́вния // гра́ду Твоєму́ дарова́ла єси́."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой честни́й, / і́мже показа́ла єси́ // пресла́вноє зна́меніє."]},{"h":"Інше величання, що у Великому Новгороді","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой честни́й, / і́мже побі́ду на враги́ дарова́ / гра́ду на́шему."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Іверська»","e":"Prayer to the Theotokos before her icon “Iveron”","secs":[{"h":"Тропар, глас 1","ps":["От святи́я іко́ни Твоєя́, / о Влади́чице Богоро́дице, / ісціле́нія і цільби́ подаю́ться оби́льно, / с ві́рою і любо́вію приходя́щим к ней. / Та́ко і мою́ не́мощ посіти́, / і ду́шу мою́ поми́луй, Блага́я, // і ті́ло ісціли́ благода́тію Твоє́ю, Пречи́стая."]},{"h":"Інший тропар, глас 1","ps":["Де́рзость ненави́дящих о́браз Госпо́день, / і держа́ва нечести́вих безбо́жно в Ніке́ю при́йде, / і по́сланнії безчелові́чно вдови́цю, / благоче́стно чту́щую іко́ну Богома́тере, істязу́ють, / но та́я но́щію с си́ном іко́ну в мо́ре пусти́, вопію́щи: / сла́ва Тебі́, Чи́стая, / я́ко непроходи́моє мо́ре плещи́ своя́ подаде́, // сла́ва правоше́ствію Твоєму́, Єди́на Нетлі́нная."]},{"h":"Кондак, глас 8","ps":["А́ще і в мо́ре вве́ржена бисть свята́я іко́на Твоя́, Богоро́дице, / от вдови́ці, не могу́щия спасти́ сію́ от враго́в, / но яви́лася єсть Храни́тельниця Афо́на / і Врата́рниця оби́телі І́верськия, враги́ устраша́ющая / і в Правосла́вній Українській страні́ // чту́щия Тя от всіх бід і напа́стей ізбавля́ющая."]},{"h":"Інший кондак, глас 4","ps":["Совозсія́ днесь Сві́ту Воскресе́нія світ чи́стия іко́ни Твоєя́, / обоя́ ве́село торжеству́юще вопіє́м: // сохрани́ раб Твої́х благода́тію, Влади́чице."]},{"h":"Молитва перша","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода, Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію душ на́ших при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію поклоня́ющихся пречи́стому о́бразу Твоєму́. Се бо, гріхми́ погружа́ємії і скорбми́ обурева́ємії, взира́юще на Твой о́браз, я́ко живі́й Ті су́щей с на́ми, прино́сим смире́нная моле́нія на́ша. Не і́мами бо ні іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о, Ма́ти, всіх скорб'я́щих і обремене́нних! Помози́ нам, не́мощним, утоли́ скорб на́шу, наста́ви на путь пра́вий нас, заблужда́ющих, уврачу́й і спаси́ безнаде́жних, да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і тишині́ проводи́ти, пода́ждь христия́нськую кончи́ну і на Стра́шнім Суді́ Си́на Твоєго́ яви́ся нам милосе́рдая Засту́пниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко благу́ю Засту́пницю ро́да христия́нськаго, со всі́ми угоди́вшими Бо́гу. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице, прийми́ недосто́йную моли́тву на́шу, і сохрани́ нас от наві́та злих челові́к і от напра́сния сме́рти, і да́руй нам пре́жде конця́ покая́ніє, на моле́ніє на́ше умилосе́рдися, і ра́дость в печа́лі мі́сто да́руй. І ізба́ви нас, Госпоже́, от вся́кия біди́ і напа́сти, ско́рби і печа́лі і от вся́каго зла. І сподо́би нас, грі́шних рабо́в Твої́х, одесну́ю ста́ти во второ́м прише́ствії Си́на Твоєго́, Христа́ Бо́га на́шего, і наслі́дники нас би́ти сподо́би Ца́рствія Небе́снаго і жи́зні ві́чния, со всі́ми святи́ми в бесконе́чниі ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Іверська-Моздоцька»","e":"Prayer to the Theotokos before her icon “Iveron-Mozdok”","secs":[{"h":"Тропар, глас 1","ps":["От святи́я іко́ни Твоєя́, о Влади́чице Богоро́дице, / ісціле́нія і ці́льби подаю́ться оби́льно, / с ві́рою і любо́вію приходя́щим к ней. / Та́ко і мою́ не́мощ посіти́, / і ду́шу мою́ поми́луй, Блага́я, / і ті́ло ісціли́ благода́тію Твоє́ю, Пречи́стая."]},{"h":"Молитва","ps":["О, Всеми́лостивая Госпоже́, Ді́ва Богоро́дице, усли́ши нас, моля́щихся Тебі́, і яви́ нам ско́рую ми́лость Твою́, моли́ Си́на Твоєго́ ско́ро ізба́витися нам от вся́каго зла і сохрани́ лю́ди, благоче́стно прибега́ющия і призива́ющия і́м'я Твоє́ свято́є, от вся́кия напа́сти. Всіх нас сохраня́ющи под кро́вом бла́гости Твоєя́, ри́зою Твоє́ю честно́ю защити́. При́зри на нас призрі́нієм ми́лостивного Твоєго́ заступле́нія і моли́твою Твоє́ю сподо́би нас со Христо́м жи́ти і ра́дості а́нгельськия в небе́сних селе́ніях наслажда́тися. Ти бо єси́, Госпоже́, сла́ва небе́сних і упова́ніє земни́х, Ти на́ша наде́жда і засту́пниця всім, притека́ющим к Тебі́ і Твоєя́ святи́я по́мощі прося́щих. Ті́мже всечестни́й о́браз Твой і руко́ю Твоє́ю держи́маго Вседержи́теля ви́дяще на іко́ні, ра́дуємся грі́шнії, со умиле́нієм припа́даєм і любо́вію сей цілу́єм, ча́юще, Госпоже́, Твої́ми благоприя́тними моли́твами в ми́рі і благоче́стії земни́й путь прейти́ і небе́сния бесконе́чния жи́зні дости́гнути і Трисія́нному Бо́гу со всі́ми, угоди́вшими Єму́, поклоня́тися во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Єрусалимська»","e":"Prayer to the Theotokos before her icon “Jerusalem”","secs":[{"h":"Тропар, глас 4","ps":["Богора́дованная Влади́чице, / препросла́вленная Ма́ти Щедро́т і человіколю́бія, / всеми́лостивая о всем ми́рі Хода́тайце! / Прилі́жно раби́ Твої́ ко Твоєму́ предста́тельству прибіга́єм, / і ко пречу́дному о́бразу Твоєму́ со умиле́нієм припа́дающе мо́лимся: / моли́тву те́плую Си́ну Твоєму́ і Бо́гу на́шему сотвори́, / о Всепі́тая Цари́це Богоро́дице, / да от вся́ких болі́зней і печа́лей нас Тебе́ ра́ди ізба́вить, / і от гріхо́во вся́ких свободи́в, / Ца́рствія Своєго́ Небе́снаго наслі́дники ни пока́жеть: / ве́ліє бо і неізрече́нноє я́ко Ма́ти к Нему́ дерзнове́ніє і́маши, / і вся от Него́ іспроси́ти мо́жеши, // Єди́на во ві́ки преблагослове́нная."]},{"h":"Інший тропар, глас 3","ps":["Твоєго́ предста́тельства увіре́ніє / і милосе́рдія Твоєго́ явле́ніє / іко́на Ієрусали́мская нам, Влади́чице, показа́ся / пред не́ю же ду́ші на́ша в моли́тві ізлива́єм / і ві́рою Тебі́ вопіє́м: / воззри́, Милосе́рдная, на лю́ди Твоя́, / вся ско́рбі на́ша і печа́лі утоли́, / утіше́ніє благо́є в сердця́ на́ша низпосли́ // і спасе́ніє ві́чноє ду́шам на́шим, Пречи́стая, іспроси́."]},{"h":"Кондак, глас 5","ps":["Не отри́ни, о Милосе́рдая Ма́ти, / слез і воздиха́ній на́ших, / но проше́нія на́ша ми́лостивно приї́мши, / пред Ієрусали́мскою іко́ною Твоє́ю / моля́щихся люде́й ві́ру укріпи́, / умиле́нієм сердця́ їх іспо́лни, / і крест земна́го житія́ нести́ їм помози́, // єли́ка бо хо́щеши мо́жеши."]},{"h":"Молитва","ps":["Пресвята́я Госпоже́, Влади́чице Богоро́дице, упова́ніє всіх упова́ющих на Тя, Засту́пнице печа́льних, прибі́жище отча́янних, вдов і сиро́т Пита́тельнице! Усли́ши і поми́луй ни, грі́шния і недосто́йния раби́ Своя́, со умиле́нієм ко пречи́стому Твоєму́ о́бразу припа́дающия: умоли́, Милосе́рдая Влади́чице, Си́на Твоєго́ і Го́спода на́шего Ісу́са Христа́, да отврати́ть от нас пра́ведний гнів Свой, да прости́ть гріхи́ і беззако́нія на́ша, я́ко да сподо́бимся бла́гостію Єго́ сконча́ти житіє́ на́ше в покая́нії і получи́ти ми́лость Єго́ со всі́ми ізбра́нними Єго́, я́ко благослове́нна і препросла́влена єси́ во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Ізбавительниця»","e":"Prayer to the Theotokos before her icon “Deliverer”","secs":[{"h":"Тропар, глас 4","ps":["Ізбавле́ніє Принося́щая всім, / от се́рдця Тебі́ призива́ющим, / принеси́ ізбавле́ніє ско́роє / і нам, в лю́тих біда́х погиба́ющим // і в Тебі́ Єди́ной ізбавле́ніє на́ше на Бо́зі полага́ющим."]},{"h":"Інший тропар, глас 4","ps":["Я́ко пресві́тлая звізда́, / просія́ Боже́ственними чудеси́ / святи́й о́браз Твой, Ізба́вительнице, / луча́ми благода́ті і милосе́рдія Твоєго́ / озари́во в нощі́ скорбе́й су́щих. / Пода́ждь у́бо і нам, Всеблага́я Ді́во, / ізбавле́ніє от бід, / ісціле́ніє неду́гов душе́вних і тіле́сних, // спасе́ніє і ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Ко іко́ні Твоє́й, Пресвята́я Госпоже́, / бе́дствовавшії с ві́рою прите́кше, / заступле́нієм Твої́м ізба́вишася от злих, / но я́ко Ма́тер Христа́ Бо́га, / і нас свободи́ от лю́тих обстоя́ній, / вре́менних і ві́чних, да зове́м Ті: // ра́дуйся, Ізба́вительнице на́ша от всіх бід."]},{"h":"Молитва","ps":["О, Ма́ти Бо́жия, по́моще і защи́та на́ша, єгда́ попро́сим, бу́ди ізба́вительнице на́ша, на Тя бо упова́єм і всегда́ вседу́шно Тя призива́єм: умилосе́рдися і помози́, пожале́й і ізба́ви, приклони́ у́хо Твоє́ і на́ші ско́рбния і сле́зния моли́тви прийми́, і я́коже хо́щеши, успоко́й і обра́дуй нас, лю́б'ящих твоєго́ Безнача́льного Си́на і Бо́га на́шего. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Ізборська»","e":"Prayer to the Theotokos before her icon “Izborsk”","secs":[{"h":"Тропар, глас 4","ps":["Я́ко звізда́ пресві́тлая, возсія́ во гра́ді Ізбо́рске / о́браз честни́й Твой, Богоро́дице Ді́во, / от него́же іногда́ із обою́ о́чію теча́ху сле́зи, я́ко струя́, / єго́же тогда́ ви́дівше, наро́ди ізбо́рстії, / му́жи і же́ни с ча́ди, с пла́чем моля́хуся к нему́, / ми же, взира́юще уми́льно, си́це глаго́лем: / о Пресвята́я Влади́чице Богоро́дице, / не забу́ди нас, грі́шних раб Свої́х, / моля́щихся Христу́, Бо́гу на́шему, спасти́ся нам."]},{"h":"Кондак, глас 8","ps":["Засту́пнице христия́ном усе́рдная / і Предста́тельнице гра́ду на́шему Ізбо́рську непости́дная, / не пре́зри моле́нія нас, грі́шних, / я́коже іногда́ от Твоєго́ честна́го о́браза / сле́зи істочи́ла єси́ із обою́ о́чію, моля́щися прилі́жно, / но предвари́, я́ко Блага́, на по́мощ на́шу, / ві́рно к Тебі́ припа́дающих, / усли́ши на́ша моле́нія, Богоро́дице, / ізба́ви нас от нахожде́нія пога́них, от вся́каго зла, / ускори́ же на моли́тву на́шу і потщи́ся на умоле́ніє, / заступа́ющи при́сно, Богоро́дице, чту́щих Тя і вопію́щих Ті: / ра́дуйся, Ді́во, христия́ном похвало́."]},{"h":"Молитва","ps":["О Всесвята́я Влади́чице, мо́лимся Твоєму́ благосе́рдію, щедро́ти Твоя́ прия́ти лю́дем Твої́м і достоя́нію Твоєму́, ста́ни Моли́твенниця к ро́ждшемуся із Тебе́ Бо́гу на́шему, да помо́жеть нам, коне́чно погиба́ющим, да і́зметь ни от напа́стей неісці́льних. Зри́ши, Влади́чице, коли́кими слеза́ми потопля́ємі єсьми́, уми́лостивися у́бо і не отри́ни нас до конця́. Вску́ю, Цари́це, лице́ Твоє́ отвраща́єши і забива́єши нищету́ на́шу і печа́ль на́шу, расточи́ належа́щий на ни страх і тре́петь, ути́ши подви́гшийся на ни гнів Бо́жий, і па́губу укроти́, і су́щия посреді́ нас ра́спри і м'яте́жи умири́, і тишину́ і мир пода́ждь рабо́м Твої́м благодія́нієм, і, сія́ приложи́вше, пропові́даєм всегда́ Твоя́ чудеса́, ча́юще дойти́ Твої́ми моли́твами ві́чния жи́зні, сла́в'яще Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Казанська»","e":"Prayer to the Theotokos before her icon “Kazan”","secs":[{"h":"Тропар, глас 4","ps":["Засту́пнице усе́рдная, / Ма́ти Го́спода Ви́шняго, / за всіх мо́лиши Си́на Твоєго́ Христа́ Бо́га на́шего, / і всім твори́ши спасти́ся, / в держа́вний Твой покро́в прибега́ющим. / Всіх нас заступи́, о Госпожі́ Цари́це і Влади́чице, / і́же в напа́стіх і в ско́рбіх, і в болі́зніх, обремене́нних гріхи́ мно́гими, / предстоя́щих і моля́щихся Тебі́ умиле́нною душе́ю / і сокруше́нним се́рдцем, / пред пречи́стим Твої́м о́бразом со слеза́ми, / і невозвра́тно наде́жду іму́щих на Тя, / ізбавле́нія всіх зол, / всім поле́зная да́руй, / і вся спаси́, Богоро́дице Ді́во: // Ти бо єси́ Боже́ственний покро́в рабо́м Твої́м."]},{"h":"Кондак, глас 8","ps":["Притеце́м, лю́діє, к ти́хому сему́ і до́брому приста́нищу, / ско́рой Помо́щнице, гото́вому і те́плому спасе́нію, покро́ву Ді́ви, / ускори́м на моли́тву і потщі́мся на покая́ніє: / істоча́єть бо нам неоску́дния ми́лості Пречи́стая Богоро́диця, / предваря́єть на по́мощ, і ізбавля́єть от вели́ких бід і зол // благонра́вния і богобоя́щіяся раби́ Своя́."]},{"h":"Молитва перша","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице! Со стра́хом, ві́рою і любо́вію пред честно́ю іко́ною Твоє́ю припа́дающе, мо́лим Тя: не отврати́ лиця́ Твоєго́ от прибіга́ющих к Тебі́, умоли́, Милосе́рдая Ма́ти, Си́на Твоєго́ і Бо́га на́шего, Го́спода Ісу́са Христа́, да сохрани́ть ми́рну страну́ на́шу, Це́рков же Свою́ святу́ю непоколеби́му да соблюде́ть і от неві́рія, єресе́й і раско́ла да ізба́вить. Не і́мами бо іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Пречи́стая Ді́во: Ти єси́ всеси́льная христия́н Помо́щниця і Засту́пниця. Ізба́ви же і всіх с ві́рою Тебі́ моля́щихся от паде́ній гріхо́вних, от наві́та злих челові́к, от вся́ких іскуше́ній, скорбе́й, болі́зней, бід і от внеза́пния сме́рті; да́руй нам дух сокруше́нія, смире́нія се́рдця, чистоту́ помишле́ній, ісправле́нія гріхо́вния жи́зні і оставле́ніє прегріше́ній, да всі, благода́рні воспіва́юще вели́чія і ми́лості Твоя́, явля́ємия над на́ми зді на землі́, сподо́бимся і Небе́снаго Ца́рствія і та́мо со всі́ми святи́ми просла́вим пречестно́є і великолі́поє І́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, Пресвята́я Влади́чице Богоро́дице, Цари́це Небесі́ і землі́, ви́шшая а́нгел і арха́нгел і всея́ тва́рі честні́йшая, чи́стая Ді́во Марі́є, ми́ру блага́я Помо́щнице, і всім лю́дем утвержде́ніє, і во вся́ких ну́ждах ізбавле́ніє! При́зри і ни́ні, Госпоже́ Всеми́лостивая, на раби́ Твоя́, Тебі́ умиле́нною душе́ю і сокруше́нним се́рдцем моля́щіяся, со слеза́ми к Тебі́ припа́дающия і покланя́ющіяся пречи́стому і цільбоно́сному о́бразу Твоєму́, і по́мощі і заступле́нія Твоєго́ прося́щия. О, Всеми́лостивая і Премилосе́рдая Ді́во Богоро́дице Чи́стая! Воззри́, Госпоже́, на лю́ди Твоя́: ми бо грі́шнії не і́мами іни́я по́мощі, ра́зві Тебе́ і от Тебе́ ро́ждшагося Христа́ Бо́га на́шего. Ти єси́ засту́пниця і предста́тельниця на́ша. Ти єси́ оби́димих защище́ніє, скорб'я́щим ра́дованіє, си́рим прибі́жище, вдо́вам храни́тельниця, ді́вам сла́ва, пла́чущим весе́ліє, больни́м посіще́ніє, немощни́м ісціле́ніє, грі́шним спасе́ніє. Сего́ ра́ди, о Богома́ти, к Тебі́ прибіга́єм, і на Твой Пречи́стий о́браз с Предві́чним на руку́ Твоє́ю держи́мим Младе́нцем, Го́сподем на́шим Ісу́сом Христо́м взира́юще, умиле́нноє пі́ніє Тебі́ прино́сим і вопіє́м: поми́луй нас, Ма́ти Бо́жия, і проше́ніє на́ше іспо́лни, вся бо суть возмо́жна хода́тайству Твоєму́: я́ко Тебі́ сла́ва подоба́єть ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой святи́й, / от него́же істека́єть благода́тная по́мощ // всім, с ві́рою притека́ющим к нему́."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Калузька»","e":"Prayer to the Theotokos before her icon “Kaluga”","secs":[{"h":"Тропар, глас 4","ps":["Засту́пнице от враг іноплеме́нних Необори́мая Калу́жськия землі́ / і Ізба́вительнице от смертоно́сния я́зви Ми́лостивая! / Ізба́ви раби́ Твоя́ от вся́ких бід і болі́зней, / с ві́рою і любо́вію прибега́ющия к чудотво́рній іко́ні Твоє́й, // і спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Не і́мами пі́сней, ніже́ слове́с, / ка́ко досто́йно восхваля́ти Тя, / Ма́ти Христа́ Бо́га на́шего, / явле́нія ра́ди чудотво́рния іко́ни Твоєя́ землі́ Калу́жстій, / то́кмо мо́жем вопи́ти Тебі́: / не отврати́ ми́лости Твоєя́ от нас // і низпосли́ ю всім притека́ющим к цільбоно́сній іко́ні Твоє́й."]},{"h":"Молитва перша","ps":["О Пресвята́я Ді́во, Ма́ти Христа́ Бо́га на́шего, Ди́вная Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію серде́ць на́ших; при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію предстоя́щих пред чудотво́рною Твоє́ю іко́ною і со умиле́нієм моля́щихся Тебі́, Влади́чице! Не преда́ждь умале́нію Це́рков Правосла́вную, помози́ нам, Пресвята́я Богоро́дице, святооте́чеськую Правосла́вную ві́ру до конця́ дній на́ших непоро́чно сохрани́ти, во всіх за́повідіх Госпо́дніх неукло́нно ходи́ти і ізба́ви ни от па́губних душевре́дних уче́ній. На Твою́, Ди́вная Цари́це Небесе́ і землі́, ми́лость упова́єм, раби́ Твої́: очи́сти уми́ на́ша от гріхо́вних по́мислов, душе́внаго разслабле́нія, обурева́нія страсте́й, от іскуше́ній, собла́знов і гріхопаде́ній; Ти бо єси́, Влади́чице, крі́пкоє прибі́жище грі́шников ка́ющихся. Воздви́гни нас із глубини́ гріхо́вния і і́стинним покая́нієм ороси́ ізсо́хшая сердця́ на́ша, просвіти́ серде́чная очеса́ на́ша ко зрі́нію спасе́нія, і прельще́нних бісо́вською пре́лестію на путь пра́вий наста́ви; вся́коє ді́ло зло́є і богопроти́вноє разруши́; вся́кому же благо́му і богоуго́дному ді́лу научи́ і споспі́шествуй; вложи́, Влади́чице, в сердця́ на́ша дух стра́ха Бо́жия, дух благоче́стія, дух кро́тости, смире́нія, терпі́нія, незло́бія; ум'ягчи́ зла́я сердця́ на́ша і ниспосли́ нам ре́вность о спасе́нії бли́жніх на́ших. Вразуми́ і научи́ ни, о Всеми́лостивая Засту́пнице на́ша, ка́ко безгрі́шно ходи́ти по путі́ земна́го сего́ житія́: я́ко Ти, Пресвята́я, ві́си ві́ру на́шу, і упова́ніє на́ше ви́диши. О Влади́чице ми́ра! Скорб'я́щих уті́ши, бе́дствующим помози́; сохрани́ от молнієно́снаго гро́ма, тлітво́рних вітр, лю́тих болі́зней, смертоно́сния я́зви, междоусо́бния бра́ні, наше́ствія враго́в іноплеме́нних. О Пресвята́я Богоро́дице! Ізбави́ ни от внеза́пния і наси́льственния сме́рті; всім нам да́руй обраще́ніє на путь і́стинний і христия́нськую кончи́ну живота́ на́шего безболі́зненну, непости́дну, ми́рну, Святи́х Тайн прича́стну. Во вре́м'я ісхо́да на́шего предста́ни нам, Ді́во Богоро́дице, і ізба́ви ни от вла́сті бісо́вськия, возду́шних го́рких мита́рств і огня́ ві́чнаго. Сконча́вшимся внеза́пною сме́ртію ми́лостива би́ти Си́на Твоєго́ умоли́, і о всіх усо́пших, і́же не і́муть сро́дников, о упокоє́нії їх Си́на Твоєго́ умоля́ющих, Сама́ бу́ди непреста́нная і те́плая Моли́твенниця і Хода́тайця. Преста́вльшихся же во ві́рі і покая́нії от вре́меннаго житія́ сего́ отці́, бра́тію, ма́тері і сестри́ на́ша сподо́би Твої́м хода́тайством всели́тися во оби́теліх Небе́сних со А́нгели і со всі́ми святи́ми, іді́же непреста́нно гла́си пра́зднующих і ра́достно сла́в'ящих Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга (під час хресного ходу)","ps":["О Пресвята́я Влади́чице Богоро́дице, Цари́це Небесі́ і землі́! К Тебі́ прибіга́єм і к Твоє́й по́мощі взива́єм: сохрани́ зе́млю на́шу от наше́ствія враго́в іноплеме́нних, і от вся́кия болі́зні душе́вния і тіле́сния, і от смертоно́сния я́зви, да всегда́ поє́м, велича́єм і сла́вим Тя, Пресвяту́ю Богоро́дицю, я́ко благу́ю і Ди́вную Засту́пницю на́шу во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Богоро́дице Ді́во, / і почита́єм чудотво́рную іко́ну Твою́, / є́юже благоволи́ла єси́ спасти́ зе́млю Калу́жськую // от наше́ствій вра́жиїх і всегуби́тельних болі́зней."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Козельщанська»","e":"Prayer to the Theotokos before her icon “Kozelshchyna”","secs":[{"h":"Тропар, глас 4","ps":["Весели́ся, земле́ Полта́вськая / і все Оте́чество на́ше правосла́вноє: / се бо я́ко світоза́рноє со́лнце, / яви́ся пречу́дная іко́на Твоя́, Преблагослове́нная Богома́ти, / мир озаря́ющи мно́жеством чуде́с Твої́х, / ті́ми у́бо обріта́єм, я́же на землі́, вся блага́я і поле́зная, / і су́щих, я́же на Небесі́, сокро́вищ сподобля́ємся. / Сего́ ра́ди вопіє́м Ті: / ра́дуйся, Похвало́ на́ша приснопокланя́ємая, / спаси́ ни, моля́щіяся Тебі́, // єди́ная Наде́ждо і Ра́дованіє ві́чноє пою́щих Тя."]},{"h":"Кондак, глас 3","ps":["Боголі́пно во смире́нії красу́ється оби́тель Красного́рськая, / осіня́ємая і спаса́ємая преди́вним о́бразом Влади́чиці Пречи́стия, / Небесе́ і землі́ Цари́ці Богоро́диці, / от него́же істо́чники благода́ті і ча́ша чуде́с оби́льно ізлива́ються, / і усе́рдно притека́ющії ісціле́нія ві́рою приє́млють, / і неві́рнії ві́рою крі́пкою сердца́ ісполня́ють / і ми, раби́ Твої́, Богома́ти, благода́рні вопіє́м Ті: // ра́дуйся, Предста́тельство христия́н непости́дноє і оби́телі Твоєя́ красото́ і ра́дованіє."]},{"h":"Молитва перша","ps":["Богоро́дице Ді́во Пренепоро́чная Ма́ти Христа́ Бо́га на́шего, Засту́пнице всего́ ро́да христия́нськаго! Чудотво́рній іко́ні Твоє́й благогові́йно предстоя́ще, мо́лим Тя, усли́ши нас, моля́щихся Тебі́: прийми́ благодаре́нія на́ша недосто́йная о всіх неізрече́нних Твої́х к нам благодія́ніїх, в мі́сті сем і во мно́гих ве́сях і гра́діх землі́ Українськия явле́нних і явля́ємих; Ти бо єси́ больни́х ісціле́ніє, скорб'я́щих утіше́ніє, заблу́ждших ісправле́ніє і вразумле́ніє. Бу́ди всім нам покро́в і утіше́ніє, приста́нище от вся́ких зол, бід і обстоя́ній, от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нник, смертоно́сния я́зви і от злих челові́к озлобле́нія. О Премилосе́рдая Ма́ти, бу́ди при́сно моли́твенниця любвеоби́льная о благостоя́нії свята́го хра́ма сего́, о ми́рі і тишині́ жи́тельства общи́ни сея́, укріпи́ і поддержи́ священноде́йствующия і служа́щия во святі́м хра́мі сем. Осіни́ вседержа́вним покро́вом Твої́м строї́телі і благотвори́телі святи́я оби́телі сея́, возда́ждь їм ві́чними да́ри щедро́т Твої́х, заступи́ от вся́кия напа́сти і сохрани́ с ві́рою і благогові́нієм притека́ющия к чудотво́рной іко́ні Твоє́й і моля́щіяся Тебі́ с любо́вію зді і на вся́ком мі́сті. Вознеси́ моли́тви на́ша, я́ко кади́ло благово́нноє, ко Престо́лу Всеви́шняго, да́рующаго нам здра́віє, долгоде́нствіє і в труді́х благочести́вих поспіше́ніє, да Твої́м окормле́нієм управля́ємі, і покро́вом Твої́м осіня́ємі, просла́вим Отця́, Си́на і Свята́го Ду́ха і Твоє́ Ма́тернеє о нас заступле́ніє, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Ді́во Влади́чице Богоро́дице, добропослу́шная Боже́ственному Сло́ву, Ма́ти Пречи́стая от всіх родо́в ізбра́нная, на Небесі́ і на землі́ ублажа́ємая, прийми́ і сіє́ благодаре́ніє на́ше і всеблагогове́йноє поклоне́ніє чудотво́рній іко́ні Твоє́й ю́же я́ко многоціле́бний істо́чник Твоєя́ благода́ті благоізво́лила єси́ яви́ти страні́ на́шей правосла́вній і святі́й оби́телі сей. Арха́нгельський глас вопіє́м Ті; Чи́стая, — Обра́дованная, ра́дуйся, с Тобо́ю Госпо́дь і Тобо́ю с на́ми! Предста́тельством Твої́м і заступле́нієм на Небесі́ у Престо́ла Всеблага́го Бо́га нікто́же да ізи́деть отсю́да упова́нія своєго́ тощ і неусли́шан. О, Пречу́дная і ви́сшая всіх тва́рей небе́сних і земни́х Богома́ти Ді́во, благода́рні помина́я пресла́вная чудеса́ от свята́го о́браза Твоєго́ дарова́нная, мо́лим Тя, Всеблага́я, не лиши́ от него́ і нас ди́внаго зна́менія во спасе́ніє на́ше. Пом'яни́ щедро́ти Твоя́ дре́внія, в судьба́х Оте́чества на́шего явле́нная, і да преста́нем всі от лука́вств свої́х і́миже прогні́вахом Тя во вік сей м'яте́жний удале́нієм от любве́ є́юже возлюби́ і возрасти́ нас Це́рков Свята́я. О, Прему́драя небе́сная Началоводи́тельнице ко спасе́нію і́нокинь оби́телі і́менем Твої́м нарече́нной ю́же ізбра́ла єси́ в достоя́ніє Своє́ на мі́сті сем Тобо́ю благослове́ннем, яви́ ю приста́нище ти́хоє всім скорб'я́щим і обремене́нним і ча́ющим блаже́нния ві́чния жи́зні. Грі́шнії єсьми́, Пренепоро́чная Влади́чице, но Твої́ до ві́ка. Озари́ у́бо ду́ші на́ша сві́том Боже́ственная благода́ті Твоєя́, покри́й нас от вся́каго зла, ско́рби і печа́лі: огради́ от вся́кия напа́сти, клевети́ челові́чеськія і наві́та вра́жия; немощни́м і боля́щим здра́віє да́руй; ка́ющихся грі́шников прости́ і от плі́на страсте́й свободи́; отступи́вшия от правосла́вния ві́ри і поги́бельними єресьми́ осліпле́нния сві́том богопозна́нія просвіти́ і святеє́й Апо́стольстій Це́ркві причти́. Мо́лим Тя, умиле́нно, сохрани́ і поми́луй па́стирей Це́ркві Правосла́вния і всіх ві́рних чад єя́; утверди́ житіє́ на́ше в ми́рі; упра́ви путі́ і сові́ти на́ша в пра́вді, во є́же откри́тися в них Ца́рству Христо́ву: да́руй нам кончи́ну христия́нськую, безболі́знену, непости́дну, ми́рну, Боже́ственних Та́їн прича́стну, і Сама́ нам в час той предста́ни і спаси́ посреди́ мита́рств возду́шних от мра́ка і ско́рби лю́тия; в стра́шний же день Суда́ сподо́би ни ста́ти одесну́ю Си́на Твоєго́ Христа́ Бо́га на́шего. Мо́лим Тя, Ді́во Всепі́тая, при́зри благосе́рдієм Твої́м на оби́тель сію́ і сохрани́ ю до ві́ка ці́лу і неврежде́нну, да ви́ну чистото́ю возвиша́ється і сла́виться в ней вели́чество Єдиносу́щния Тро́йці і Твоє́ препі́тоє і преблагослове́нноє і́м'я во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Коневська»","e":"Prayer to the Theotokos before her icon “Konevets”","secs":[{"h":"Тропар, глас 1","ps":["Возсія́ нам, я́ко со́лнце світоза́рноє, от восто́ка во велелі́пії / Твоя́, Влади́чице, іко́на, / озаря́ющи чуде́с сія́нієм пресла́вно / всіх, ви́ну приходя́щих к ней с ві́рою і любо́вію, / і моля́щихся усе́рдно Твоєму́, є́же о Си́ні Твоє́м і Бо́зі вели́чію. / Сла́ва Бо́гу, Арсе́нієм сію́ да́вшему нам, / сла́ва возврати́вшему от Нова́града, // сла́ва ді́йствующему то́ю всім ісціле́нія."]},{"h":"Кондак, глас 8","ps":["Препросла́вленная Ви́шняго Ма́ти созива́єть к піснопі́нію нас / Своєго́ о́браза прише́ствієм от Нова́града / і возбужда́єть зрі́нієм того́ на по́двиг, / побіжда́ти сопроти́вних си́лу, / і к Ней, я́ко на́шея ра́дости вино́вній, пі́ти: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["О, Всеми́лостивая Госпоже́, Ді́во Богоро́дице! Воньми́ смире́нному моле́нію моєму́, і сокруше́нно ни́ні предстоя́щаго о́бразу Твоєму́ усли́ши глас. Вім бо, о, Соді́теля моєго́ Ма́ти, я́ко Ти предста́тельство христия́н непости́дноє і хода́тайство ко Творцю́ непрело́жноє. Вім і сіє́, я́ко беззако́нія моя́ превзидо́ша главу́ мою́, і я́ко бре́м'я тя́жкоє отяготі́ша на мні, і уже́ нісьм досто́їн ви́діти висоту́ Небе́сную, ніже́ воззрі́ти ко Престо́лу сла́ви Си́на Твоєго́ і Бо́га на́шего, но досто́їн мук і ві́чнаго осужде́нія. Сего́ ра́ди к Тебі́ (со предстоя́щими ку́пно) припа́даю, Тя прошу́ умиле́нно, к Тебі́ со слеза́ми взива́ю: сотвори́ к Нему́ ма́тернєє Твоє́ моле́ніє, да не отве́ржеть нас, грі́шних от лиця́ Своєго́: но я́ко Ми́лостив, да прости́ть нам согріше́нія на́ша во́льная і нево́льная, на путь спасе́нія наставля́я нас, і сви́ше си́лою укріпля́я к творе́нію за́повідей Свої́х святи́х. Да сохрани́ть нас от собла́знов ми́ра, от вожделі́ній гріхо́вних, от ко́зней дия́вольських, і от нападе́нія ви́димих враго́в. Да благослови́ть діла́ рук на́ших, подава́я оби́телі сей і вся́кому гра́ду і страні́ оби́ліє благ земни́х. Да сотвори́ть нам дні бла́гі і безм'яте́жни, да огради́ть ми́ром Це́рков Свою́ святу́ю, і разстоя́щая да соєдини́ть той, я́ко благ Госпо́дь, Долготерпіли́в і Многоми́лостив, от всея́ тва́рі со Отце́м і Святи́м Ду́хом сла́вимий во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Любецька»","e":"Prayer to the Theotokos before her icon “Lyubech”","secs":[{"h":"Тропар, глас 4","ps":["Преблагослове́нная Цари́це, / Пречи́стая Ді́во Богоро́дице, / просла́вльшая град Лю́беч / уго́дника Твоєго́ преподо́бнаго Анто́нія Пече́рськаго рожде́нієм / і чудотво́рния іко́ни Твоєя́ явле́нієм, / мо́лим Тя, Всеблага́я: / моли́ за ни ро́ждшагося от Тебе́ Царя́, / Христа́ Бо́га на́шего, / і Ма́терним Твої́м к Нему́ предста́тельством / ізба́ви нас от вся́каго зла, / неду́ги на́ша ісціли́, печа́лі на́ша утоли́ / і наслі́дники яви́ нас Ца́рствія Небе́снаго, // я́ко Милосе́рдна."]},{"h":"Кондак, глас 8","ps":["Притеце́м, ві́рнії, к многоціле́бному о́бразу Засту́пниці на́шея, Богоро́диці Марі́ї, / і, припа́дающе к нему́ с любо́вію, си́це рцем: / о Всепі́тая Ма́ти, о Цари́ці Всеми́лостивая, / при́зри сви́ше благосе́рдієм Твої́м на ни, недосто́йния, / і моли́твами уго́дника Твоєго́, преподо́бнаго Анто́нія Пече́рськаго, / яви́ нам Твоя́ ми́лості і щедро́ти: / в болі́зніх ісціле́ніє, в ско́рбіх утіше́ніє, / в біда́х ско́рую по́мощ нам да́руй, / і вся ни спаси́, на Тя упова́ющия, да зове́м Ті: // ра́дуйся, Ді́во, христия́н заступле́ніє."]},{"h":"Молитва","ps":["О, Пресвята́я і Преблагослове́нная Ма́ти Го́спода і Спа́са на́шего Ісу́са Христа́, Пречи́стая Присноді́во, Богоро́дице Марі́є! Припа́даєм і покланя́ємся Тебі́ пред свято́ю і чудотво́рною іко́ною Твоє́ю, ю́же от літ дре́вніх зді чудеси́ мно́гими і ісціле́ньми неісче́тними просла́вити благоізво́лила єси́. Смире́нно мо́лимся Тебі́, Благо́й і Милосе́рдной Засту́пниці на́шей, предста́тельством уго́дника Твоєго́, преподо́бнаго Анто́нія Пече́рськаго, воньми́ гла́су грі́шних моле́ній на́ших, не пре́зри воздиха́ній от душі́, виждь ско́рби і біди́, нас обише́дшия, і, я́ко любвеоби́льная воі́стину Ма́ти, потщи́ся на по́мощ нам, безпо́мощним, уни́лим, во мно́гія і тя́жкия гріхи́ впа́дшим і приснопрогневля́ющим Го́спода і Созда́теля на́шего, Єго́же умоли́, Предста́тельнице на́ша, да не погуби́ть нас со беззако́нії на́шими, но яви́ть нам человіколю́бную Свою́ ми́лость. Іспроси́ нам, Влади́чице, у бла́гости Єго́, тіле́сноє здра́віє і душе́вноє спасе́ніє, благоче́стноє і ми́рноє житіє́, землі́ плодоно́сіє, возду́ха благорастворе́ніє, до́жди благовре́менни і благослове́ніє сви́ше на вся блага́я діла́ і начина́нія на́ша. Ісхода́тайствуй, Госпоже́, у Царя́ ца́рствующих і Го́спода госпо́дствующих страні́ на́шей на вся враги́ побі́ду і одолі́ніє, всім же правосла́вним христия́ном ми́лость Бо́жию, благоустроє́ніє і во всіх благи́х ізоби́ліє. О, Цари́ці Всепі́тая, Ма́ти Бо́жия Всеблага́я, простри́ богоно́снії ру́ці Твої́ к возлю́бленному Си́ну Твоєму́ і Бо́гу на́шему, умоли́ Єго́ вся ни спасти́ і ізба́вити поги́белі ві́чния. Я́коже дре́вле на мі́сті сем отце́м на́шим ми́лость Твою́ явля́ла єси́, Влади́чице, си́це і нам ни́ні яви́, Богоро́дице, Твоя́ щедро́ти: боля́щия ісціли́, скорб'я́щия уті́ши, бе́дствующим помози́. Споспіши́ всім нам носи́ти і́го Христо́во в терпі́нії і смире́нії і сподо́би нас благоче́стно житіє́ сіє́ земно́є сконча́ти, христия́нськую непости́дную кончи́ну получи́ти і Небе́сноє Ца́рствіє унаслі́дити Ма́тернім хода́тайством Твої́м к ро́ждшемуся от Тебе́ Го́споду і Бо́гу на́шему Ісу́су Христу́, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // с ві́рою всім притека́ющим."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Млекопитательниця»","e":"Prayer to the Theotokos before her icon “The Milk-Giver”","secs":[{"h":"Тропар, глас 3","ps":["Без сі́мене от Боже́ственнаго Ду́ха, / во́лею же О́тчею зачала́ єси́ Си́на Бо́жия, / от Отця́ без ма́тере пре́жде вік су́ща, / нас же ра́ди із Тебе́ без отця́ би́вша, / пло́тію родила́ єси́ / і Младе́нця млеко́м пита́ла єси́, / ті́мже не преста́й моли́ти // ізба́витися от бід душа́м на́шим."]},{"h":"Кондак, глас 5","ps":["Душ на́ших чу́вствія очи́стивше, / у́зрим на іко́ні та́їнство пресла́вноє, / Творця́ Вселе́нной і Го́спода ви́шніх сил, / во об'я́тіїх держи́ма і от сосцю́ Твоє́ю я́ко Младе́нця пита́єма, / і, со стра́хом і ра́достію покланя́ющеся Тебі́ / і ро́ждшемуся от Тебе́ Спа́су на́шему, воззове́м: // ра́дуйся, Влади́чице, жи́зні на́шея Пита́тельнице."]},{"h":"Молитва перша","ps":["Прийми́, Госпоже́ Богороди́тельнице, сле́зная моле́нія рабо́в Твої́х, к Тебі́ притека́ющих. Зрим Тя на святі́й іко́ні, на рука́х нося́щую і млеко́м пита́ющую Си́на Твоєго́ і Бо́га на́шего, Го́спода Ісу́са Христа́. А́ще і безболі́зненно родила́ єси́ Єго́, оба́че ма́тернія ско́рби ві́си і не́мощі сино́в і дще́рей челові́чеських зри́ши. Ті́мже те́плі припа́дающе к цільбоно́сному о́бразу Твоєму́ і умиле́нно сей лобиза́юще, мо́лим Тя, всеми́лостивая Влади́чице: нас, грі́шних, осужде́нних в болі́зніх роди́ти і в печа́ліх пита́ти ча́да на́ша, ми́лостивно пощади́ і сострада́тельно заступи́, младе́нці же на́ша, та́кожде і роди́вшия їх, от тя́жкаго неду́га і го́ркия ско́рби ізба́ви. Да́руй їм здра́віє і благомо́щіє, да і пита́ємії от си́ли в си́лу возраста́ти бу́дуть, і пита́ющия їх іспо́лняться ра́достію і утіше́нієм, я́ко да і ни́ні предста́тельством Твої́м із уст младе́нець і ссу́щих Госпо́дь соверши́ть хвалу́ Свою́. О Ма́ти Си́на Бо́жия! Умилосе́рдися на ма́тері сино́в челові́чеських і на немощни́я лю́ди Твоя́: постига́ющия нас болі́зні ско́ро ісціли́, належа́щия на нас ско́рби і печа́лі утоли́, і не пре́зри слез і воздиха́ній рабо́в Твої́х. Усли́ши нас в день ско́рби пред іко́ною Твоє́ю припа́дающих, і в день ра́дости і ізбавле́нія прийми́ благода́рная хвале́нія серде́ць на́ших. Вознеси́ мольби́ на́ша к престо́лу Си́на Твоєго́ і Бо́га на́шего, да ми́лостив бу́деть ко гріхо́м і немоще́м на́шим і проба́вить ми́лость Свою́ веду́щим і́м'я Єго́, я́ко да і ми, і ча́да на́ша, просла́вим Тя, милосе́рдую Засту́пницю і ві́рную наде́жду ро́да на́шего, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Госпоже́ Влади́чице на́ша Богоро́дице, Небе́сная на́ша Цари́це, млеко́м Христа́ Бо́га на́шего пита́вшая, і нас недосто́йних і многогрі́шних Твоє́ю бога́тою ми́лостію пита́єши. Спаси́ і ізба́ви нас грі́шних рабо́в Твої́х от напра́сния клевети́, от вся́кия біди́ і напа́сти і внеза́пния сме́рті. Поми́луй нас в дневни́х часі́х, во у́тренних і вече́рніх і во вся́коє вре́м'я сохрани́ нас: стоя́щих, сидя́щих соблюди́ і на вся́ких путеіх ходя́щих і в ночни́х часі́х спя́щих покри́й і заступи́. Защити́ нас, Влади́чице Богоро́дице, от всіх на́ших враг ви́димих і неви́димих і от вся́каго зла́го обстоя́нія. На вся́ком мі́сті і на вся́коє вре́м'я бу́ди нам, Ма́ти Преблага́я, необори́мая стіна́ і крі́пкоє заступле́ніє, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Млекопита́тельниці Спа́са на́шего, / і чтим о́браз Твой святи́й, / от него́же благода́ть ісціле́нія / нам при́сно подає́ши."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Муромська»","e":"Prayer to the Theotokos before her icon “Murom”","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється град Му́ром, / я́ко зарю́ со́лнечную, восприє́мши, Влади́чице, / чудотво́рную Твою́ іко́ну, / к не́йже ни́ні ми притека́юще і моля́щеся, Тебі́ взива́єм си́це: / о Пречу́дная Влади́чице Богоро́дице, / моли́ся із Тебе́ воплоще́нному Христу́ Бо́гу на́шему, / да ізба́вить град сей і вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх / і спасе́ть ду́ші на́ша, я́ко Милосе́рд."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх Сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея Всемо́щная Засту́пнице! Усли́ши нас, моля́щихся Тебі́, і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем – му́дрость і си́лу, судія́м – пра́вду і нелицеприя́тіє, наста́вником – ра́зум і смиренному́дріє, супру́гом – любо́в і согла́сіє, ча́дом – послуша́ніє, оби́димим – терпі́ніє, оби́дящим - страх Бо́жий, скорб'я́щим – благоду́шіє, ра́дующимся – воздержа́ніє. Нам же всім низпосли́ дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пречи́стая! Умилосе́рдися на немощни́я лю́ди Твоя́: разсі́янния собери́, заблу́дшия на путь пра́вий наста́ви, неду́гующия уврачу́й, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія. Ми́лостива нам бу́ди зді і на Стра́шном Суді́ Си́на Твоєго́. Ти бо єси́, Госпоже́, сла́ва Небе́сних і упова́ніє земни́х, ти по Бо́зі на́ша наде́жда і Засту́пниця всіх притека́ющих к Тебі́ с ві́рою. Тебі́ у́бо мо́лимся і Тебі́, я́ко всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і всю жизнь на́шу предає́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Неопалима Купина»","e":"Prayer to the Theotokos before her icon “Unburnt Bush”","secs":[{"h":"Тропар, глас 4","ps":["І́же во огні́ купини́ неопали́мия, дре́вле Моїсе́єм ви́дінния, / та́йну воплоще́нія Своєго́ от неіскусобра́чния Ді́ви Марі́ї Прообразова́вий, / Той і ни́ні, я́ко чуде́с Творе́ць і всея́ тва́рі Созда́тель, / іко́ну Єя́ святу́ю чудеси́ мно́гими просла́ви, / дарова́в ю ві́рним во ісціле́ніє неду́гом / і в защище́ніє от о́гненнаго запале́нія. / Сего́ ра́ди вопіє́м Преблагослове́нній: / наде́ждо христия́н, от лю́тих бід, огня́ і гро́ма ізба́ви на Тя упова́ющия // і спаси́ ду́ші на́ша, я́ко милосе́рда."]},{"h":"Інший тропар, глас 4","ps":["І́же в купині́, огне́м горя́щей і несгора́ємой, / показа́вий Моїсе́йові Пречи́стую Твою́ Ма́тер, Христе́ Бо́же, / Огнь Божества́ неопа́льні во чре́ві приі́мшую, / і нетлі́нну по Рождестві́ преби́вшую: / Тоя́ моли́твами пла́мене страсте́й ізба́ви нас, / і от о́гненних запале́ній град Твой сохрани́, // я́ко Многоми́лостив."]},{"h":"Кондак, глас 8","ps":["Предочи́стим чу́вствія душ і тіле́с на́ших, / да ви́дим та́їнство Боже́ственноє, / о́бразно явле́нноє дре́вле вели́кому во проро́ціх Моїсе́ю купино́ю, / горі́вшею огне́м і не сгара́вшею, / в не́йже Твоєго́ безсі́меннаго Рождества́, Богоро́дице, предвозвіще́ніє іспові́дуєм, / і, благогові́йно покланя́ющеся Тебі́ / і Ро́ждшемуся от Тебе́ Спа́су на́шему, со стра́хом вопіє́м: // ра́дуйся, Влади́чице, Покро́ве, і Прибі́жище, і Спасе́ніє душ на́ших."]},{"h":"Молитва перша","ps":["Цари́це Небе́сная, Влади́чице на́ша, Госпоже́ Вселе́нния, Пресвята́я Богоро́дице, нескве́рная, небла́зная, нетлі́нная, пречи́стая, чи́стая Присноді́во, Марі́є Богоневі́сто, Ма́ти Творця́ тва́рі, Го́спода сла́ви і Влади́ки вся́чеських! Тобо́ю Цар ца́рствующих і Госпо́дь госпо́дствующих при́йде і на землі́ нам яви́ся. Ти у́бо Бо́жиє милосе́рдіє воплоще́нноє. Ти Ма́ти Сві́та і Живота́ су́щи, я́коже ні́когда во чре́ві Твоє́м носи́ла єси́ Єго́ і на об'я́тіїх Твої́х імі́ла єси́ Младе́нця Сло́во Преві́чноє, Бо́га, та́ко і всегда́ Того́ с Собо́ю і́маши. Сего́ ра́ди ми по Бо́зі к Тебі́ прибіга́єм, я́ко к неруши́мій стіні́ і предста́тельству: при́зри благосе́рдієм, всепі́тая Богоро́дице, на лю́тоє озлобле́ніє на́ше і ісціли́ душ і тіле́с на́ших болі́зні: отжени́ от нас вся́каго врага́ і супоста́та, ізба́ви от гла́да, мо́ра, от я́зви, от вод мно́гих і возду́хов тлітво́рних, і от сме́рти внеза́пния; і я́коже три о́троки в пещі́ вавило́нстій, сохрани́ і соблюди́ нас, да я́коже дре́вле лю́дем Бо́жиїм, та́ко бу́дуть вся блага́я нам чту́щим Тя; вразі́ же і всі ненави́дящії нас да постидя́ться і посра́м'яться, і уразумі́ють всі, я́ко с Тобо́ю Госпо́дь, о Влади́чице, і Тобо́ю с на́ми Бог. Во дні осіни́ нас сі́нію благода́ті Твоєя́, во тьмі же нощні́й просвіти́ сві́том сви́ше, всім поле́зная устроя́ющи: преложи́ го́ресть на́шу во сла́дость і сле́зи утри́ согріши́вших і бі́дствующих раб Твої́х, ісполня́ющи коєго́ждо проше́нія вся во бла́го; вся бо мо́жеши, єли́ка хо́щеши Ти, Ма́ти Сло́ва і Живота́. Тебі́ Оте́ць вінча́ Дщер, Син Ма́тер Ді́ву, Дух Святи́й Неві́сту, да ца́рствуєши я́ко цари́ця, предстоя́щи одесну́ю Святи́я Тро́йці, і ми́луєши нас я́коже хо́щеши, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, Пресвя́тая і Преблагослове́нная Ма́ти Сладча́йшаго Го́спода на́шего Ісу́са Христа́! Припа́даєм і поклоня́ємся Тебі́ пред свято́ю і пречестно́ю іко́ною Твоє́ю, є́юже ди́вни і пресла́вни чудеса́ содіва́єши, от о́гненнаго запале́нія і молнієно́снаго гро́ма жили́ща на́ша спаса́вши, неду́жния ісціля́єши і вся́коє благо́є проше́ніє на́ше во бла́го ісполня́єши. Смире́нно мо́лим Тя, всеси́льная ро́да на́шего Засту́пнице, сподо́би ни немощни́я і грі́шния Твоєго́ Ма́терняго уча́стія і благопопече́нія. Спаси́ і сохрани́, Влади́чице, под кро́вом ми́лости Твоєя́ Це́рков Святу́ю, оби́тель сію́, всю страну́ на́шу правосла́вную, і вся ни припа́дающия к Тебі́ с ві́рою і любо́вію, і умиле́нно прося́щия со слеза́ми Твоєго́ заступле́нія. Єй, Госпоже́ Всеми́лостивая, умилосе́рдися на нас, обурева́ємих гріха́ми мно́гими і не іму́щих дерзнове́нія ко Христу́ Го́споду, проси́ти Єго́ о поми́лованії і проще́нії, но Тебі́ предлага́єм к Нему́ на умоле́ніє Ма́тер Єго́ по пло́ті: Ти же, Всеблага́я, простри́ к Нему́ Богоприї́мнії ру́ці Твої́ і предста́тельствуй за нас пред Бла́гостію Єго́, прося́ще нам проще́нія прегріше́ній на́ших, благоче́стнаго ми́рнаго житія́, благи́я христия́нськия кончи́ни, і до́браго отві́та на стра́шнім Суді́ Єго́. В час же гро́знаго посіще́нія Бо́жия, єгда́ огне́м возгоря́ться до́ми на́ша, іли́ молнієно́сним гро́мом устраша́ємі бу́дем, яви́ нам ми́лостивноє Твоє́ заступле́ніє і держа́вноє вспоможе́ніє: да спаса́ємі всеси́льними Твої́ми ко Го́споду моли́твами вре́меннаго наказа́нія Бо́жия зді ізбі́гнем і ві́чноє блаже́нство ра́йськоє та́мо унаслі́дуєм: і со всі́ми святи́ми воспоє́м Пречестно́є і Великолі́пноє І́м'я поклоня́ємиє Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, і Твоє́ ве́ліє к нам милосе́рдіє, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода Ви́шняго, Засту́пнице і Покрови́тельнице всіх, к Тебі́ прибіга́ющих! При́зри с висоти́ святи́я Своєя́ на м'я грі́шнаго, припа́дающаго к чудотво́рному ли́ку Твоєму́: усли́ши мою́ смире́нную моли́тву і принеси́ ю пред возлю́бленнаго Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́: умоли́ Єго́, да просвіти́ть мра́чную мою́ ду́шу сві́том Боже́ственния благода́ті Своєя́, да ізба́вить м'я от вся́кия ну́жди, ско́рби і болі́зні, да ниспосле́ть мні ти́хоє і ми́рноє житіє́, здра́віє тіле́сноє і душе́вноє, да успоко́їть стра́ждущеє се́рдце моє́ і ісціли́ть ра́ни єго́, да вразуми́ть м'я на до́брия діла́, очи́стить ум мой от помишле́ній су́єтних, наста́вить м'я ко ісполне́нію за́повідей Свої́х, ізба́вить от ві́чния му́ки і не лиши́ть Своєго́ Небе́снаго Ца́рствія. О, Пресвята́я Богоро́дице, Ти — “всіх скорб'я́щих Ра́досте”, усли́ши і м'я ско́рбнаго. Ти, — імену́ємая — “Утоле́ніє печа́лі”, утоли́ і мою́ печа́ль. Ти — “Купина́ неопали́мая”, сохрани́ мир і всіх нас от вредоно́сних, о́гненних стріл врага́. Ти — “Взиска́ніє поги́бших”, не попусти́ і мні поги́бнуть в бе́здні гріхо́в мої́х. На Тя по Бо́зі вся моя́ наде́жда і упова́ніє! Бу́ди мні Покрови́тельницею в жи́зні вре́менной і ві́чной і Хода́тайцею пред возлю́бленним Си́ном Твої́м, Го́сподом на́шим, Ісу́сом Христо́м. Научи́ м'я служи́ти Єму́ с ві́рою і любо́вію і благогові́йно чти́ти Тебі́, Пресвята́я Ма́ти Бо́жия, Преблагослове́нная Марі́є! Твої́м святи́м моли́твам вруча́ю себе́ до сконча́нія дній мої́х. Амі́нь."]},{"h":"Молитва четверта","ps":["О, Пресвята́я Ді́во Ма́ти Го́спода, Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію душі́ на́шея, при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію поклоня́ющихся пречи́стому о́бразу Твоєму́. Се бо гріхми́ погружа́ємії і скорб'я́ми обурева́ємії, взира́я на Твой о́браз, я́ко живі́й Ті су́щей с на́ми, прино́сим смире́нния моле́нія на́ша. Не і́мами бо ні іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о, Ма́ти всіх скорб'я́щих і обремене́нних. Помози́ нам не́мощним, утоли́ скорб на́шу, наста́ви на путь пра́вий нас, заблужда́ющих, уврачу́й і спаси́ безнаде́жних, да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і тишині́ проводи́ти, пода́ждь христия́нськую кончи́ну, і на стра́шнім суді́ Си́на Твоєго́ яви́ся нам милосе́рдія засту́пниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко благу́ю Засту́пницю ро́да христия́нського, со всі́ми угоди́вшими Бо́гу. Амі́нь.","О, Ма́ти Бо́жия Неопали́мая Купина́, заступи́ м'я от людсько́й напа́сти, от па́нськой ка́рности, от неугаси́мого огня́, от на́глой сме́рті, от ві́чной му́ки і скрой ри́зой Своє́й Небе́сній м'я. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Неупиваєма Чаша»","e":"Prayer to the Theotokos before her icon “The Inexhaustible Chalice”","secs":[{"h":"Тропар, глас 4","ps":["Днесь притеце́м ві́рнії / к Боже́ственному і пречу́дному о́бразу Пресвяти́я Богома́тері, / напоя́ющей ві́рних сердця́ / небе́сною Неупива́ємою Ча́шею Своєго́ милосе́рдія / і лю́дем ві́рним чудеса́ показу́ющей. / Я́же ми ви́дяще і сли́шаще / духо́вно пра́зднуєм і те́плі вопіє́м: / Влади́чице преми́лостивая, / ісціли́ на́ша неду́ги і стра́сті / моля́щи Си́на Твоєго́ Христа́ Бо́га на́шего // спасти́ ду́ші на́ша."]},{"h":"Молитва перша","ps":["О, Премилосе́рдая Влади́чице! К Твоєму́ заступле́нію ни́ні прибіга́єм, моле́ній на́ших не пре́зри, но ми́лостивно усли́ши нас: жен, діте́й, ма́терей і тя́жким неду́гом пія́нства одержи́мих, і того́ ра́ди от ма́тере своєя́ — Це́ркві Христо́вой і спасе́нія отпа́дающих, бра́тьев і сесте́р і сро́дник на́ших ісціли́. О, Ми́лостивая Ма́ти Бо́жия, косни́ся серде́ць їх і ско́ро возста́ви от паде́ній гріхо́вних, ко спаси́тельному воздержа́нію приведи́ їх. Умоли́ Си́на Своєго́, Христа́ Бо́га на́шего, да прости́ть нам согріше́нія на́ша і не отврати́ть ми́лости Своєя́ от люде́й Свої́х, но да укріпи́ть нас в трезве́нії і цілому́дрії. Прийми́, Пресвята́я Богоро́дице, моли́тви ма́терей, о ча́діх свої́х сле́зи пролива́ющих, жен, о мужеіх свої́х рида́ющих, чад, си́рих і убо́гих, заблу́ждшими оста́вленних, і всіх нас, к іко́ні Твоє́й припа́дающих. І да при́йдеть сей вопль наш, моли́твами Твої́ми, ко Престо́лу Всеви́шняго. Покри́й і соблюди́ нас от лука́ваго ловле́нія і всіх ко́зней вра́жиїх, в стра́шний же час ісхо́да на́шего помози́ пройти́ непреткнове́нно возду́шния мита́рства, моли́твами Твої́ми ізба́ви нас ві́чнаго осужде́нія, да покро́єть нас ми́лость Бо́жия в несконча́ємиі ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Цари́це на́ша Преблага́я, наде́ждо на́ша, Пресвята́я Богоро́дице, прия́телеще си́рих і стра́нних Засту́пнице, бі́дствующих по́моще і озло́бленних покро́ве. Зри́ше на́шу біду́, зри́ше на́шу скорб: отвсю́ду іскуше́ніями одержи́ми єсьми́, а заступа́ющего ність. Ти у́бо Сама́ помози́ нам, я́ко не́мощни, окорми́, я́ко стра́нни, наста́ви нас, я́ко заблу́дших, уврачу́й і спаси́ нас, я́ко безнаде́жних. Не і́мами іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о Ма́ти всіх ско́рбних і обремене́нних. При́зри на нас, грі́шних і во озлобле́нії су́щих, покри́й нас Честни́м Твої́м Омофо́ром. Да ізба́влени бу́дем от зол, обише́дших нас, найпа́че же пія́нства. Да восхва́лим всегда́ Пресвято́є і́м'я Твоє́. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Нечаянная Радість»","e":"Prayer to the Theotokos before her icon “Unexpected Joy”","secs":[{"h":"Тропар, глас 4","ps":["Днесь ві́рнії лю́діє / духо́вно торжеству́єм, / прославля́юще Засту́пницю усе́рдную ро́да христия́нськаго / і притека́юще к пречи́стому Єя́ о́бразу, взива́єм си́це: / о, Преми́лостивая Влади́чице Богоро́дице, / пода́ждь нам неча́янную ра́дость, / обремене́нним гріхи́ і скорбми́ мно́гими, / і ізба́ви нас от вся́каго зла, // моля́щи Си́на Твоєго́, Христа́ Бо́га на́шего, спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице. / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, Всеблага́го Си́на Ма́ти Всеблага́я, гра́да і свята́го хра́ма сего́ Покрови́тельнице, всіх су́щих во грісі́х, ско́рбіх, біда́х і болі́зніх ві́рная Предста́тельнице і Засту́пнице! Прийми́ моле́бноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, Тебі́ возноси́моє, і я́коже дре́вле грі́шника, на всяк день мно́гажди пред честно́ю іко́ною Твоє́ю моли́вшагося, не презрі́ла єси́, но дарова́ла єси́ єму́ неча́янную ра́дость покая́нія і преклони́ла єси́ Си́на Твоєго́ мно́гим і усе́рдним к Нему́ хода́тайством к проще́нію сего́ грі́шнаго і заблу́дшагося, та́ко і ни́ні не пре́зри моле́нія нас, недосто́йних рабо́в Твої́х, і умоли́ Си́на Твоєго́ і Бо́га на́шего, да і всім нам, с ві́рою і умиле́нієм поклоня́ющимся пред цільбоно́сним о́бразом Твої́м, да́руєть неча́янную по коєго́ждо потре́бі ра́дость: грі́шником, погря́зшим во глубині́ зол і страсте́й, — вседі́йственноє вразумле́ніє, покая́ніє і спасе́ніє; су́щим в ско́рбіх і печа́ліх — утіше́ніє; обріта́ющимся в біда́х і озло́бленіїх — соверше́нноє сих ізби́тіє; малоду́шним і ненаде́жним — наде́жду і терпі́ніє; в ра́дості і ізоби́лії живу́щим — непреста́нноє Благоді́телю Бо́гу благодаре́ніє; бе́дствующим — милосе́рдіє; су́щим в болі́зні і долгонеду́жії і оста́вленним врача́ми — неча́ємоє ісціле́ніє і укріпле́ніє; іжди́вшим от неду́га ум — ума́ возвраще́ніє і обновле́ніє; отходя́щим во ві́чную і несконча́ємую жизнь — па́м'ять сме́ртную, умиле́ніє і сокруше́ніє о грісі́х, дух бодр і тве́рдую на милосе́рдіє Судії́ наде́жду. О Госпожі́ Пресвята́я! Умилосе́рдися о всіх чту́щих всечестно́є і́м'я Твоє́ і всім яви́ всемо́щний покро́в Твой і заступле́ніє: во благоче́стії, чистоті́ і честні́м жи́тельстві пребива́ющия до сконча́нія їх во бла́гости соблюди́; зли́я бла́гі сотвори́; заблу́ждшия на путь пра́вий наста́ви; вся́кому ді́лу благо́му і Си́ну Твоєму́ уго́дному споспі́шествуй; вся́коє ді́ло зло́є і богопроти́вноє разруши́; в недоумі́нії і тру́дних і опа́сних обстоя́ніїх обріта́ющимся незри́мую по́мощ і вразумле́ніє с Небесе́ ниспосли́, от іскуше́ній, собла́знов і поги́белі спаси́, от всіх злих челові́к і от враго́во ви́димих і неви́димих защити́ і сохрани́; пла́вающим спла́вай, путеше́ствующим спутеше́ствуй; су́щим в ну́жді і гла́ді бу́ди Пита́тельниця; неіму́щим кро́ва і приста́нища бу́ди покро́в і прибі́жище; наги́м пода́ждь одія́ніє, оби́димим і непра́ведно гони́мим — заступле́ніє; клевету́, поноше́ніє і хуле́ніє терп'я́щия незри́мо оправда́й; клеветники́ і хули́телі пред всі́ми обличи́; ожесточе́нно вражду́ющим неча́ємоє пода́ждь примире́ніє і всім нам — друг ко дру́гу любо́в, мир, і благоче́стіє, і здра́віє с долгоде́нствієм. Супру́жества в любві́ і єдиноми́слії сохрани́; супру́ги, во вражді́ і разділе́нії су́щия, умири́, соєдини́ я друг ко дру́гу і положи́ їм сою́з любве́ неразруши́мий; ма́терем детородя́щим ско́роє пода́ждь разріше́ніє, младе́нці воспита́й, ю́ния уцілому́дри, отве́рзи їм ум к восприя́тію вся́каго поле́знаго уче́нія, стра́ху Бо́жию, воздержа́нію і трудолю́бію наста́ви; от дома́шнія бра́ні і вражди́ єдинокро́вния ми́ром і любо́вію огради́; безма́терніх сиро́т бу́ди Ма́тер, от вся́каго поро́ка і скве́рни отврати́ я і всему́ благо́му і богоуго́дному научи́, прельще́нния же і во гріх і нечистоту́ впа́дшия, скве́рну гріха́ от'я́вши, із бе́здни поги́белі ізведи́; вдов бу́ди Уті́шительниця і Помо́щниця, ста́рости бу́ди жезл; от внеза́пния сме́рті без покая́нія всіх нас ізба́ви і всім нам христия́нськую кончи́ну живота́ на́шего, безболі́зненну, непости́дну, ми́рну і до́брий отві́т на Стра́шнім Суди́щі Христо́ві да́руй: преста́вльшіяся во ві́рі і покая́нії от житія́ сего́ со А́нгели і всі́ми святи́ми жи́ти сотвори́; сконча́вшимся внеза́пною сме́ртію ми́лостива би́ти Си́на Твоєго́ умоли́ і о всіх усо́пших, і́же не і́муть сро́дников, о упокоє́нії їх Си́на Твоєго́ умоляя́ющих, Сама́ бу́ди непреста́нная і те́плая Моли́твенниця і Хода́тайця: да всі на Небесі́ і на землі́ ві́дять Тя, я́ко тве́рдую і непости́дную Предста́тельницю ро́да христия́нськаго, і, ві́дуще, сла́в'ять Тя і Тобо́ю Си́на Твоєго́, с Безнача́льним Єго́ Отце́м і Єдиносу́щним Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Озерянська»","e":"Prayer to the Theotokos before her icon “Ozeryany”","secs":[{"h":"Тропар, глас 3","ps":["Твоєго́ предста́тельства увіре́ніє / і милосе́рдія Твоєго́ явле́ніє / іко́на Озеря́нськая нам, Влади́чице, показа́ся; / пред не́юже ду́ші на́ша в моли́тві ізлива́єм / і ві́рою Тебі́ вопіє́м: / воззри́, Милосе́рдная, на лю́ди Твоя́, / вся ско́рбі на́ша і печа́лі утоли́, / утіше́ніє благо́є в сердця́ на́ша низпосли́ // і спасе́ніє ві́чноє душа́м на́шим, Пречи́стая, іспроси́."]},{"h":"Кондак, глас 5","ps":["Не отри́ни, о Милосе́рдая Ма́ти, / слез і воздиха́ній на́ших, / но проше́нія на́ша ми́лостивно приї́мши, / пред іко́ною Твоє́ю моля́щихся люде́й ві́ру укріпи́, / умиле́нієм сердця́ їх іспо́лни і крест земна́го житія́ носи́ти їм помози́; // єли́ка бо хо́щеши, мо́жеши."]},{"h":"Молитва перша","ps":["Суєти́ жите́йськія возни́кше і ума́ своєго́ по́мисли во єди́но собра́вше, ко Твоє́й, Богоро́дице, іко́ні о́чі душ і тіле́с на́ших воздвиза́єм, і Тебі́ взива́єм си́це: не оста́ви, Пречи́стая, нас немощни́х во грісі́х на́ших растлі́тися, не попусти́ зло́му де́мону ду́ші на́ша от Си́на Твоєго́ в де́бри страсте́й отгна́ти, но помози́ нам Того́ за́повіді при́сно па́м'ятовати, да ніже́ блу́дним возбіше́нієм себі́ предає́м, ніже́ друг дру́га зло́бою угриза́єм, но я́коже днесь, святи́ні Твоє́й предстоя́ще, о ісправле́нії житія́ на́шего ре́вностію распаля́ємся, та́ко і от хра́ма Твоєго́ в до́ми своя́ отше́дше, сіє́ до́броє намі́реніє сохрани́ти потщі́мся. По сих же і тіле́сния на́ша ну́жди утоли́, і го́рести Твоє́ю моли́твою ісціли́, Всепі́тая. Ві́ми, я́ко подоба́ше нам па́че вся сія́ благоду́шне претерпіва́ти і то́чію о терпі́нії в ско́рбіх Го́спода проси́ти: но поне́же ізнемога́ють в печа́ліх ду́ші на́ша і по́мисли уни́нія на́шу коле́блють ві́ру, сего́ ра́ди в сокруше́нії серде́ць к Тебі́ си́це взива́єм: я́коже безчи́сленния боля́щия страда́льці ісціли́ла єси́ і скорб'я́щия уті́шила єси́, та́ко і нас пред чудотво́рною Твоє́ю іко́ною припа́дающих і в ско́рбі Тебі́ моля́щихся усли́ши, і всіх проше́нія во благо́є іспо́лни, боля́щим здра́віє, скорб'я́щим утіше́ніє подаю́щи, во вражді́ су́щим мир от Бо́га низпосила́ющи, сомня́щимся же ві́ри утвержде́ніє. Усли́ши грі́шния раби́ Твоя́, Пречи́стая, воздви́гни нас на благода́рственноє Ті славосло́віє, да умно́житься ві́ра люде́й Твої́х, да просла́виться в них Твоє́ заступле́ніє, да та́ко Ца́рствіє Си́на Твоєго́ посреди́ нас утверди́ться. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Преблагослове́нная Влади́чице на́ша Богоро́дице! К Тебі́, обре́тшей благода́ть пред Бо́гом, во є́же роди́ти ми́ру Спа́са душ на́ших, с Ним же у Креста́ Єго́ моли́твою за мир сраспина́вшаяся, і Ма́терію Сві́та Їм пронарече́нная, припа́дающе, мо́лимся. При́зри, Всеми́лостивая, на нас, Предві́чним Сові́том Пресвяти́я Тро́йці, к благода́тному наслі́дію жи́зні ві́чния созда́нних, жа́лом же гріхо́вним уя́звленних і сме́рті тіле́сній і душе́вній пове́рженних су́щих, і я́коже святу́ю іко́ну Твою́ Озеря́нськую пречу́дне срасти́вши, всім ві́рним істо́чник чуде́с от нея́ істочи́ла єси́, си́це же і нас, на Твою́, Богома́ти, іко́ну, благогові́йно взира́ющих, душе́вні і тіле́сні ісціли́, і немощно́є єстество́ на́ше, січе́нієм гріхо́вним разсека́ємоє, па́ки с Бо́гом соєдини́, і ча́дами Єго́ Боже́ственния любве́, си́лою і ді́йствієм Свята́го Ду́ха, нас соді́лай. Сердця́ же на́ша, Всеми́лостивая, благода́тію Христо́вою раствори́, і во́лю на́шу к ісполне́нію за́повідей Бо́жиїх спе́шну сотвори́, но́ги же на́ші на путь ми́рен — І́стину Христо́ву напра́ви. І си́це, о Всеблага́я, все єстество́ на́ше любо́вію к Бо́гу воспламени́. Влади́чице Пресвята́я, я́коже в тя́жком наше́ствії іноплеме́нник в преді́ли на́ша свято́ю іко́ною Твоє́ю Озеря́нською Правосла́вния лю́ди укрепля́ла єси́, та́ко і ни́ні зна́менієм Ли́ка сего́ Пресвята́го па́ству Ха́рковськую і всіх ві́рних чад страни́ на́шея в єдиноми́слії ві́ри утверди́, і от тлітво́рних раско́лов і єресе́й злочести́вих і іни́х бід сохрани́, Оте́честву же на́шему нези́блемаго ми́ра от Бо́га іспроси́, і от всіх враг, ми́слящих нам зла́я, нас ізба́ви. Ві́рних же Твої́х, пред свято́ю іко́ною Твоє́ю припа́дающих і в ско́рбіх Тебі́ моля́щихся, проше́нія іспо́лни, і вся, я́же ко спасе́нію потре́бная, всім нам да́руй. Убо́гія же сле́зи і воздиха́нія на́ша благоприя́тни пред Бо́гом сотвори́ і проще́ніє гріхо́в на́ших іспроси́. І та́ко, Преблагослове́нная Ма́ти, воздви́гни нас на благода́рственноє Ті славосло́віє, і в по́двизі покая́нія нас укріпля́ющи, неосужде́нних прича́стников Пречи́стаго Ті́ла і Честни́я Кро́ве Го́спода на́шего Ісу́са Христа́ по кончи́ні житія́ на́шего би́ти нас ми́лостивно сподо́би. В час же ісхо́да на́шего моли́тву Ма́тернюю о нас пред Бо́гом сотвори́, і бі́дния ду́ші на́ша чрез мита́рства лю́тия, нача́ла і вла́сті тьми, невозбра́нно в Ца́рствіє Небе́сноє, іді́же мир і ра́дость безконе́чная, приведи́, — во є́же в Це́ркві Небе́сній, Тобо́ю, Честні́йшею Херуви́м і Сла́внейшею без сравне́нія Серафи́м, укра́шенной, непреста́нно славосло́вити і воспіва́ти сме́рті Побіди́теля — А́гнця Бо́жия, взе́мшаго гріхи́ ми́ра. Єму́же, о Благода́тная, Тебе́ ра́ди, оса́нна і благодаре́ніє, сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і со Пресвяти́м, Благи́м і Животворя́щим Ду́хом — Уті́шителем Святи́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Утіха» або «Розрада»","e":"Prayer to the Theotokos before her icon “Consolation” or “Comfort”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грі́шнії і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній. / Не отврати́ Твоя́ раби́ тщи, // Тя бо і єди́ну наде́жду і́мами."]},{"h":"Інший тропар, глас 4","ps":["Я́ко покро́в благода́тний і спаси́тельний / стяжа́хом честну́ю Твою́ іко́ну, Богоро́дице, / на сію́ у́бо со умиле́нієм взира́юще, Тебі́ вопіє́м: / Влади́чице, ниспосли́ нам отра́ду і утіше́ніє, / на Тя бо упова́ніє возлага́єм, грі́шнії і смире́ннії. / На Твоє́ предста́тельство наді́ємся, недосто́йнії. / Ускори́ нас ізба́вити от бід і скорбе́й / і умоли́ Си́на Твоєго́, Христа́ Бо́га на́шего, // поми́ловати і спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді побіди́тельная, / я́ко ізба́вльшеся от злих, / благода́рственная воспису́єм Ті, раби́ Твої́, Богоро́дице, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва перша","ps":["Наде́жда всім конце́м землі́, Пречи́стая Ді́во Богоро́дице, Утіше́ніє і Отра́до на́ше! Не гнуша́йся нас грі́шних, на Твою́ бо ми́лость упова́єм. Угаси́ пла́мень гріхо́вний і покая́нієм ороси́ ізсо́хшиє сердця́ на́ша. Очи́сти ум наш от гріхо́вних помишле́ній. Прийми́ моле́нія от душі́ і се́рдця с воздиха́нієм Тебі́ приноси́мия. Бу́ди Хода́тайце о нас к Си́ну Твоєму́ і Бо́гу і отврати́ гнів Єго́ от нас Ма́терніми моли́твами. Укріпи́ в нас ві́ру правосла́вную, вложи́ в нас дух стра́ха Бо́жия, дух смире́нія, терпі́нія і любві́. Душе́вния і тіле́сния я́зви ісціли́, утиши́ бу́рю злих нападе́ній вра́жеських. Отими́ бре́м'я гріхо́в на́ших і не оста́ви нас до конця́ поги́бнути. Пода́ждь нам ми́лость Твою́ і свято́є благослове́ніє Своє́ всім зді предстоя́щим і моля́щимся і всегда́ пребива́й с на́ми, подава́я приходя́щим к Тебі́ отра́ду і утіше́ніє, по́мощ і заступле́ніє, да сла́вим і велича́єм Тя всі до послі́дняго на́шего воздиха́нія. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода, Цари́це Небесе́ і землі́! Воньми́ многоболі́зненному воздиха́нію душі́ на́шея, при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію поклоня́ющихся Пречи́стому о́бразу Твоєму́. Се бо гріхми́ погружа́ємії і скорбми́ обурева́ємії, взира́я на Твой о́браз, я́ко живі́й Ті су́щей с на́ми, прино́сим смире́нная моле́нія на́ша. Не і́мами бо ні іни́я по́мощі, ні іна́го предста́тельства, ні утіше́нія, то́кмо Тебі́, о Ма́ти всіх скорб'я́щих і обремене́нних! Помози́ нам не́мощним, утоли́ скорб на́шу, наста́ви на путь пра́вий нас заблужда́ющих, уврачу́й і спаси́ безнаде́жних, да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і тишині́ проводи́ти, пода́ждь христия́нськую кончи́ну, і на стра́шном суді́ Си́на Твоєго́ яви́ся нам Милосе́рдая Засту́пниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко благу́ю Засту́пницю ро́да христия́нськаго, со всі́ми угоди́вшими Бо́гу. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Печерська»","e":"Prayer to the Theotokos before her icon “of the Caves”","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло торжеству́єть Пече́рськая оби́тель / і ра́дується явле́нієм о́браза Богома́тере / безмі́рний лик Пече́рських отце́в, / с ни́миже і ми непреста́нно вопіє́м: // ра́дуйся, Благода́тная, Пече́рськая похвало́."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь неви́димо предстої́ть в це́ркві / і с ли́ки Пече́рських отце́в мо́литься о нас, / благогові́йно велича́ющих Єя́ безмі́рную ми́лость к ро́ду на́шему, / я́вльшуюся в чу́дном о́бразі Єя́, // оби́тель Пече́рськую украша́ющем."]},{"h":"Молитва","ps":["О, Пресвята́я і Пренепоро́чная Ді́во Богоро́дице, на́ша Пече́рськая похвало́ і украше́ніє, держа́вний покро́ве свята́го мі́ста сего́, і́стинная Влади́чице ізбра́ннаго уде́ла Своєго́. Прийми́ нас, недосто́йних рабо́в Твої́х, убо́гоє моле́ніє, с ві́рою і любо́вію принося́щих пред чу́дним о́бразом Твої́м, да посіти́ши ми́лостивно гріхо́вноє житіє́ на́ше, просвіща́ющи єго́ сві́том покая́нія, осіни́ нас, обремене́нних скорбми́ мно́гими, Твоє́ю Небе́сною ра́достію, сподо́би нас при́сно сла́вити Тя в ми́рі і благоче́стії на мі́сті святі́м сем, да, без поро́ка преше́дше путь житія́ на́шего, по́мощію Твоє́ю дости́гнем ві́чнаго весе́лія во сві́тлості святи́х і Богоно́сних оте́ць на́ших Анто́нія і Феодо́сія і всіх преподо́бних Пече́рських і єди́ними усти́ і се́рдці воспої́м Тя с Предві́чним Си́ном Твої́м і Безнача́льним Єго́ Отце́м і Пресвяти́м, Животворя́щим, Всеблаги́м і Єдиносу́щним Єго́ Ду́хом во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Почаївська»","e":"Prayer to the Theotokos before her icon “Pochaiv”","secs":[{"h":"Тропар, глас 5","ps":["Пред свято́ю Твоє́ю іко́ною, Влади́чице, / моля́щіїся ісціле́ній сподобля́ються, / ві́ри і́стинния позна́ніє приє́млють / і ага́рянськая наше́ствія отража́ють. / Ті́мже і нам, к Тебі́ припа́дающим, / гріхо́в оставле́ніє іспроси́, / по́мисли благоче́стія сердця́ на́ша просвіти́, / і к Си́ну Твоєму́ моли́тву вознеси́ // о спасе́нії душ на́ших."]},{"h":"Інший тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м грі́шнії і смире́ннії, і припаде́м к ди́вному о́бразу Єя́, і́же на горі́ Поча́євстій: к нему́же уми́льно взира́юще і моля́щеся Цари́це Влади́чице із глубини́ душе́вния вопіє́м: О Пречу́дная Ді́во, Ма́ти Го́спода Ви́шняго, от літ дре́вніх ізбра́вшая оби́тель Поча́євськую в мі́сто селе́нія Своєго́! Зе́млю оте́чественную на́шу в правосла́вії і ми́ре утверди́, і спаси́ всіх предстоя́щих і моля́щихся Тебі́ умиле́нною душе́ю і сокруше́нним се́рдцем, пред Пречи́стим Твої́м о́бразом со слеза́ми. Не отврати́ раби́ Твоя́ тщи: Тя бо єди́ну Наде́жду і́мами."]},{"h":"Кондак, глас 1","ps":["Істо́чник ісціле́ній і ві́ри Правосла́вния утвержде́ніє / Поча́євськая Твоя́ іко́на, Богоро́дице, яви́ся, / ті́мже і нас, к ней притека́ющих, / от бід і іскуше́ній свободи́. / ла́вру Твою́ невріди́му сохрани́, / Правосла́віє во о́крест стоя́щих страна́х утверди́, / і гріхи́ разріши́ моли́твенник Твої́х: // єли́ка бо хо́щещі, мо́жеши."]},{"h":"Молитва перша","ps":["К Тебі́, о Богома́ти, моли́твенно притека́єм ми, грі́шнії, чудеса́ Твоя́, во святі́й ла́вре Поча́євстій явле́нная, помина́юще і о свої́х сокруша́ющеся прегріше́ніїх. Ві́ми, Влади́чице, ві́ми, я́ко не подоба́ше нам, грі́шним, чесого́ проси́ти, то́кмо о є́же Пра́ведному Судії́ беззако́нія на́ша оста́вити нам. Вся бо на́ми в житії́ претерпі́нная, ско́рби же, і ну́жди, і болі́зні, я́ко плоди́ паде́ній на́ших прозябо́ша нам, Бо́гу сія́ на ісправле́ніє на́ше попуща́ющу. Ті́мже вся сія́ і́стиною і су́дом Свої́м наведе́ Госпо́дь на грі́шния раби́ Своя́, і́же в печа́ліх свої́х к заступле́нію Твоєму́, Пречи́стая, притеко́ша і во умиле́нії серде́ць к Тебі́ взива́ють си́це: гріхо́в і беззако́ній на́ших, Блага́я, не пом'яни́, но па́че всечестні́ї ру́ці Твої́ воздви́гши, к Си́ну Твоєму́ і Бо́гу предста́ни, да лю́ті соді́янная на́ми отпу́стить нам, да за премно́гая неіспо́лненная обіща́нія на́ша лиця́ Своєго́ от рабо́в Свої́х не отврати́ть, да благода́ті Своєя́, спасе́нію на́шему посо́бствующия, от душ на́ших не оти́меть. Єй, Влади́чице, бу́ди спасе́нію на́шему Хода́тайця і, малоду́шія на́шего не возгнуша́вшися, при́зри на стена́нія на́ша, я́же в біда́х і ско́рбіх на́ших пред чудотво́рним Твої́м о́бразом возно́сим. Просвіти́ умиле́нними по́мисли уми́ на́ша, ві́ру на́шу укріпи́, наде́жду утверди́, любве́ сладча́йший дар сподо́би нас прия́ти. Си́ми у́бо, Пречи́стая, дарова́ньми, а не болі́зньми і скорбми́ живо́т наш ко спасе́нію да возво́диться, но, от уни́нія і отча́янія ду́ші на́ша огражда́ющи, ізба́ви нас, маломо́щних, от находя́щих на ни бід, і нужд, і клевети́ челові́чеськія, і болі́зней нестерпи́мих. Да́руй мир і благоустроє́ніє жи́тельству христия́нському предста́тельством Твої́м, Влади́чице, утверди́ Правосла́вную ві́ру в страні́ на́шей і во всем ми́рі. Це́рков Апо́стольськую і Собо́рную умале́нію не преда́ждь, уста́ви святи́х оте́ць на ві́ки непоколеби́ми сохрани́ і всіх к Тебі́ притека́ющих от ро́ва поги́бельнаго спаси́. Єще́ же і є́ресію прельще́нних бра́тій на́ших іли́ ві́ру спаси́тельную в гріхо́вних страстеіх погуби́вших па́ки ко і́стинній ві́рі і покая́нію приведи́, да вку́пі с на́ми, Твоєму́ чудотво́рному о́бразу покланя́ющеся, Твоє́ предста́тельство іспові́дять. Сподо́би у́бо нас, Пресвята́я Госпоже́ Богоро́дице, єще́ в животі́ сем побі́ду і́стини Твої́м заступле́нієм узрі́ти, сподо́би нас благода́тную ра́дость пре́жде кончи́ни на́шея восприя́ти, я́коже дре́вле насе́льники Поча́євськия Твої́м явле́нієм побіди́телі і просвіти́телі ага́рян показа́ла єси́, да всі ми благода́рним се́рдцем вку́пі со А́нгели, і проро́ки, і апо́столи, і со всі́ми святи́ми, Твоє́ милосе́рдіє прославля́юще, воздади́м сла́ву, честь і поклоне́ніє в Тро́йці піва́ємому Бо́гу Отцю́, і Си́ну, і Свято́му Ду́ху, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, Всеми́лостивая Госпоже́, Цари́це і Влади́чице, от всіх родо́в ізбра́нная, і всі́ми ро́ди Небе́сними і земни́ми ублажа́ємая! Воззри́ ми́лостивно на предстоя́щий пред свято́ю іко́ною Твоє́ю і усе́рдно к Тебі́ моля́щийся наро́д сей, і сотвори́ предста́тельством і заступле́нієм Твої́м у Си́на Твоєго́ і Бо́га на́шего, да нікто́же ізи́деть отсю́ду упова́нія своєго́ тощ і посра́млен в наде́жді своє́й, но да при́йметь ки́йждо от Тебе́ вся, по благо́му ізволе́нію се́рдця своєго́ і по нужді́ і потре́бі своє́й, во спасе́ніє душі́ і во здра́віє ті́лу. При́зри благосе́рдієм, Всепі́тая Богоро́дице, і на оби́тель сію́, Твої́м і́менем нариця́ющуюся, ю́же от літ дре́вніх возлюби́ла єси́, ізбра́вши єє́ в достоя́ніє себе́, і неоску́дно істоча́ющи то́ки ісціле́ній от чудотво́рния іко́ни Твоєя́ і от приснотеку́щаго істо́чника, в слі́ді стопи́ Твоєя́, нам откри́таго, і сохрани́ ю от вся́каго прило́га і наві́та вра́жия, я́коже дре́вле сохрани́ла єси́ Твої́м явле́нієм ці́лу і неврежде́нну от лю́таго наше́ствія ага́рянскаго, да ви́ну воспіва́ється і сла́виться в ней Пресвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха, і Твоє́ пресла́вноє успе́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, Пресвята́я Ді́во, Влади́чице Богоро́дице! Благодарю́ Тя от всего́ се́рдця моєго́, я́ко сподо́била м'я єси́ грі́шнаго і недосто́йнаго раба́ Твоєго́ предста́ти зді і покланя́тися на святі́й горі́ Твоє́й. О, коли́ких благ удосто́їхся та́ко многогрі́шний аз милосе́рдієм Твої́м. Ви́жду, Пречи́стая, і ужаса́юся, і істаєва́єть дух мой, зря воо́чію многоціле́бний сей істо́чник благода́ті Твоєя́, єго́же іздре́вле во слі́ді святи́я стопи́ Твоєя́ неізрече́нно яви́ла єси́, і всеблагогові́йно покланя́ємся на мі́сті, іді́же стоя́сте Діви́честії но́зі Твої́, молю́ Тя, благослове́нная Наде́ждо і Спасе́ніє душ і тіле́с на́ших: оми́й м'я цільбоно́сною водо́ю Твоє́ю от вся́кия скве́рни пло́ті і ду́ха, утоли́ благода́тними струя́ми Твої́ми вся стра́сті моя́ серде́чния, уврачу́й ка́плями от приснотеку́щаго істо́чника Твоєго́ вся неду́ги моя́ тіле́сния, да, Тобо́ю наставля́ємий, врачу́ємий і ізбавля́ємий, воспіва́ю Тебі́ всеусе́рдно: Ра́дуйся, істо́чниче ра́дости непреста́ємия, ра́дуйся, то́че добро́ти неізрече́нния. Ра́дуйся, вожделі́ній нечи́стих потопле́ніє, ра́дуйся, скверн вся́ких ізмове́ніє. Ра́дуйся, струє́ світови́днійшая во здра́віє ві́рним от гори́ приосіне́нния ча́щи благода́ть ісціле́ній подава́ющая, ра́дуйся, росо́ небе́сная, сви́ше то́ки прему́дрости жа́ждущим і́стиннаго позна́нія ниспосила́ющая. Ра́дуйся, похвало́ Поча́євськая, спаси́ ни, моля́щіяся Тебі́, Наде́ждо на́ша і утіше́ніє. Амі́нь."]},{"h":"Молитва четверта","ps":["Цари́це на́ша Преблага́я, Влади́чице Преблагослове́нная, Наде́ждо на́ша Богоро́дице! К Тебі́ умиле́нно ни́ні притека́єм, і сокруше́нною душе́ю і смире́нним се́рдцем мо́лим Тя, Всепі́тая, пред Пречи́стим Твої́м о́бразом: пом'яни́ щедро́ти Твоя́ дре́внія, я́же от Тебе́ зді би́вшия, і я́коже іногда́ яви́лася єси́ на скалі́ Поча́євстій, в столпі́ о́гненнім, от ка́мене цільбоно́сную во́ду істоча́ющи, си́це і ни́ні предста́ни нам, Ма́ти многомо́щная, і теплото́ю Богома́тернія любве́ Твоєя́ согрі́й сердця́ на́ша окамене́нная, сле́зи любве́ і покая́нія нераска́яннаго от оче́й на́ших історга́ющи. Ти бо єди́на єси́ Засту́пниця на́ша Богодарова́нная: Тя у́бо мо́лим, ізба́ви от всіх бід, от вся́кия напа́сти, болі́зні і ско́рби, раби́ Твоя́, предста́тельством вели́каго о нас хода́тая і моли́твенника Твоєго́, всеблаже́ннаго отця́ на́шего І́ова, уго́дника Твоєго́ Поча́євськаго, єго́же моли́тві я́ві внима́ла єси́ на возду́сі іногда́, єгда́ всесла́вним і стра́шним явле́нієм Твої́м ізба́вила єси́ оби́тель Твою́ от наше́ствія і обложе́нія ага́рянськаго. При́зри благосе́рдієм, Всепі́тая, призрі́нієм ми́лостиваго Твоєго́ заступле́нія і на все ца́рства і страну́ на́шу, і на вся лю́ди Твоя́ ізле́й бога́тия Твоя́ ми́лості: разсе́янниє собери́, неві́рния же і інові́рния, во страна́х на́ших, на путь і́стинний наста́ви, отпа́дшия от благочести́вия оте́чеськия ві́ри па́ки возврати́ і сопричти́ їх Святі́й Твоє́й Правосла́вній і Кафоли́честій Це́ркві; в семе́йствах на́ших мир утверди́, ста́рость поддержи́, ю́ния наста́ви, младе́нці воспита́й, си́рия і вдови́ці заступи́, пліне́нния свободи́, боля́щия уврачу́й, на суди́щі і в темни́цях, і в заточе́ніїх, і в го́рких рабо́тах су́щих пом'яни́, огражда́ющи ни ви́ну, посіща́ющи і утеша́ющи то́ками чуде́с і зна́меній многоразли́чних, я́же при́сно ізлива́єши всім от святи́я іко́ни Твоєя́ цільбоно́сния. Да́руй, Всеблага́я, землі́ плодоро́діє, возду́ха благорастворе́ніє і вся, я́же на по́льзу на́шу да́ри благовре́менния і благопотре́бния, моли́твами ізбра́нних уго́дников Твої́х, благода́тний Твой лик на святі́й іко́ні Твоє́й окружа́ющих: Ілії́ богоглаго́ливаго, свята́го архідия́кона Стефа́на первострада́льнаго, преподо́бнаго Авраа́мія всеблаже́ннаго, і богому́жнаго Ми́ни му́ченика многоімени́таго, і с ни́ми ку́пно святи́х і пра́ведних жен: Параске́ви прехва́льния, Іри́ни преблаже́нния і святи́я Єкатери́ни великому́ченици многострада́льния, і всіх святи́х. Єгда́ же приспі́єть на́ше от житія́ сего́ отше́ствіє і к ві́чності переселе́ніє, си́це предста́ни нам, Преблагослове́нная, я́коже іногда́ благопоспеши́ла єси́ оби́телі Твоє́й во спасе́ніє во вре́м'я бра́ні Збаражськой, і Твої́м те́плим хода́тайством да́руй нам христия́нськую кончи́ну живота́ на́шего безболі́зненну, непости́дно, ми́рну і Святи́х Та́їн прича́стну; да я́коже в сей жи́зні, си́це і в бу́дущем ві́ці сподо́бимся всі, моли́твами Твої́ми, безконе́чния Небе́сния жи́зні во Ца́рствії возлю́бленнаго Си́на Твоєго́, Го́спода Бо́га і Спа́са на́шего, Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і почита́єм честну́ю іко́ну Твою́, / ю́же от літ дре́вніх // на горі́ Поча́євстій просла́вила єси́."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Рудненська»","e":"Prayer to the Theotokos before her icon “Rudna”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грішні́ї і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній, / не отврати́ Твоя́ раби́ тщи: // Тя бо і єди́ну наде́жду і́мами."]},{"h":"Інший тропар, глас 4","ps":["Не умолчи́м нікогда́, Богоро́дице, / си́ли Твоя́ глаго́лати недосто́йнії: / а́ще бо Ти не би предстоя́ла моля́щи, / кто би нас ізба́вил от толи́ких бід? / Кто же би сохрани́л до ни́ні свобо́дні? / Не отсту́пим, Влади́чице, от Тебе́: // Твоя́ бо раби́ спаса́єши при́сно от вся́ких лю́тих."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице, / Ти нам помози́: / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, // да не постиді́мся."]},{"h":"Молитва","ps":["Пресвята́я Ді́во Влади́чице Богоро́дице, ми́лосте Христа́ моєго́, оби́телище Пресвята́го і Животворя́щаго Ду́ха, наде́ждо всіх святи́х раб, свято́є зерца́ло сві́тлости Бо́жия, святі́йшая А́нгел і Арха́нгел, Тебі́ припа́дая, усе́рдно молю́ся: умоли́ Си́на Своєго́ і Бо́га моєго́, да отпу́стить мі вся́коє прегріше́ніє, во́льноє і нево́льноє, ізба́вить м'я от всіх наві́тов дия́вольських. Єй, Влади́чице, моєго́ паде́нія возведе́ніє, простри́ богоно́снеї Свої́ ру́ці і ізвлеци́ м'я із глубини́ гріхо́вния і даждь мі, рабу́ Твоєму́ (і́м'я рек), всегда́ уго́дная Си́ну Твоєму́ і Бо́гу моєму́ твори́ти, сла́в'я Єго́ вку́пі со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Семистрільна» або «Пом’якшення злих сердець»","e":"Prayer to the Theotokos before her icon “Seven Arrows” or “Softener of Evil Hearts”","secs":[{"h":"Тропар, глас 5","ps":["Ум'ягчи́ на́ша зла́я сердца́, Богоро́дице, / і напа́сти ненави́дящих нас угаси́ / і вся́кую тісноту́ душі́ на́шея разріши́, / на Твой бо святи́й о́браз взира́юще, / Твої́м сострада́нієм і милосе́рдієм о нас умиля́ємся / і ра́ни Твоя́ лобиза́єм, / стріл же на́ших, Тя терза́ющих, ужаса́ємся. / Не даждь нам, Ма́ти Благосе́рдая, / в жестокосе́рдії на́шем і от жестокосе́рдія бли́жніх поги́бнути, // Ти бо єси́ воі́стину злих серде́ць ум'ягче́ніє."]},{"h":"Кондак, глас 2","ps":["Благода́тію Твоє́ю, Влади́чице, / ум'ягчи́ сердця́ злоді́єв, / низпосли́ благоді́телей, / соблюда́ющи їх от вся́каго зла, / благомоля́щимся Ті усе́рдно // пред честни́ми іко́нами Твої́ми."]},{"h":"Молитва перша","ps":["О Многоско́рбная Ма́ти Бо́жия, преви́шшая всіх дще́рей землі́ по чистоті́ Своє́й і по мно́жеству страда́ній, Тобо́ю на землі́ пренесе́нних! Прийми́ многоболе́зненная воздиха́нія на́ша і сохрани́ нас под кро́вом Твоєя́ ми́лости, іна́го бо прибі́жища і те́плаго предста́тельства, ра́зві Тебе́, не ві́ми, но, я́ко дерзнове́ніє іму́щи к І́же от Тебе́ Рожде́нному, помози́ і спаси́ ни моли́твами Свої́ми, да непреткнове́нно дости́гнем Ца́рствія Небе́снаго, іді́же со всі́ми святи́ми бу́дем воспіва́ти хвалу́ в Тро́йці Єди́ному Бо́гу, всегда́, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О кто не ублажи́ть Тя, Ді́во Благода́тная, кто не воспоє́ть Твоє́ милосе́рдіє к ро́ду челові́чеському. Тебі́ мо́лимся, Тя про́сим: не оста́ви нас, во злі погиба́ющих, раствори́ любо́вію сердця́ на́ша і ко врага́м на́шим пошли́ стрілу́ Свою́, да уязвля́єть сердця́ на́ша ми́ром ко гоня́щим нас. А́ще мир нас ненави́дить — Ти простри́ любо́в Свою́ к нам, а́ще мир нас го́нить — Ти прийми́ нас. Пода́ждь нам Благода́тную си́лу терпі́нія — без ро́пота перенести́ іспита́нія, в ми́рі сем бива́ємая. О Госпожі́! Ум'ягчи́ сердця́ злих челові́ков, восстаю́щих на нас, да не поги́бнуть сердця́ їх во злі, но умоли́, Благода́тная, Си́на Твоєго́ і Бо́га на́шего, да умири́ть сердця́ їх ми́ром, дия́вол же — оте́ць зло́би — да посрами́ться! Ми же, воспіва́юще милосе́рдіє Твоє́ к нам, злим, непотре́бним, воспоє́м Ті, о Пречу́дная Госпоже́ Ді́во Благода́тная: усли́ши нас в час сей, сокруше́нная сердца́ іму́щих, огради́ нас ми́ром і любо́вію друг ко дру́гу і ко враго́м на́шим, іскорени́ от нас вся́кую зло́бу і вражду́, да воспоє́м Тебі́ і Си́ну Твоєму́, Го́споду Ісу́су Христу́ на́шему: Аллилу́я! Аллилу́я! Аллилу́я!"]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Скоропослушниця»","e":"Prayer to the Theotokos before her icon “Quick to Hear”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці притеце́м, су́щії в біда́х, / і святі́й іко́ні Єя́ ни́ні припаде́м, / с ві́рою зову́ще із глубини́ душі́: / ско́ро на́ше усли́ши моле́ніє, Ді́во, / я́ко Скоропослу́шниця наре́кшаяся, / Тебі́ бо раби́ Твої́ в ну́ждах // гото́вую Помо́щницю і́мами."]},{"h":"Кондак, глас 8","ps":["В мо́рі жите́йстім обурева́ємії, / треволне́нію подпа́даєм страсте́й і іскуше́ній. / Пода́ждь у́бо нам, Госпоже́, ру́ку по́мощі, я́коже Петро́ві Син Твой, / і ускори́ от бід ізба́вити ни, да зове́м Ті: // ра́дуйся, всеблага́я Скоропослу́шнице."]},{"h":"Молитва перша","ps":["Преблагослове́нная Влади́чице, Присноді́во Богоро́дице, Бо́га Сло́ва па́че вся́каго сло́ва на спасе́ніє на́ше ро́ждшая, і благода́ть Єго́ преізоби́льно па́че всіх прия́вшая, мо́ре я́вльшаяся Боже́ственних дарова́ній і чуде́с приснотеку́щая ріка́, ізлива́ющая бла́гость всім, с ві́рою к Тебі́ прибега́ющим! Чудотво́рному Твоєму́ о́бразу припа́дающе, мо́лимся Тебі́, всеще́дрій Ма́тері Человіколюби́ваго Влади́ки: удиви́ на нас пребога́тия ми́лості Твоя́, і проше́нія на́ша, приноси́мая Тебі́, Скоропослу́шнице, ускори́ іспо́лнити, все, є́же на по́льзу во утіше́ніє і спасе́ніє коєму́ждо устроя́ющи. Посіти́, Преблага́я, раби́ Твоя́ благода́тію Твоє́ю, пода́ждь неду́гующим цільбу́ і соверше́нноє здра́віє, обурева́ємим тишину́, пліне́нним свобо́ду і разли́чними о́брази стра́ждущих уті́ши, ізба́ви, всеми́лостивая Госпоже́, всяк град і страну́ от гла́да, я́зви, тру́са, пото́па, огня́, меча́ і іни́я ка́зні вре́менния і ві́чния, Ма́терним Твої́м дерзнове́нієм отвраща́ющи гнів Бо́жий: і душе́внаго разслабле́нія, обурева́нія страсте́й і гріхопаде́ній свободи́ раби́ Твоя́, я́ко да непреткнове́нно во вся́ком благоче́стії пожи́вше в сем ві́ці, і в бу́дущем ві́чних благ сподо́бимся благода́тію і человіколю́бієм Си́на Твоєго́ і Бо́га, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода Ви́шняго, Скоропослу́шная Засту́пнице всіх, к Тебі́ с ві́рою прибіга́ющих! При́зри с висоти́ небе́снаго вели́чія Своєго́ на мене́ непотре́бнаго, припа́дающаго к іко́ні Твоє́й, усли́ши ско́ро смире́нную моли́тву мене́ грі́шнаго і принеси́ ю к Си́ну Своєму́: умоли́ Єго́, да озари́ть мра́чную ду́шу мою́ сві́том Боже́ственния благода́ті Своєя́ і очи́стить ум мой от по́мислов су́єтних, да успоко́їть стра́ждущеє моє́ се́рдце і ісціли́ть ра́ни єго́, да вразуми́ть м'я на до́брая діла́ і укріпи́ть рабо́тати Єму́ со стра́хом, да прости́ть вся соді́янная мно́ю зла́я, да ізба́вить ві́чния му́ки і не лиши́ть Небе́снаго Своєго́ Ца́рствія. О Преблагослове́нная Богоро́дице: Ти благоізво́лила єси́ нарещи́ся во о́бразі Своє́м Скоропослу́шниця, повеліва́ющи всім притека́ти к Тебі́ с ві́рою: не пре́зри у́бо мене́ ско́рбнаго і не попусти́ поги́бнути мні в бе́здні гріхо́в мої́х. На Тя по Бо́зі все моє́ упова́ніє і наде́жда спасе́нія, і Твоєму́ покро́ву і предста́тельству поруча́ю себе́ во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Одигітрія» Смоленська (Путівниця)","e":"Prayer to the Theotokos before her icon “Hodegetria” of Smolensk (She Who Shows the Way)","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, / грішні́ї і смире́ннії, і припаде́м, / в покая́нії зову́ще із глубини́ душі́: / Влади́чице, помози́, на ни милосе́рдовавши, / потщи́ся, погиба́єм от мно́жества прегріше́ній, / не отврати́ Твоя́ раби́ тщи, // Тя бо і Єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, / ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Інший кондак, глас 6","ps":["Не і́мами іни́я по́мощі, / не і́мами іни́я наде́жди, / ра́зві Тебе́, Влади́чице, / Ти нам помози́, / на Тебі́ наді́ємся / і Тобо́ю хва́лимся, / Твої́ бо єсьми́ раби́, / да не постиді́мся."]},{"h":"Молитва","ps":["Ко кому́ возопію́, Влади́чице? Ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач мой усли́шить і воздиха́ніє при́йметь, а́ще не Ти, Пренепоро́чная, Наде́ждо христия́н і Прибі́жище нам, грі́шним? Кто па́че Тебі́ в несча́стіїх защити́ть? Усли́ши стена́ніє моє́ і приклони́ у́хо Твоє́ ко мні, Влади́чице і Ма́ти Бо́га моєго́. Не пре́зри і́щущаго Твоєя́ по́мощі і не отри́ни мене́ грі́шнаго, Цари́це Небе́сная! Научи́ мене́ ісполня́ти во́лю Си́на Твоєго́ і да́руй жела́ніє всегда́ слі́довати Єго́ святи́м за́повідем. За мой ро́пот в боле́знях, труда́х і несча́стіях не отступи́ от мене́, но бу́ди Ма́терію і Покрови́тельницею мене́ малоду́шнаго, Цари́це моя́ Преблага́я, Засту́пнице Усе́рдная! Твої́м хода́тайством прегріше́нія моя́ покри́й, от ви́димих і неви́димих враго́в защити́, сердца́ вражду́ющих про́тив мене́ см'ягчи́ і Христо́вою любо́вію согрі́й їх. Мні же немощно́му да́руй Твою́ всеси́льную по́мощ побіди́ти моя́ гріхо́вния приви́чки, да́би, очище́нний покая́нієм і после́дующею доброді́тельною жи́знію, в обще́нії со Свято́ю Це́рковю прове́л остальни́я дні земна́го стра́нствія. Предста́ни мні, Наде́ждо всіх христия́н, в час кончи́ни моєя́ і подкріпи́ мою́ ві́ру в сме́ртний тя́жкий час. Вознеси́ за мене́, многопрегреша́ющаго в жи́зні сей, Твоя́ всеси́льния моли́тви по отше́ствії моє́м, да оправда́єть мене́ Госпо́дь і соді́лаєть прича́стником Єго́ бесконе́чних ра́достей. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Софія, Премудрість Божа» (Новгородська)","e":"Prayer to the Theotokos before her icon “Sophia, the Wisdom of God” (of Novgorod)","secs":[{"h":"Тропар, глас 1","ps":["Преві́чная Прему́дросте, Христе́ Бо́же наш! / Боже́ственним смотре́нієм Свої́м преклони́вий Небеса́, / благоволи́л єси́ всели́тися во утро́бу Чи́стия Отрокови́ці, / средості́ніє вражди́ разруши́в, / освяти́л єси́ єстество́ на́ше / і Ца́рствіє Твоє́ нам отве́рзл єси́; / сего́ ра́ди Тебе́, Творця́ на́шего і Ізба́вителя, / і ро́ждшую Тя, / спасе́нія на́шего та́йні послужи́вшую Ді́ву Чи́стую, // правосла́вно велича́єм."]},{"h":"Інший тропар, глас 4","ps":["Ве́лія і неізрече́нная Прему́дрости Бо́жії си́ла / смотре́нія плотська́го та́їнства! / Софі́є Преймени́тая, / ді́вственних душе́ і неізглаго́ланнаго ді́вства чистото́, / смире́нния му́дрости і́стино, / поко́їще Свята́го Ду́ха, / пречестни́й хра́мі непостижи́мия сла́ви Єго́, / огнезра́чний престо́ле Христа́ Бо́га на́шего, / в Тя бо всели́ся неізрече́нно Сло́во Бо́жиє, і плоть бисть, / Неви́димий яви́ся, / і неприкоснове́нний із Тебе́ ізи́де, / і с челові́ки поживе́, врага́ іско́ннаго уловля́я / і челові́ки от кля́тви дре́внія свобожда́я, / возводя́ па́ки, отню́дуже іспадо́хом. / Мо́лимтися, Влади́чице, / отягче́нния ни во грісі́х лю́тих поми́ловати / і спасти́ ду́ші на́ша, / і, я́ко человіколюби́вая і милосе́рдая Цари́ця, / Ма́ти Прему́дрости Бо́жия Сло́ва, / при́зри на ни, грі́шния лю́ди Твоя́, / і умилосе́рдися, заступи́ от напа́стей і скорбе́й лю́тих / і гра́ди на́ша невреди́ми сохрани́, // іді́же ни́ні і́м'я Твоє́ пресвято́є боголі́пно сла́виться."]},{"h":"Кондак, глас 4","ps":["Притеце́м, правосла́внії лю́діє, / к прему́дрости Бо́жії / і ви́дим чудотво́рную іко́ну Пречи́стия Богома́тере, / Ю́же імену́єм по явле́нію Софі́ю, Прему́дрость Бо́жию, / зане́ храм бисть одушевле́н Єдиноро́днаго Си́на і Сло́ва Бо́жия. / Сія́ у́бо світолу́чно сія́єть в пречестні́м хра́мі Своє́м / і сердця́ на́ша весели́ть, приходя́щих с ві́рою / і взира́ющих со стра́хом і благогові́нієм на пречи́стую сію́ іко́ну, / помишля́юще в сердця́х на́ших, / я́ко воі́стину Прему́дрости Бо́жії єсть се́леніє / і та́їнства Єго́ смотре́ніє, / на упова́ніє бо ві́рним / воображе́ніє огнезра́чноє Єя́ зрим / і покланя́ємся, я́ко і́стинному і пренепоро́чному Єя́ ді́вству / в рождестві́ і по рождестві́ па́ки; / от Нея́же ізи́де Огнь Боже́ственний, / попаля́я тлі́нния стра́сті / і просвіща́я ду́ші на́ша і чи́сти сотворя́я, / І́мже і ві́ки сотвори́ Оте́ць, / Той же і Му́дрость, Сло́во і Си́ла нарече́ться, / сія́ніє сла́ви і О́браз О́тчі Іпоста́си. / І па́ки у́бо мо́лим / і, припа́дающе, лобиза́єм пречестну́ю іко́ну Прему́дрости Бо́жия Ма́тере / і велегла́сно вопіє́м: / о Милосе́рдая Влади́чице, / спаси́ раби́ Своя́ от наси́лія дия́воля, / от нахожде́нія іноплеме́нних і междоусо́бния бра́ні, / я́ко Ти єси́ всіх благи́х Пода́тельниця і Покрови́тельниця // притека́ющим к Тебі́ с ві́рою і прося́щим ве́лія ми́лости."]},{"h":"Інший кондак, глас 8","ps":["Притеце́м, лю́діє, к чу́дному о́бразу Прему́дрости Бо́жії, Цари́ці і Богоро́диці: / Царя́ Небе́снаго Ма́ти, Христа́ Бо́га на́шего, / усли́ши нас, грі́шних і недосто́йних раб Твої́х, / в час сей припа́дающих і моля́щихся с воздиха́нієм і слеза́ми, / уми́льно глаго́лющих і прилі́жно вопію́щих: / от бід ізба́ви нас, Влади́чице, / і заступи́, і не пре́зри воздиха́нія на́шего і слез, / і ізми́ нас от вся́кия ско́рби і напа́сти, я́ко мо́жеши, хотя́щи, / ра́зві Тебе́ Предста́тельниці іни́я і хода́тая те́пла не і́мами к Си́ну Твоєму́ і Бо́гу на́шему, // да спасе́ть Тебе́ ра́ди ду́ші на́ша."]},{"h":"Молитва","ps":["Непостижи́мая і Всепі́тая Прему́дросте Бо́жия, Софі́є Преймени́тая, ді́вственних ду́ше, си́річ Єдиноро́дний Си́не, Сло́ве Бо́жий, прийми́ моле́бноє сіє́ пі́ніє от недосто́йних і скве́рних уст на́ших. А́ще і пи́сана суть: не красна́ піснь во усті́х грі́шничих, оба́че же разбо́йник єди́нім сло́вом спасе́ся, мита́р воздиха́нієм оправда́ся і ханане́їна дщер ма́тернім проше́нієм ісціли́ся, поне́же Ти, Го́споди, Благ і Человіколюби́в, гряду́щаго в мир просвіща́єши, і гріхи́ грі́шником отпуща́єши, і ра́зумом неразу́мних наполня́єши, і бу́їяго умудря́єши, і жа́ждущия благи́х слове́с ду́ші уче́нієм Твої́м, я́ко самаряни́ню водо́ю живо́ю, напая́єши, блудника́ цілому́дренна устроя́єши, разбо́йнику рай отверза́єши, зане́ Ти єси́ всіх благи́х Пода́тель, і Вразуми́тель, і животу́ Храни́тель, Христе́ Бо́же наш, і Тебі́ сла́ву і хвалу́, честь і благодаре́ніє і славословле́ніє возсила́єм і поклоне́ніє твори́м со Безнача́льним Твої́м Отце́м, і со Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, і со Пресвято́ю і Пренепоро́чною Твоє́ю Ма́терію, Влади́чицею на́шею Богоро́дицею і Присноді́вою Марі́єю, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Поручителька грішних»","e":"Prayer to the Theotokos before her icon “Surety of Sinners”","secs":[{"h":"Тропар, глас 4","ps":["Умолка́єть ни́ні вся́коє уни́ніє / і страх отча́янія ісчеза́єть, / грі́шници в ско́рбі се́рдця обріта́ють утіше́ніє / і Небе́сною любо́вію озаря́ються сві́тло: / днесь бо Ма́тер Бо́жия простира́єть нам спаса́ющую ру́ку / і от Пречи́стаго о́браза Своєго́ віща́єть, глаго́лющи: / Аз Спору́чниця грі́шних к Моєму́ Си́ну, / Сей дал Мні за них ру́ці сли́шати М'я ви́ну. / Ті́мже, лю́діє, обремене́ннії гріхи́ мно́гими, / припаді́те к подно́жію іко́ни Єя́, со слеза́ми вопію́ще: / Засту́пнице ми́ра, грі́шним Спору́чнице, / умоли́ Ма́терніми Твої́ми моли́твами Ізба́вителя всіх, / да Боже́ственним всепроще́нієм покри́єть гріхи́ на́ша / і сві́тлия две́рі ра́йськія отве́рзеть нам, // Ти бо єси́ предста́тельство і спасе́ніє ро́да христия́нськаго."]},{"h":"Інший тропар, глас 3","ps":["Тебі́, милосе́рдія істо́чнику при́сно теку́щему / і Спору́чнице грі́шних, недосто́йнії раби́ Твої́, Богоро́дице, / припа́дающе, скорб'я́ще, вопіє́м Ті: / спаса́й нас от бід, Влади́чице, // і ма́терним Твої́м хода́тайством іспроси́ всім нам ві́чноє спасе́ніє."]},{"h":"Кондак, глас 1","ps":["Честно́є жили́ще би́вшеє / неізрече́ннаго єстества́ Боже́ственнаго / ви́ше сло́ва і па́че ума́ / і грі́шним єси́ Спору́чниця, / подава́єши благода́ть і ісціле́ніє, / я́ко Ма́ти всіх Ца́рствующаго: / моли́ Си́на Твоєго́ // получи́ти нам ми́лость в День су́дний."]},{"h":"Молитва перша","ps":["О Влади́чице Преблагослове́нная, Защи́тнице ро́да христия́нськаго, прибі́жище і спасе́ніє притека́ющих к Тебі́! Вім, воі́стину вім, я́ко зіло́ согріши́х і прогні́вах, Преми́лостивая Госпоже́, рожде́ннаго пло́тію от Тебе́ Си́на Бо́жия: но і́мам мно́гії о́брази пре́жде мене́ прогні́вавших Єго́ благоутро́біє: митарі́, блудни́ці і про́чія грі́шники, і́мже даде́ся проще́ніє гріхо́в їх, покая́нія ра́ди і іспові́данія. Ти́я у́бо о́брази поми́лованних очесе́м грі́шния душі́ моєя́ представля́я і на толи́коє Бо́жиє милосе́рдіє, о́ніх приє́мшеє, взира́я, дерзну́х і аз грі́шний прибі́гнути с покая́нієм ко Твоєму́ благоутро́бію. О Всеми́лостивая Влади́чице, да пода́си мі ру́ку по́мощі і іспро́сиши у Си́на Твоєго́ і Бо́га ма́терніми і святі́йшими Твої́ми моли́твами тя́жким мої́м гріхо́м проще́ніє. Ві́рую і іспові́дую, я́ко Той, Єго́же родила́ єси́, Син Твой, єсть воі́стину Христо́с, Син Бо́га Жива́го, Судія́ живи́х і ме́ртвих, воздая́й кому́ждо по діло́м єго́. Ві́рую же па́ки і іспові́дую Тебі́ би́ти і́стинную Богоро́дицю, милосе́рдія істо́чник, утіше́ніє пла́чущих, взиска́ніє поги́бших, си́льную і непрестаю́щую к Бо́гу Хода́таїцю, зіло́ лю́б'ящую род христия́нський, і Спору́чницю покая́нія. Воі́стину бо ність челові́ком іни́я по́мощі і покро́ва, ра́зві Тебе́, Госпоже́ Преми́лостивая, і нікто́же упова́я на Тя постиді́ся когда́, і Тобо́ю умоля́я Бо́га, нікто́же оста́влен бисть. Того́ ра́ди молю́ Твою́ неісче́тную бла́гость: отве́рзи две́рі милосе́рдія Твоєго́ мні, заблу́дшему і па́дшему в тимі́ніє глубини́, не возгнуша́йся мене́ скве́рнаго, не пре́зри грі́шнаго моле́нія моєго́, не оста́ви мене́ окая́ннаго, я́ко в поги́бель зло́бний враг похи́тити м'я і́щеть, но умоли́ о мні рожде́ннаго от Тебе́ милосе́рдаго Си́на Твоєго́ і Бо́га, да прости́ть вели́кия моя́ гріхи́, і ізба́вить м'я от па́губи моєя́: я́ко да і аз со всі́ми получи́вшими проще́ніє воспою́ і просла́влю безмі́рноє милосе́рдіє Бо́жиє і Твоє́ непости́дноє о мні заступле́ніє в жи́зні сей і в несконча́ємом ві́ці. Амі́нь."]},{"h":"Молитва друга","ps":["Ко кому́ возопію́, Влади́чице, ко кому́ прибі́гну в го́ресті моє́й, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач мой і воздиха́ніє моє́ при́йметь і моле́ніям на́шим скоропослу́шливо вне́млеть, а́ще не Ти, Всеблага́я Спору́чнице, всіх на́ших ра́достей Ра́дость? Усли́ши же і ни́нішнія піснопі́нія і моле́нія, і о мні грі́шном Тебі́ приноси́мия. І бу́ди мні Ма́ти і Покрови́тельниця і ра́дости Твоєя́ всім нам Пода́тельниця. Устро́й жизнь мою́, я́коже хо́щеши і я́коже ві́си. Вруча́ю бо себі́ Твоєму́ покро́ву і промишле́нію, да ра́достно всегда́ пою́ Тебі́ со всі́ми: Ра́дуйся, Благода́тная; ра́дуйся, Обра́дованная. Ра́дуйся, Преблагослове́нная; ра́дуйся, Препросла́вленная во ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["Цари́це моя́ Преблага́я, Наде́ждо моя́ Пресвята́я, Спору́чнице грі́шних! Се, бе́дний грі́шник предстої́ть Тебі́! Не оста́ви мене́, всі́ми оста́вленнаго, не забу́ди мене́, всі́ми заби́таго, даждь мі ра́дость, неві́дущему ра́дованія. О, тя́жки мої́ бі́ди і ско́рби! О, безме́рни мої́ гріхопаде́нія! Я́ко тьма нощна́я — житіє́ моє́. І ність во сині́х челові́чеських ні єди́наго си́льнаго мі помощі́. Ти — Єди́ная моя́ Наде́жда. Ти — Єди́ний мой Покро́в, Прибі́жище і Утвержде́ніє. Дерзнове́нно простира́ю к Тебі́ немощни́я мої́ ру́ці і молю́: умилосе́рдися о мні, Всеблага́я, пощади́ іскупле́ннаго Кро́вію Си́на Твоєго́, утоли́ болі́зні многовоздиха́ющия душі́ моєя́, укроти́ я́рость ненави́дящих і оби́дящих м'я, возста́ви си́ли моя́ ув'яда́ющия, обнови́, я́ко у орля́те, ю́ность мою́, не попусти́ осла́бнути в ді́ланії за́повідей Бо́жиїх. Огне́м небе́сним косни́ся смуще́нния душі́ моєя́ і іспо́лни ю ві́ри непости́дния, любве́ нелицемі́рния і наде́жди ізві́стния. Да всегда́ пою́ і сла́влю Тебі́, Преблагослове́нную ми́ра Засту́пницю, Покро́в наш і Спору́чницю всіх нас грі́шних, і поклоня́юся Си́ну Твоєму́ і Спа́су на́шему, Го́споду Ісу́су Христу́, со Безнача́льним Єго́ Отце́м і Жизнепода́тельним Ду́хом Святи́м во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Страсна»","e":"Prayer to the Theotokos before her icon “of the Passion”","secs":[{"h":"Тропар, глас 4","ps":["Днесь возсія́ неізрече́нно ца́рствующему граду нашому Києву / іко́на Богома́тере / і, я́ко світоза́рним со́лнцем, прише́ствієм тоя́ озари́ся весь мир, / Небе́сния си́ли і ду́ші пра́ведних ми́сленно торжеству́ють, ра́дующеся, / ми же, на ню взира́юще, к Богоро́диці со слеза́ми вопіє́м: / о, Всеми́лостивая Госпоже́, Влади́чице Богоро́дице, / моли́ся із Тебе́ воплоще́нному Христу́, Бо́гу на́шему, / да пода́сть мир і здра́віє всім христия́ном // по вели́цій і неізрече́нній Своє́й ми́лості."]},{"h":"Інший тропар, глас 4","ps":["Животворя́щей Прему́дрости істо́чник чуде́с / честни́й о́браз Твой, Богоро́дице Ді́во, / моля́щеся, к нему́ любо́вію усе́рдно притека́юще, сві́тло пра́зднуєм / і із глубини́ душі́ вопіє́м Ті: / спаси́, Влади́чице, ві́рою покланя́ющихся цільбоно́сному Твоєму́ свято́му о́бразу, / тім, благодаря́ще, Тя велича́єм, я́ко Ма́тер Бо́жию, / спаси́ архієре́ї правосла́вния, / і сохрани́ зе́млю Українськую, / і вся лю́ди, і́же Тебе́ чту́щия, соблюди́, / да хвале́бния Ті да́ри, грі́шнії, прино́сим, Благода́тная: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Кондак, глас 3","ps":["Благода́ть прия́хом нетлі́нія / є́же дарова́ла єси́ нам, спаси́тельнаго Твоєго́ ціле́нія / чудотво́рним Твої́м о́бразом честни́м, Богоро́дице Ді́во, / ті́мже вопіє́м Ті і с ра́достію зове́м, Госпоже́ Цари́це, / мо́лимтися уми́льно, грі́шнії, со слеза́ми глаго́люще: / о Пресвята́я Влади́чице, / ско́роє нам яви́ заступле́ніє і по́мощ, / спаси́ ни от супоста́ть на́ших / і от вся́кия ско́рби соблюди́, / зе́млю на́шу ми́ром огради́, / і вся лю́ди Твоя́ покри́й, / і соблюди́ на Тя упова́ющия, / потщи́ся ізба́вити, / да не поги́бнем злі, раби́ Твої́, / но да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["О Пресвята́я Госпоже́, Влади́чице Богоро́дице, ви́шши єси́ всіх А́нгел і Арха́нгел і всея́ тва́рі честні́йши, Помо́щниця єси́ оби́димих, ненаді́ющихся наді́яніє, убо́гих Засту́пниця, печа́льних утіше́ніє, а́лчущих Корми́тельниця, наги́х одія́ніє, больни́х ісціле́ніє, грі́шних спасе́ніє, христия́н всіх поможе́ніє і заступле́ніє. О Всеми́лостивая Госпоже́, Ді́во Богоро́дице, Влади́чице, ми́лостію Твоє́ю спаси́ і поми́луй раб Твої́х, Вели́каго Господи́на і отця́ на́шего Святі́йшаго Патріа́рха (і́м'я рек), і преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи, і весь свяще́нничеський і і́ночеський чин, Богохрани́мую страну́ на́шу, воєнача́льники, градонача́льники і христолюби́воє во́їнство і доброхо́ти, і вся правосла́вния христия́ни ри́зою Твоє́ю честно́ю защити́, і умоли́, Госпоже́, із Тебе́ без сі́мене воплоти́вшагося Христа́ Бо́га на́шего, да препоя́шеть нас си́лою Своє́ю сви́ше на неви́димия і ви́димия враги́ на́ша. О Всеми́лостивая Госпоже́, Влади́чице Богоро́дице, воздви́гни нас із глубини́ гріхо́вния і ізба́ви нас от гла́да, губи́тельства, от тру́са і пото́па, от огня́ і меча́, от нахожде́нія іноплеме́нних і междоусо́бния бра́ні, і от напра́сния сме́рти, і от нападе́нія вра́жия, і от тлітво́рних вітр, і от смертоно́сния я́зви, і от вся́каго зла. Пода́ждь, Госпоже́, мир і здра́віє рабо́м Твої́м, всім правосла́вним христия́ном, і просвіти́ їм ум і о́чі серде́чния, є́же ко спасе́нію, і сподо́би ни, грі́шния раби́ Твоя́, Ца́рствія Си́на Твоєго́, Христа́ Бо́га на́шего, я́ко держа́ва Єго́ благослове́нна і препросла́влена, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Табинська»","e":"Prayer to the Theotokos before her icon “Tabynsk”","secs":[{"h":"Тропар, глас 4","ps":["Наста́ днесь пресві́тлий пра́здник, Пречи́стая Ді́во, / честни́я Твоєя́ Таби́нськия іко́ни, Влади́чице, / я́же па́че луче́й со́лнечних возсія́, / от Істо́чника приснотеку́щаго, Христа́ Бо́га на́шего, / істоча́єши ціле́бния да́ри / с ві́рою к Тебі́ притека́ющим, / Тя бо Христо́с Помо́щницю лю́дем Свої́м дарова́, / покрива́ти і спаса́ти от вся́кия біди́ раби́ Своя́, // єди́ну Благослове́нную."]},{"h":"Молитва перша","ps":["О Пресвята́я Влади́чице, Ді́во Богоро́дице! Прийми́ мольби́ от нас, прилі́жно призива́ющих і моля́щихся Тебі́, покажи́ ско́роє Твоє́ заступле́ніє, покажи́, я́ко мо́жеши, я́ко Ма́ти Бо́га, призива́єм Тя от се́рдця, со слеза́ми припа́дающе пред пречи́стим Твої́м о́бразом. О Бо́жия Ма́ти! Спаси́ нас і не даждь в расхище́ніє супоста́том, ніже́ да на́йдеть на ни вся зла́я, я́же гріхи́ на́ша угото́ваша нам, ніже́ беззако́нія на́ша да превзи́дуть на глави́ на́ша. Виждь на́ша нестерпи́мия печа́лі, ско́рби, ну́жди, болі́зні, стра́сті; вооружи́ся на ни лука́вно враг, язи́ком, я́коже мече́м, хотя́ нас погуби́ти, но Твоє́ю, Богороди́тельнице, крі́постію предвари́. Уста́ челові́ков, я́ко львов лю́тих, гро́ба тягча́йше отверзо́шася, го́рко поглоти́ша ни; но Ти, Богороди́тельнице яви́ся наде́жда ненаде́ющимся і низложи́ крі́пость їх, да у́зрять вразі́ і постидя́ться, да разумі́ють і ви́дять Твою́, є́же по нам сопроти́в борю́щую си́лу, і в про́пасть преіспо́днюю низложи́ їх. Да загради́ться всяк язи́к, лука́вим поуча́яйся, да молча́ть уста́ льсти́вия і уста́, непра́ведно глаго́лющия на пра́веднаго беззако́ніє, горди́нею і за́вистію вражде́бною вку́пі. Призива́ющим Тя, Богоро́дице, от душі́ нело́жно во вся́кой ско́рби, і в болі́зніх разли́чних, і в біда́х лю́тих спі́шно усли́ши, Влади́чице, сих ізбавля́ющи при́сно моли́твами Свої́ми; душ спасе́ніє, ві́ри сохране́ніє, от гріхо́вних на́виков ізбавле́ніє, ми́рную христия́нськую кончи́ну і Ца́рствія Небе́снаго наслі́діє да́руй нам. Да і́м'я Твоє́, Богоро́дице, на землі́ славосло́виться, І́же бо, із Тебе́ возсія́в, грі́шником держа́вную наде́жду і сті́ну неруши́мую Тя дарова́ во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Влади́чице Богоро́дице, Ма́ти Го́спода на́шего Ісу́са Христа́ непреста́нная о нас пред Бо́гом Моли́твеннице і Хода́тайце. О, Ма́ти на́ша Преблага́я, всіх нас при Кресті́ Си́на Твоєго́ усинови́вшая. Благодари́м Тя, безчи́сленния бла́га моли́твою Своє́ю нам іспроси́вшая. Благодари́м Тя, мно́жество іко́н Твої́х чудотво́рних страні́ на́шей дарова́вшая. Благодари́м Тя, ди́вную іко́ну Таби́нськую в годи́ну скорбе́й кра́ю Ура́льському посла́вшая, на ка́мені ве́лієм іко́ну Свою́ нам яви́вшая, мо́лим Тя: окамене́нния сердця́ на́ша росо́ю моли́тв Твої́х ум'ягчи́. Ми́лость Свою́ нам показа́вшая у істо́чника водна́го, іді́же болі́зні на́ша тіле́сния ісціля́ються, да́руй нам пото́ки ско́рбних слез і очи́сти і́ми ти́ну гріхо́в на́ших. У істо́чника водна́го свято́ю іко́ною Твоє́ю благослове́ніє мі́сту сему́ показа́вшая, помози́ нам сло́во Го́спода Си́на Твоєго́ іспо́лнити і со́лію землі́ би́ти. Лик Свой те́мним, нам, грі́шним, омраче́нним гріхо́м яви́вшая, просвіти́ тьму гріхо́в на́ших і приведи́ нас к ти́хому приста́нищу во ві́чния оби́телі, угото́ванния Го́сподом лю́б'ящим Єго́. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, і чтим о́браз Твой святи́й, і́мже болі́зні на́ша врачу́єши і ду́ші на́ша к Бо́гу возво́диши."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Тихвінська»","e":"Prayer to the Theotokos before her icon “Tikhvin”","secs":[{"h":"Тропар, глас 4","ps":["Днесь, я́ко со́лнце пресві́тлоє, / возсія́ нам на возду́сі всечестна́я іко́на Твоя́, Влади́чице, / луча́ми ми́лости мир просвіща́ющи, / ю́же вели́кая Україна, / я́ко ні́кий дар Боже́ственний сви́ше благогові́йні восприє́мши, / прославля́єть Тя, Богома́ти, всіх Влади́чицю, / і от Тебе́ ро́ждшагося Христа́ Бо́га на́шего велича́єть ра́достно. / Єму́же моли́ся, о Госпожі́ Цари́це Богоро́дице, / да сохрани́ть вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх / і спасе́ть ві́рою поклоня́ющихся Єго́ Боже́ственному / і Твоєму́ пречи́стому о́бразу, // Ді́во Неіскусобра́чная."]},{"h":"Кондак, глас 8","ps":["Притеце́м, лю́діє, к Ді́ві Богоро́дице Цари́це, / благодаря́ще Христа́ Бо́га, / і, к Тоя́ чудотво́рній іко́ні уми́льно взира́ющи, припаде́м і возопіє́м Єй: / о Влади́чице Марі́є, / присети́вше страну́ сію́ Твоєго́ честна́го о́браза явле́нієм чуде́сно, / спаса́й в ми́рі і благовре́менстві оте́чество на́ше і вся христи́яни, / наслі́дники показу́ющи Небе́сния жи́зні, / Тебі́ бо ві́рно зове́м: // ра́дуйся, Ді́во, ми́ра спасе́ніє."]},{"h":"Молитва перша","ps":["Благодари́м Тя, о Преблага́я і Пречи́стая, Преблагослове́нная Ді́во, Влади́чице, Ма́ти Христа́ Бо́га на́шего, о всіх благодія́ніїх Твої́х, я́же показа́ла єси́ ро́ду челові́чеському, найпа́че же нам, христоімени́тим лю́дем українським, о ни́хже ніже́ са́мий а́нгельський язи́ко к похвале́нію дово́лен бу́деть. Благодари́м Тя, я́коже і ни́ні удиви́ла єси́ неізрече́нную Твою́ ми́лость на нас, недосто́йних рабі́х Твої́х, преєсте́ственним самоприше́ствієм Пречи́стия Твоєя́ іко́ни, є́юже всю просвіти́ла єси́ Українськую страну́. Ті́мже і ми, грі́шнії, со стра́хом і ра́достію покланя́ющеся, вопіє́м Ті: о Пресвята́я Ді́во, Цари́це і Богоро́дице, спаси́ і поми́луй лю́ди Твоя́, і пода́ждь їм побі́ди на вся враги́ їх, і сохрани́ ца́рствующия гра́ди, і вся гра́ди і страни́ христия́нськия, і сей святи́й храм от вся́каго наві́та вра́жия ізба́ви, і всім вся на по́льзу да́руй, ни́ні прише́дшим с ві́рою і моля́щимся рабо́м Твої́м, і поклоня́ющимся Пресвято́му о́бразу Твоєму́, я́ко благослове́нна єси́ с ро́ждшимся от Тебе́ Си́ном і Бо́гом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея Всемо́щная Засту́пнице. Прийми́ хвале́бно-благода́рственноє пі́ніє сіє́ от нас недосто́йних раб Твої́х і вознеси́ моли́тви на́ша ко престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить бла́гость Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію поклоня́ющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостививши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей; усли́ши нас моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиреному́дріє, супру́гам любо́в і согла́сіє, ча́дам послуша́ніє, оби́димим терпі́ніє, оби́дящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє: всім же нам дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́: разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й, і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша к зрі́нію спасе́нія, ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на стра́шнім суді́ Си́на Твоєго́: преста́вльшияся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со А́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, сла́ва Небе́сних і упова́ніє земни́х. Ти по Бо́зі на́ша Наде́ждо і Засту́пниця всіх притека́ющих к Тебі́ с ві́рою. К Тебі́ у́бо мо́лимся, і Тебі́, я́ко Всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Досто́йно єсть велича́ти Тя, Богоро́дице, / честні́йшую Херуви́м / і сла́внійшую // без сравне́нія Серафи́м."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Толзька»","e":"Prayer to the Theotokos before her icon “Tolga”","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло сія́єть на То́лгі / о́браз Твой, Пречи́стая Ді́во Богоро́дице, / і, я́ко со́лнце незаходи́моє, / всегда́ ві́рним подаде́ся, / єго́же ви́дів на возду́сі, / неви́димо А́нгели, я́ко ники́м, держи́ма, / преосвяще́нний єпи́скоп гра́да Росто́ва Три́фон / тече́ ко явле́нному светя́щемуся столпу́ о́гненну, / і по вода́м, я́ко по су́ху, пре́йде, / і моля́щеся Ті ві́рно о па́стві і о лю́діх. / І ми, к Тебі́ притека́юще, зове́м: / Пресвята́я Ді́во Богоро́дице, / ві́рно Тя сла́в'ящих спаса́й, / страну́ на́шу, архієре́єв і вся Українськия наро́ди от всіх бід ізбавля́й // по вели́цій Твоє́й ми́лості."]},{"h":"Кондак, глас 8","ps":["Чу́дноє і богоприя́тноє світоно́снаго зра́ка Твоєго́ явле́ніє, Пречи́стая Ді́во, / с ві́рою взира́ющим бива́єть ізві́стноє ча́яніє спасе́нія, / столпо́м бо о́гненним явля́ющи предста́тельство, / неуси́пноє і те́плоє за ни к Бо́гу возсила́єши моле́ніє, / і́мже страну́ Українськую от вся́ких бід ізба́ви, мо́лимся, / да ра́достними усти́ вопіє́м Ті всі: // ра́дуйся, Предводи́тельнице ві́чнаго блаже́нства."]},{"h":"Інший кондак, глас 8","ps":["Стра́нноє і богоприя́тноє світоно́снаго зра́ка Твоєго́ явле́ніє, / Пречи́стая Ді́во, / с ві́рою взира́ющим бива́єть ізві́стноє ча́яніє спасе́нія, / столпо́м бо о́гненним явля́ющи предста́тельство, / неуси́пноє і те́плоє за ни к Бо́гу возсила́єши моле́ніє, / і́мже от вся́ких бід ізба́ви, мо́лимся, / да ра́достними усти́ вопіє́м Ті всі: / ра́дуйся, Хода́тайце ві́чнаго блаже́нства."]},{"h":"Молитва перша","ps":["О Пресвята́я Госпоже́, Ді́во Богоро́дице, ви́шшая Херуви́мов і Серафи́мов і святі́йшая всіх святи́х! Ти, Всеблага́я, на То́лгі іко́ну Твою́ многоціле́бную блаже́нному святи́телю Три́фону огневи́дно яви́ти благоволи́ла єси́, і є́ю мно́гая і неізрече́нная чудеса́ соді́лала єси́, і ни́ні содіва́єши, по Твоєму́ неізрече́нному к нам милосе́рдію. Тебі́ пред пречи́стим о́бразом Твої́м припа́даєм і мо́лимся, Преблагослове́нная ро́да на́шего Засту́пнице: в стра́нствії сем земні́м, многоско́рбнім і многом'яте́жнім, не лиши́ нас Твоєго́ заступле́нія і покро́ва держа́внаго. Спаси́ і защити́ нас, Влади́чице, от разжже́нних стріл лука́ваго врага́ спасе́нія на́шего. Укріпи́ немощну́ю во́лю на́шу к ді́ланію за́повідей Христо́вих, ум'ягчи́ окамені́лая сердця́ на́ша любо́вію к Бо́гу і бли́жнім на́шим, да́руй нам сокруше́ніє серде́чноє і покая́ніє і́стинноє, да, очи́стившеся от скве́рни гріхо́вния, возмо́жем принести́ Творцю́ благоуго́дния Єму́ плоди́ до́брих діл і сподо́битися ми́рния христия́нськия кончи́ни і отві́та пра́ваго на стра́шнім і нелицеприя́тнім Суді́ Єго́. Єй, Госпоже́ Всеми́лостивая! В час гро́зний сме́ртний найпа́че яви́ нам Твоє́ многомо́щноє заступле́ніє, ускори́ тогда́ на по́мощ к нам, безпо́мощним, і держа́вною руко́ю Твоє́ю ісхити́ нас із вла́сті лю́таго мироде́ржця, і́бо воі́стину мно́го мо́жеть моли́тва Твоя́ пред лице́м Го́спода, і нічто́же невозмо́жно хода́тайству Твоєму́, а́ще то́кмо восхо́щеши. Ті́мже, на святи́й о́браз Твой умиле́нно взира́юще і пред ним, я́ко живі́й Ті су́щей с на́ми, покланя́ющеся, с упова́нієм благи́м са́мі себе́, і друг дру́га, і весь живо́т наш Тебі́ по Бо́зі моли́твенно предає́м і Тя велича́єм с ро́ждшимся от Тебе́ Спаси́телем на́шим, Го́сподом Ісу́сом Христо́м, Єму́же, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Прийми́, о Всеблагослове́нная і Всемо́щная, Пречи́стая Госпоже́ Влади́чице, Богоро́дице Ді́во, сія́ моли́тви, со слеза́ми Тебі́ ни́ні приноси́мия от нас, недосто́йних рабо́в Твої́х, к цільбоно́сному о́бразу Твоєму́ со умиле́нієм притека́ющих, я́ко Тебі́ Само́й ту су́щей, і сли́шащей моле́нія на́ша, і подаю́щей с ві́рою прося́щим по коєму́ждо проше́нію ісполне́ніє. Скорб'я́щим бо ско́рби облегча́єши, немощни́м здра́віє да́руєши, разсла́бленних і неду́жних ісціля́єши, от бі́сних бі́си прогоня́єши, оби́димия от оби́д ізбавля́єши і ги́бнущия спаса́єши, грі́шних ка́ющихся проща́єши, прокаже́нних очища́єши, ма́лих діте́й ми́луєши, от уз і темни́ць свобожда́єши, і вся́кия многоразли́чния стра́сті врачу́єши Ти, Госпоже́ Влади́чице Богоро́дице: вся бо суть возмо́жна хода́тайством Твої́м к Си́ну Твоєму́, Христу́ Бо́гу на́шему. О Всепі́тая Ма́ти, Пресвята́я Богоро́дице Ді́во Марі́є! Не преста́й моли́тися о нас, недосто́йних рабі́х Твої́х, сла́в'ящих Тя і почита́ющих, і поклоня́ющихся пречи́стому о́бразу Твоєму́, і наде́жду іму́щих невозвра́тну і ві́ру несумне́нну к Тебі́, Присноді́ві Пресла́вній і Непоро́чній, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Розчулення» Новгородська","e":"Prayer to the Theotokos before her icon “Tenderness” of Novgorod","secs":[{"h":"Молитва","ps":["О, Влади́чице Богоро́дице, душі́ моєя́ услажде́ніє, ізсо́хшаго се́рдця моєго́ струє́ Боготе́чная, потемне́ннаго ума́ моєго́ пресві́тлий світи́льниче, ліни́вия во́лі моєя́ путеводи́тельнице, не́мощі моєя́ си́ло, наготи́ облегче́ніє, нищети́ бога́тство, неісціли́мих ран мо́щноє і ско́роє врачева́ніє, слез осуше́ніє, рида́ній утоле́ніє, бід претворе́ніє, болі́зней облегче́ніє, уз разріше́ніє, спасе́нія наде́ждо! Усли́ши моли́тву мою́: даждь мі вре́м'я покая́нія, ре́вность спасе́нія, си́лу в по́двизіх богоугожде́нія; сохрани́ м'я от напа́стей і вся́ких зол, во іскуше́ніїх же і біда́х простри́ Твою́ ру́ку по́мощі, да возста́ну в паде́нії і не поги́бну лю́ті. До́ндеже пребива́ю в сем многоболе́зненном житії́, не лиши́ мене́ даро́в Твоєя́ ми́лости. Уще́дри благости́нею Твоє́ю всю христолюби́вую бра́тію, зді предстоя́щую і моля́щуюся. Младе́нці воспита́й, ю́ния наста́ви, ста́рия поддержи́, малоду́шния уті́ши, заблу́дшия вразуми́, вдови́ці і си́рия при́зри і защити́, на всіх лю́б'ящих і ненави́дящих нас ізле́й бога́тую Твою́ ми́лость. І при кончи́ні жи́зні моєя́, во вре́м'я ісхо́да моєго́ от тілесе́, бу́ди мі предста́тельниця: болі́знь сме́ртную ум'ягчи́, тоску́ утоли́ і бі́дную мою́ ду́шу приведи́ к ві́чним оби́телем, да не во́зьметь мене́ те́мная си́ла, ніже́ да увлече́ть во глубину́ а́да. Єй, Преблага́я Влади́чице Богоро́дице, душі́ моєя́ умиле́ніє! Согрі́й хла́дноє во ві́рі і любві́ се́рдце моє́ слеза́ми умиле́нія; низпосли́ мі, скорб'я́щему і обремене́нному гріхми́, за моли́тви преподо́бного отця́ Серафи́ма твоєго́ чти́теля, потре́бную ра́дость і утіше́ніє. Да не лишу́ся у́бо, Богоневі́сто, упова́нія моєго́ лю́бленном си́не Твоє́м, Го́споді на́шем Ісу́се Христе́, сей прия́ти. Тому́ сла́ва і держа́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, Всесвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Розчулення» Псково-Печерська","e":"Prayer to the Theotokos before her icon “Tenderness” of Pskov-Caves","secs":[{"h":"Молитва","ps":["О Преблагослове́нная Ді́во Богоро́дице Влади́чице! Ма́ти всіх стра́ждущих і болі́знующих се́рдцем! Страни́ на́шея і гра́да Защи́тнице! Оби́телі Пско́во-Пече́рськия красото́ і сла́во! При́зри на нас смире́нних, обремене́нних гріхи́ мно́гими, отягче́нних скорбми́ і печа́лями, і с сокруше́нієм і слеза́ми взира́ющих на пречи́стий лик Твой, в чудотво́рній іко́ні явле́нний. Сохрани́ от вся́каго зла святу́ю оби́тель сію́, ю́же преподо́бний Корни́лій со ста́рці Ма́рком і Іо́ною Тебі́ вручи́ і всіх во ві́рі і наде́жде подвиза́ющихся в ней. Спаси́ і град сей, і вся лю́ди, правові́рно живу́щия і к Тебі́ прибега́ющия, от наше́ствія іноплеме́нних, от вся́каго стра́ха і тру́са, от мо́ра і гла́да, от злих челові́к і вся́чеськой ско́рби. Прини́кни к нам милосе́рдієм Твої́м, я́ко ли́ком Твої́м Боже́ственним любе́зно прини́кла єси́ к лани́ті Богомладе́нця. Согрі́й нас диха́нієм Твоєя́ любве́ і нікогда́ же отступа́й от нас, ні в сей жи́зні, ні в бу́дущей да ча́юще Твою́ всеси́льную Матери́нськую по́мощ, сподо́бимся безбі́дно дойти́ ві́чния жи́зні і прославля́ть Небе́снаго Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці сла́вимаго Бо́га, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Розчулення» Серафимо-Дівеєвська","e":"Prayer to the Theotokos before her icon “Tenderness” of Seraphim-Diveyevo","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці с умиле́нієм припаде́м, / всі, гріхми́ обремене́ннії, / чудотво́рную Єя́ іко́ну Умиле́нія облобиза́юще / і вопію́ще со слеза́ми: / Влади́чице, прийми́ моле́ніє недосто́йних раб Твої́х / і пода́ждь нам, прося́щим, // ве́лію Твою́ ми́лость."]},{"h":"Кондак, глас 3","ps":["Ю́же подража́я непло́дную смоко́вницю, / аз, окая́нний, умиле́нія плода́ отню́д не приношу́ і посіче́нія страшу́ся, / но, взира́я к чудотво́рній іко́ні Твоє́й Умиле́нія, Влади́чице, / стеню́ от се́рдця і вопію́: / умили́ся, Благосе́рдая, / і мні, окамене́нному се́рдцем, // благоволи́ пода́ти душе́вноє і серде́чноє умиле́ніє."]},{"h":"Молитва перша","ps":["О Пресвята́я Госпоже́ Влади́чице, Богоро́дице Ді́во! Прийми́ недосто́йния моли́тви на́ша, сохрани́ нас от наві́тов злих челові́к і от напра́сния сме́рті, пода́ждь нам пре́жде конця́ покая́ніє, на моле́нія на́ша умилосе́рдися і ра́дость в печа́лі мі́сто да́руй. І ізба́ви нас, о Госпоже́ Влади́чице Богоро́дице, от вся́кия біди́, напа́сти, ско́рби, болі́зні і вся́каго зла, і сподо́би нас, грі́шних рабо́в Твої́х, одесну́ю ста́ти во второ́м прише́ствії Си́на Твоєго́, Христа́ Бо́га на́шего, і наслі́дники нас би́ти сподо́би Ца́рствія Небе́снаго і жи́зні ві́чния со всі́ми святи́ми в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["Прийми́, всеблагомо́щная, Пречи́стая Госпоже́, Влади́чице Богороди́тельнице, сія́ честни́я да́ри, Тебі́ єди́ній прикла́дния, от нас, недосто́йних рабо́в Твої́х: от всіх родо́в ізбра́нная, всіх тва́рей небе́сних і земни́х ви́сшая я́вльшаяся, поне́же бо Тебе́ ра́ди бисть Госпо́дь Сил с на́ми, і Тобо́ю Си́на Бо́жия позна́хом і сподо́бихомся свята́го Ті́ла Єго́ і пречи́стия Кро́ве Єго́; ті́мже блаже́нна єси́ в ро́діх родо́в, Богоблаже́нная, херуви́мов світлі́йши і серафи́мов честні́йши су́щая. І ни́ні, всепі́тая Пресвята́я Богоро́дице, не преста́й моля́щися о нас, недосто́йних рабі́х Твої́х, є́же ізба́витися нам от вся́каго сові́та лука́ваго і вся́каго обстоя́нія і сохрани́тися нам неврежде́нним от вся́каго ядови́таго прило́га дия́вольськаго; но да́же до конця́ моли́твами Твої́ми неосужде́нних нас соблюди́, я́ко да Твої́м заступле́нієм і по́мощію спаса́ємі, сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся в Тро́йці Єди́ному Бо́гу і всіх Созда́телю возсила́єм, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Утоли моя печалі»","e":"Prayer to the Theotokos before her icon “Soothe My Sorrows”","secs":[{"h":"Тропар, глас 5","ps":["Утоли́ болі́зні / многовоздиха́ющия душі́ моєя́, / утоли́вшая вся́кую слезу́ от лиця́ землі́: / Ти бо челові́ком болі́зні отго́ниши / і грі́шних ско́рби разруша́єши, / Тебі́ бо всі стяжа́хом наде́жду і утвержде́ніє, // Пресвята́я Ма́ти Ді́во."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, / ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, // предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Інший кондак, глас 6","ps":["Не вві́ри м'я челові́чеському предста́тельству, / Пресвята́я Влади́чице, / но прийми́ моле́ніє раба́ Твоєго́, / скорб бо обдержи́ть м'я, / терпі́ти не могу́ де́монськаго стріля́нія, / покро́ва не і́мам, / ніже́ гді прибі́гну, окая́нний, / всегда́ побіжда́єм, / і утіше́нія не і́мам, ра́зві Тебе́, Влади́чице ми́ра, / упова́ніє і предста́тельство ві́рних, / не пре́зри моле́ніє моє́, / поле́зно сотвори́."]},{"h":"Молитва перша","ps":["Наде́ждо всіх конце́в землі́, Пречи́стая Ді́во, Госпоже́ Богоро́дице, утіше́ніє на́ше! Не гнуша́йся нас, грі́шних, на Твою́ бо ми́лость упова́єм. Угаси́ в нас пла́мень гріхо́вний і покая́нієм ороси́ ізсо́хшая сердця́ на́ша, очи́сти ум наш от гріхо́вних по́мислов; прийми́ воздиха́ніє от душі́ і се́рдця мольбу́ Ті принося́щих. Бу́ди о нас Хода́тайця к Си́ну Твоєму́ і Бо́гу, і укроти́ я́рость Єго́ пра́ведную Ма́терніми Твої́ми моли́твами. Душе́вния і тіле́сния я́зви ісціли́, Госпоже́ Богоро́дице, утоли́ болі́зні душ і тіле́с, ути́ши бу́рю злих нападе́ній вра́жеських; отими́ бре́м'я гріхо́в на́ших і не оста́ви нас до конця́ поги́бнути. Ти бо єси́ возведе́ніє челові́чеському ро́ду, в печа́лі ско́рая Помо́щниця. Ма́ти і́стинная Христа́ Бо́га на́шего, помога́й нам, грі́шним раба́м Твої́м всегда́, і ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга святого Єфрема Сиріна","ps":["Ді́ва, Влади́чиця, Богоро́диця, па́че єстества́ і сло́ва роди́вшая Єдоноро́дноє Бо́жиє Сло́во, Творця́ і Влади́ку всей ви́димой і неви́димой тва́рі, Єди́наго от Тро́йці Бо́га, Бо́га і Челові́ка, соде́лавшаяся оби́телію Божества́, вмісти́лищем вся́кой святи́ні і благода́ті, в кото́ром, по благоволе́нію Бо́га і Отця́, при соде́йствії Свята́го Ду́ха, тіле́сно обита́ла Полнота́ Божества́, несравне́нно превознесе́нная боголі́пним досто́їнством і прейму́ществующая пред вся́кою тва́рію, Сла́ва і Утіше́ніє, і неізрече́нноє весе́ліє А́нгелов, ца́рственний віне́ць апо́столов і проро́ков, преєсте́ственноє і чу́дноє му́жество му́чеников, Побо́рниця в по́двигах і Пода́тельниця побі́ди, уготовляя́ющая подви́жникам вінці́ і воздая́нія ві́чния і боголі́пния, преви́сшая вся́кой че́сти, честь і сла́ва преподо́бних, непогріши́тельная Путеуказа́тельниця і Наста́вниця безмо́лвія, двер открове́ній і духо́вних та́їн, Істо́чник Сві́та, врата́ ві́чной жи́зні, неістощи́мая ріка́ милосе́рдія, неісчерпа́ємоє мо́ре всіх боголі́пних дарова́ній і чуде́с. Тя про́сим і Тя умоля́єм, сострада́тельнійшую Ма́тер человеколюби́вого Влади́ки, будь ми́лостива к нам, смире́нним і недосто́йним раба́м Твої́м, воззри́ благосе́рдно на пліне́ніє і смире́ніє на́ше, уврачу́й сокруше́нія душ і тіл на́ших, рассе́й ви́димих і неви́димих враго́в, будь для нас, недосто́йних, пред лице́м враго́в на́ших крі́пким столпо́м, бра́нним ору́жієм, си́льним ополче́нієм, Воєво́дою і непреобори́мою Побо́рницею, покажи́ ни́ні на нас дре́внія і чу́дния ми́лості Твоя́, да позна́ють беззако́нниє враги́ на́ші, что Син Твой і Бог єди́н єсть Цар і Влади́ка, что Ти воі́стину Богоро́диця, роди́вшая по пло́ті і́стинного Бо́га, что все Тебі́ возмо́жно, і чего́ ні восхо́щеш, Влади́чице, іме́єш си́лу все сіє́ соверши́ть на Не́бі і на землі́, і на вся́коє проше́ніє дарова́ть что кому́ поле́зно: больни́м здра́віє, су́щим на мо́рі тишину́ і до́броє кораблепла́ваніє. Путеше́ствующим спутеше́ствуй і охраня́й їх, плі́нних спаса́й от го́ркого ра́бства, утіша́й печа́льних, облегча́й нищету́ і вся́коє друго́є тіле́сноє злострада́ніє: всіх свобожда́й от душе́вних неду́гов і страсте́й, неви́димими Твої́ми предста́тельствами і внуше́ніями, да́би, хорошо́ і непреткнове́нно соверши́в путь сей вре́менной жи́зні, улучи́ли ми чрез Тя і о́ниє ве́чниє блага́ в Ца́рстві Небе́сном. Ві́рних, почте́нних стра́шним і́менем Єдиноро́дного Си́на Твоєго́, упова́ющих на Твоє́ предста́тельство і на ми́лость Твою́ і во всем імі́ющих Тя своє́ю Хода́тайцею і Побо́рницею, укрепля́й неви́димо про́тив окружа́ющих враго́в, разсі́й о́блако уни́нія, облега́ющеє ду́ші їх, ізба́ви їх от душе́вного утружде́нія і пода́й їм сві́тлоє благоду́шіє і ра́дость, возстанови́в мир і безм'яте́жіє в сердця́х їх. Спаси́ моли́твами Твої́ми, Влади́чице, сію́ Тебі́ преймущественно посвяще́нную па́ству, весь го́род і страну́, от го́лода, землетрясе́нія, потопле́нія, огня́, меча́, наше́ствія іноплеме́нников, междоусо́бной бра́ні, і вся́кий пра́ведно подви́гшийся на нас гнів обрати́, по благоволе́нію і благода́ті Єдиноро́дного Си́на і Бо́га Твоєго́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, с сове́чним і животворя́щим Єго́ Ду́хом, ни́ні і всегда́, і во ві́ки віко́в! Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Феодорівська»","e":"Prayer to the Theotokos before her icon “Feodorovskaya”","secs":[{"h":"Тропар, глас 4","ps":["Прише́ствієм честни́я Твоєя́ іко́ни, Богоотрокови́це, / обра́дованний днесь Богохрани́мий град Кострома́, / я́коже дре́вній Ізра́їль ко киво́ту Заві́та, / притека́єть ко ізображе́нію лиця́ Твоєго́ / і воплоти́вшагося от Тебе́ Бо́га на́шего, / да Твої́м Ма́тернім к Нему́ предста́тельством / при́сно хода́тайствуєши всім, / под сінь кро́ва Твоєго́ прибега́ющим, // мир і ве́лію ми́лость."]},{"h":"Інший тропар, глас 4","ps":["Днесь сві́тло красу́ється преймени́тий град Кострома́ / і вся Українськая страна́, / созива́ющи к весе́лію вся боголюби́вия наро́ди христия́нськия, / на пресла́вноє торжество́ Бо́жия Ма́тере, / прише́ствія ра́ди чудотво́рнаго Єя́ і многоціле́бнаго о́браза, / днесь бо яви́ся нам пресві́тлоє вели́коє со́лнце, / прийді́те, всі Богоізбра́ннії лю́діє, но́вий Ізра́їль, / ко істо́чнику цільбоно́сному, / істоча́єть бо нам неоску́дния ми́лості Пресвята́я Богоро́диця / і ізбавля́єть вся гра́ди і страни́ христия́нськия / невреди́ми от всіх наві́т вра́жиїх. / Но, о Всеми́лостивая Госпоже́, Ді́во Богоро́дице, Влади́чице, / спаси́ страну́ на́шу, і архієре́ї, і вся лю́ди Твоєго́ достоя́нія от всіх бід / по вели́цій Твоє́й ми́лості, да зове́м Ті: // ра́дуйся, Ді́во, христия́ном похвало́."]},{"h":"Кондак, глас 8","ps":["Благода́рственная принося́ще Ті, раби́ Твої́, Богороди́тельнице, о всіх, / і́миже благоді́яла єси́ гра́ду на́шему, / із глубини́ душі́ взива́єм к Тебі́ і ми́лі ся ді́єм: / не преста́ни, Влади́чице, / Ма́терніми к Си́ну Твоєму́ і Бо́гу на́шему моли́твами / подава́ти вся блага́я і спаси́тельная всім, / ві́рою і любо́вію вопію́щим Ті: // ра́дуйся, Ді́во, христия́н похвало́."]},{"h":"Інший кондак, глас 8","ps":["Притеце́м, лю́діє, всі к ти́хому і до́брому приста́нищу, / в дом Бо́жия Ма́тере, / чу́дному о́бразу Цари́ці і Богоро́диці, / за неізрече́нную ми́лость Єя́ явле́нному, / ві́рно припа́дающе і вопію́ще: / о Всеми́лостивая Влади́чице, / за спаси́тельноє Твоє́ смотре́ніє, / чу́днаго о́браза к нам прише́ствіє, / посіти́ нас, грі́шних, сві́тло сотворя́ющих пра́зднество Твоє́, / укріпи́ страну́ на́шу, / ди́вно на враги́ побі́ду подаю́щи, і ві́ру утверди́. / Це́рков Си́на Твоєго́ непоколеби́му соблюди́, / притека́ющих к Тебі́ спаси́, от вся́ких напа́стей ізба́ви, / сохраня́ющи в ми́рі все Правосла́віє, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва перша","ps":["О Премилосе́рдая Госпоже́, Цари́це Богоро́дице, прийми́ смире́нноє моле́ніє на́ше, і не отри́ни нас, заступле́ніє і прибі́жище на́ше, і не возгнуша́йся нас, недосто́йних, но я́ко Милосе́рдая, не преста́ни моля́щи, Єго́же родила́ єси́, да да́руєть нам проще́ніє мно́гих согріше́ній на́ших, да спасе́ть нас і́миже вість судьба́ми. Поми́луй нас, Влади́чице, поми́луй нас, ність бо нам спасе́нія от діл. Ті́мже ві́рно вопіє́м Ті: поми́луй раби́ Твоя́, і непло́дноє се́рдце на́ше покажи́ плодоно́сно благи́х діл. При́зри на нас недосто́йних, Ти бо упова́ніє і покро́в наш, жизнь і світ се́рдцю на́шему. Я́ко Невече́рній Світ от чре́ва Твоєго́ воздви́гшая, озари́ ду́шу на́шу, Чи́стая, і отжени́ вся́ку мглу се́рдця на́шего. Да́руй нам умиле́ніє, покая́ніє і сокруше́ніє серде́чноє. Сподо́би нас по вся дні живота́ на́шего твори́ти во́лю Си́на Твоєго́ і Бо́га на́шего і во всем благоугожда́ти Єму́ Єди́ному. О Богома́ти, не преста́ни моля́щи Ро́ждшагося от Тебе́ за вся притека́ющия с ві́рою к сему́ чудотво́рному о́бразу Твоєму́ і подава́й їм ско́рую по́мощ і утіше́ніє в ско́рбіх, і напа́стіх, і злострада́ніїх, ізба́ви їх от клевети́ і зло́би челові́чеськія, от враг ви́димих і неви́димих, і вся́кия ну́жди і печа́лі. Спаси́ оте́чество на́ше, град сей і вся гра́ди і страни́ от вся́ких бід і нужд, і сотвори́ ми́лостива нам би́ти Бо́га на́шего, отврати́ вся́кий гнів Єго́ на ни дви́жимий і ізба́ви ни от належа́щаго і пра́веднаго Єго́ преще́нія. О Боголюби́вая Влади́чице, А́нгелов украше́ніє, му́чеников сла́во і всіх святи́х ра́досте, с ни́ми моли́ Го́спода, да сподо́бит нас в покая́нії сконча́ти живота́ на́шего тече́ніє. Во сме́рті же час, Пресвята́я Ді́во, ізба́ви нас от вла́сті бісо́вськия і осужде́нія, і отві́та, і стра́шнаго іспита́нія, і мита́рств го́рких, і огня́ ві́чнаго, да, сподо́бльшеся сла́внаго Ца́рствія Бо́жия, велича́єм Тя і сла́вим вопло́щшагося от Тебе́ Христа́ Бо́га на́шего, Єму́же сла́ва со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, Пресвята́я Влади́чице Богоро́дице і Присноді́во, Марі́є, єди́ная наде́ждо нам грі́шним! К Тебі́ прибіга́єм і Тебі́ мо́лим, я́ко ве́ліє і́маши дерзнове́ніє пред ро́ждшимся от Тебе́ по пло́ті Го́сподем Бо́гом і Спаси́телем на́шим Ісу́сом Христо́м. Не пре́зри слез на́ших, не возгнуша́йся воздиха́ній на́ших, не отри́ни ско́рби на́шея, не посрами́ упова́нія на́шего на Тя, но Ма́терніми моле́нії Твої́ми умоли́ Го́спода Бо́га, да сподо́бит нас грі́шних і недосто́йних свободи́тися от гріхо́в і страсте́й душе́вних і тіле́сних, умре́ти ми́ру і жи́ти Єму́ єди́ному по вся дні живота́ на́шего. О Пресвята́я Влади́чице Богоро́дице, путеше́ствующим спутеше́ствуй і огражда́й і охраня́й о́ния, ізба́ви пліне́нних от пліне́нія, свободи́ стра́ждущих от бід, уті́ши су́щих в печа́лі, ско́рбіх і напа́стіх, облегчи́ нищету́ і вся́ко злострада́ніє тіле́сноє, і да́руй всім вся потре́бная к животу́, благоче́стію і жи́зні вре́менній. Спаси́, Влади́чице, вся стра́ни і гра́ди і сію́ страну́ і сей град, і́мже сія́ чудотво́рная і свята́я іко́на Твоя́ даде́ся во утіше́ніє і огражде́ніє, ізба́ви я от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних, междоусо́бния бра́ні, і отврати́ вся́кий гнів на ни пра́ведно дви́жимий. Да́руй нам вре́м'я на покая́ніє і обраще́ніє, ізба́ви нас от внеза́пния сме́рти, і во вре́м'я ісхо́да на́шего предста́ни нам я́вльшися, Ді́во Богоро́дице, і ізба́ви нас от возду́шних мита́рств, князе́й ві́ка сего́, сподо́би на Стра́шнім Суди́щі Христо́вім ста́ти одесну́ю, і соді́лай нас наслі́дники ві́чних благ, да сла́вим вове́ки великолі́поє і́м'я Си́на Твоєго́ і Бо́га на́шего со Безнача́льним Єго́ Отце́м і Святи́м і Бла́гим і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["Ко кому́ воззову́, Влади́чице; ко кому́ прибі́гну в печа́лі моє́й; ко кому́ привнесу́ сле́зи і воздиха́нія моя́, а́ще не к Тебі́, Цари́це Небесе́ і землі́. Кто істо́ргнеть м'я із ти́ни гріхо́в і беззако́ній, а́ще не Ти, о Ма́ти Живота́, Засту́пнице і Прибі́жище ро́да челові́чеськаго. Усли́ши стена́ніє моє́, уті́ши м'я і поми́луй в го́ресті моє́й, защити́ в біда́х і напа́стіх, ізба́ви от озлобле́ній і скорбе́й і вся́ких неду́гов і болі́зней, от враг ви́димих і неви́димих, умири́ вражду́ стужа́ющих мні, да ізба́влен бу́ду от клевети́ і зло́би челові́чеськія; та́кождь от своєя́ мі пло́ті гну́сних оби́чаєв свободи́ м'я. Укри́й м'я под сі́нію ми́лості Твоя́, да обря́щу поко́й і ра́дость і от гріхо́в очище́ніє. Твоєму́ Ма́тернему заступле́нію себі́ вруча́ю: бу́ди мні Ма́ти і Наде́жда, Покро́в і По́мощ і Заступле́ніє, ра́дость і утіше́ніє і ско́рая во всем Помо́щниця. О, чу́дная Влади́чице! Всяк притека́яй к Тебі́, без Твоєя́ всеси́льния по́мощі не отхо́дить: сего́ ра́ди і аз недосто́йний к Тебі́ прибіга́ю, да ізба́влен бу́ду от внеза́пния і лю́тия сме́рті, скре́жета зубна́го і ві́чнаго муче́нія. Небе́сноє же Ца́рствіє получи́ти сподо́блюся і Тебі́ во умиле́нії се́рдця реку́: ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Царгородська»","e":"Prayer to the Theotokos before her icon “of Constantinople”","secs":[{"h":"Тропар, глас 1","ps":["Возсія́ нам, я́ко со́лнце світоза́рноє от восто́ка во велелі́пії. / Твоя́, Влади́чице, іко́на, / озаря́ющи чуде́с сія́нієм пресла́вно всіх, приходя́щих к ней с ві́рою і любо́вію / і моля́щихся усе́рдно к Твоєму́, є́же о Си́ні Твоє́м і Бо́зі, вели́чію. / Сла́ва Бо́гу, Євфоси́ном сію́ да́вшему нам! / Сла́ва Приве́дшему ю от Царгра́да! // Сла́ва Даю́щему то́ю всім ісціле́нія."]},{"h":"Кондак, глас 8","ps":["Препросла́вленная Ви́шняго Ма́тер / созива́єть к піснопі́нію нас Своєго́ о́браза прише́ствієм от Царгра́да / і возбужда́єть зрі́нієм того́ на по́двиг, / побіжда́ти сопроти́вних си́лу, / і к Ней, я́ко на́шея ра́дости вино́вній, пі́ти: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["К Тебі́, Пресвяті́й Госпоже́ Богоро́дице, недосто́йнії раби́ Твої́ прибіга́єм: Ти бо, Преблага́я, єди́на незло́бивая і велемо́щная к Си́ну Твоєму́, Христу́ Бо́гу на́шему, за ни, грі́шния, Хода́тайця і Непости́дная Предста́тельниця. Ві́си, я́ко зіло́ преогорчи́хом бла́гость Єго́ преступле́нієм Боже́ственних Єго́ за́повідей. Ність бо гріха́, єго́же ми, непотре́бнії, не сотвори́хом, всяк страх отве́ргши, того́ ра́ди і Ду́ха благода́ті і да́ра преєсте́ственнаго синоположе́нія отверго́хомся і вся́каго отвраще́нія і ка́зні досто́йні сотвори́хомся. Ві́си, Преблага́я Засту́пнице, я́ко і Твоя́ ми́лості і дарова́нія ми, безу́мнії, забве́нію преда́хом і Твоєго́ милосе́рдія недосто́йни соді́яхомся. Коли́ко бо Тя, Госпоже́ Богороди́тельнице, на умоле́ніє Си́на Твоєго́ і Бо́га на́шего подвиза́хом, обіща́вше Ті, Пречи́стая, от злих ісправле́ніє, толи́ко Твоє́ ма́тернеє к Нему́ за ни, грі́шния, предста́тельство і заступле́ніє нівочто́же вміни́хом, неблагода́рни і злонра́вни су́ще. Ни́ні стид нося́ще і ніже́ досто́йні воззрі́ти на пречи́стий о́браз Твой, пред ни́мже предста́хом. Но, о сві́ті душ на́ших, сві́тлоє зерца́ло бла́гости Бо́жия! І ми ві́ми, коли́ко мо́жеть Твоє́ ма́тернеє ко Христу́ Бо́гу на́шему дерзнове́ніє, ві́ми, я́ко нікто́же, прибіга́яй к Тебі́, Благосе́рдая, с покая́нієм і умиле́нієм, посра́млен от Тебе́ бисть, іли́ призива́яй Тебі́, Пречи́стая, не усли́шан от Тебе́ ізи́де: чтить бо Син Твой Тя, Богоневі́сто, я́ко Ма́тер Свою́, ми́лостивно приє́мля моле́нія Твоя́. Сего́ ра́ди і ужаса́ємся воззрі́ти к Сві́ту Твоєя́ стра́шния і Богоподо́бния сла́ви, оскверне́ни іму́ще о́чі душе́вния, оба́че колі́на душ і тіле́с на́ших преклоня́юще, мо́лим Тя, Боголі́пная Марі́є, я́ко Ма́тер і Цари́цю на́шу: умилосе́рдися на ни, непотре́бния раби́ Твоя́, і, ї́миже ві́си судьба́ми, взищи́ ни, поги́бшія, просвіти́ наш ум сві́том Твоєго́ Богові́дінія, да, їм озаре́ни су́ще, вся́коє зло́є помишле́ніє і всяк безсту́дних дія́ній о́браз до конця́ отсіче́м, всім же се́рдцем за́повіді Госпо́дні возлю́бим і в них непоро́чно ходи́ти начне́м. Єрети́чеськая возста́нія прекрати́, разсі́янния же собери́, заблу́ждшия возврати́ во єди́но ста́до Си́на Твоєго́, Христа́ Бо́га на́шего, ста́рость поддержи́, ю́ния вразуми́, вдови́ць і сиро́т защити́, боля́щия ісціли́, страну́ же на́шу ми́ром огради́ і во ві́ки нези́блему соблюди́, всім же нам преспі́яніє во ві́рі і ді́ліх благи́х в долготу́ дній да́руй. Пре́жде отше́дшия отці́ і бра́тію на́шу во сві́тлостіх ра́йських і селе́ніїх пра́ведних упоко́й, с ни́ми і нас всіх в покая́нії і іспові́данії прийми́ і сопричти́, да і ми, Преблага́я на́ша Засту́пнице, Богома́ти і Влади́чице, спасе́ни су́ще Твої́м хода́тайством, восхваля́я Тя, просла́вим со всі́ми святи́ми пречестно́є і пресвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха, Єди́наго в Тро́йці сла́вимаго Бо́га, ни́ні, і при́сно, і во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Чернігівська Гетсиманська»","e":"Prayer to the Theotokos before her icon “Chernihiv Gethsemane”","secs":[{"h":"Тропар, глас 5","ps":["Пречи́стая Влади́чице Богоро́дице, / упова́ніє всіх христия́н, / поне́же іна́го упова́нія не і́мами, ра́зві Тебе́, / Всенепоро́чная Влади́чице моя́, Госпоже́ Богоро́дице, / Ма́ти Христа́ Бо́га моєго́, / ті́мже поми́луй, і ізба́ви м'я от всіх зол мої́х, / і умоли́ ми́лостиваго Си́на Твоєго́ і Бо́га моєго́, / да поми́луєть окая́нную ду́шу мою́ / і да ізба́вить м'я от ві́чния му́ки // і сподо́бит м'я Ца́рствія Своєго́."]},{"h":"Молитва","ps":["О Пресвята́я Ді́во, Ма́ти Христа́ Бо́га на́шего, Цари́це Небесі́ і землі́! Воньми́ многоболі́зненному воздиха́нію душ на́ших, при́зри с висоти́ святи́я Твоєя́ на нас, с ві́рою і любо́вію покланя́ющихся пречи́стому о́бразу Твоєму́: се бо, гріхми́ погружа́ємі і скорбми́ обурева́ємі, взира́юще на Твой о́браз, я́ко живу́щей Ті с на́ми, прино́сим смире́нная моле́нія на́ша, не і́мами бо іни́я по́мощі, ні іна́го предста́тельства і утіше́нія, то́кмо Тебі́, о Ма́ти всіх скорб'я́щих і обремене́нних. Помози́ нам, немощни́м, утоли́ скорб на́шу, наста́ви на путь пра́вий нас, заблу́дших, уврачу́й болі́зненная сердця́ на́ша і спаси́ безнаде́жния. Да́руй нам про́чеє вре́м'я живота́ на́шего в ми́рі і покая́нії проводи́ти, пода́ждь христия́нськую кончи́ну і на Стра́шнім Суді́ Си́на Твоєго́ яви́ся нам милосе́рдая Предста́тельниця, да всегда́ поє́м, велича́єм і сла́вим Тя, я́ко Благу́ю Засту́пницю ро́да христия́нськаго, со всі́ми угоди́вшими Бо́гу. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Геронтісса» (Стариця)","e":"Prayer to the Theotokos before her icon “Gerontissa” (the Elder)","secs":[{"h":"Тропар, глас 4","ps":["Я́ко пресві́тлая звізда́, просія́ Боже́ственними чудеси́ святи́й о́браз Твой, Ізба́вительнице, луча́ми благода́ті і милосе́рдія Твоєго́ озари́во в нощі́ скорбе́й су́щих. Пода́ждь у́бо і нам, Всеблага́я Ді́во, ізбавле́ніє от бід, ісціле́ніє неду́гов душе́вних і тіле́сних, спасе́ніє і ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Ко іко́ні Твоє́й, Пресвята́я Госпоже́, бедствовавши с ві́рою прите́кшеє, заступле́нієм Твої́м ізба́вишася от злих, но я́ко Ма́тер Христа́ Бо́га і нас свободи́ от лю́тих обстоя́ній, вре́менних і ві́чних, да зове́м Ті: ра́дуйся Ізба́вительнице на́ша от всіх бід."]},{"h":"Молитва","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице! Ви́шши єси́ всіх а́нгел і арха́нгел, і всея́ тва́рі честні́йши: помо́щниця єси́ оби́димих, ненаді́ющихся наді́яніє, убо́гих засту́пниця, печа́льних утіше́ніє, а́лчущих корми́тельнице, наги́х одія́ніє, больни́х ісціле́ніє, грі́шних спасе́ніє, христия́н всіх поможе́ніє і заступле́ніє. О Всеми́лостивая Госпоже́, Ді́во Богоро́дице Влади́чице! Ми́лостію Твоє́ю спаси́ і поми́луй Святі́йшия Патріа́рхи правосла́вния, Преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи і весь свяще́нничеський і і́ночеський чин, і вся правосла́вния христия́ни ри́зою Твоє́ю честно́ю защити́: і умоли́, Госпоже́, із Тебе́ без Сі́мене воплоти́вшагося Христа́ Бо́га на́шего, да препоя́шеть нас си́лою Своє́ю сви́ше на неви́димия і ви́димия враги́ на́ша. О Всеми́лостивая Госпоже́ Влади́чице Богоро́дице! Воздви́гни нас із глубини́ гріхо́вния, і ізба́ви нас от гла́да, губи́тельства, от тру́са і пото́па, от огня́ і меча́, от нахожде́нія іноплеме́нних і междоусо́бния бра́ні, і от внеза́пния сме́рти, і от нападе́нія вра́жия, і от тлітво́рних вітр, і от смертоно́сния я́зви, і от вся́каго зла. Пода́ждь, Госпоже́, мир і здра́віє рабо́м Твої́м, всім правосла́вним христия́ном, і просвіти́ їм ум і о́чі серде́чния, є́же ко спасе́нію: і сподо́би ни, грі́шния раби́ Твоя́, Ца́рствія Си́на Твоєго́, Христа́ Бо́га на́шего: я́ко держа́ва Єго́ благослове́нна і препросла́влена, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Піщанська»","e":"Prayer to the Theotokos before her icon “Peschansk”","secs":[{"h":"Тропар, глас 4","ps":["О, Пречу́дная, Преблагослове́нная / Ма́ти Христа́ Бо́га на́шего, / сві́том небе́сним от іко́ни Твоєя́ / лю́ди страни́ Українськия при́сно озаря́ющая, / Ти бо єси́ преізоби́льная ріка́ Благода́ті Боже́ственния. / Сего́ ра́ди к Си́ну Твоєму́ моли́твами от вся́ких нас бід защити́, / покро́вом ми́лости Твоєя́ огради́ // і в Го́рній Ієрусали́м, Ца́рствіє Небе́сноє, возведи́."]},{"h":"Інший тропар, глас 4","ps":["Вірні люди з відвагою приступімо до Чудотворного Образу Богоматері Піщанської. Бо Вона дарує місту цьому й країні нашій велику милість і спасіння душам нашим."]},{"h":"Кондак, глас 8","ps":["Взбра́нной Воєво́ді і Покрови́тельнице страни́ Українськия, / мно́гіє чудеса́ от іко́ни Твоєя́ преди́вния приє́мше, / похва́льная воспіва́єм Ті, Цари́це Богоро́дице; / Ти же я́ко іму́щая благода́ть от вся́ких нас бід свобожда́ти, / спаси́ душі́ на́ша, да зове́м Ті: // ра́дуйся, Влади́чице ми́ра, іко́ною Твоє́ю Песчанською се́рдця на́ша утіша́ющая."]},{"h":"Молитва перша","ps":["О, Преми́лостивая і Премилосе́рдная Ма́ти Бо́жия, Покрови́тельнице гра́да на́шего Ізюма і страни́ на́шея, ку́пно же і всего́ ми́ра Моли́твеннице, прийми́ колінопреклоне́ніє ума́ і се́рдця на́шего, і усли́ши моли́тви в умиле́нії душ на́ших Тебі́ возсилаємия: я́коже іздре́вле приймала єси́ моли́тви лю́б'ящих душ зді, пред іко́ною Твоє́ю возноси́мия. Помози́ нам в побіжде́нії пре́лестей і собла́знов ми́ра сего́, не попусти́ нам отве́рженним би́ти ві́чнаго небе́снаго блаже́нства. Ти єди́на на́ша ра́дость і утіше́ніє в жи́зні сей вре́менній; Ти єди́на на́ша наде́жда в жи́зні ві́чній. Ві́руєм, я́ко Ти Своє́ю Богоматернею любо́вію і снисхожденієм удостоїши нас с Собо́ю вожделі́ннаго ца́рствія Си́на Твоєго́. Тебі́ у́бо про́сим: не отступа́й от нас, Всеблага́я, защища́й от всіх ко́зней вра́жиїх, не попусти́ нас чрез гріхи́ на́ша лиши́тися милосе́рдія Бо́жия; ізжени́ із нас ленность в моли́тві і посіще́нія хра́ма Бо́жия; ізба́ви нас от малоду́шія, уни́нія, вражди́, гні́ва, подозрі́нія, за́висти, клевети́, не́нависті і го́рдості бісо́вськия. Вразуми́ попра́вших за́повіді Це́ркві Христо́вой. Семям на́шим да́руй мир і любо́в, да согла́сно поживу́ть роди́телі і ді́ти. Да бу́деть в страні́ на́шей пра́вда Бо́жия, да сохраня́ться в наро́ді на́шем благочести́вії оби́чаї. Вознеси́, о Всеблага́я, усе́рдния моли́тви пред Бо́гом о всего́ ми́ра умире́нії, да не поги́бнеть род людськи́й в пла́мені опустошенія всеми́рнаго; да позна́ють всі наро́ди Отця́ Своєго́ Небе́снаго і Тя, Ма́тер Бо́жию, засту́пницю ро́да христия́нськаго. Приведи́ всі наро́ди к і́стинному покая́нію і жи́зні гріхо́вния ісправле́нію, да не бу́деть нам стра́шен день Стра́шнаго суда́ Бо́жия, но сподо́бит нас Госпо́дь с Тобо́ю ві́чния ра́дости небе́сния, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["До кого волатиму, Владичице, до кого вдамся в гіркоті моїй, якщо не до Тебе, Царице Небесна? Хто плач мій почує і зідхання прийме, якщо не Ти, Пренепорочна, Надіє християн і Прибіжище наше, грішних? Хто краще за Тебе в нещастях захистить? Почуй стогін мій і прихили вухо Твоє до мене, Владичице й Мати Бога мого! Не знехтуй того, хто чекає Твоєї допомоги, і не відкинь мене, грішного, Царице Небесна. Навчи мене виконувати волю Сина Твого й дай мені бажання завжди слідувати Його святим заповідям. За мій ремствування в хворобах, трудах і нещастях не відступи від мене, але будь Матір’ю й Покровителькою мені, малодушному, Царице моя Преблагая, Заступнице ревна. Твоїм заступництвом прикрий мої прогрішення, від видимих і невидимих ворогів захисти, серця тих, що воюють проти мене, пом’якши й зігрій їх любов’ю Христовою. Мені ж, немічному, дай Твою всесильну допомогу подолати мої гріховні звички, щоб, очищений покаянням і подальшим доброчесним життям, у спілкуванні зі Святою Церквою провести решту днів земного мандрування. Стань при мені, Надіє всіх християн, у годину кончини моєї й підкріпи мою віру в тяжку смертну годину. Піднеси за мене, що багато згрішив у цьому житті, Твої всесильні молитви по відході моєму, щоб виправдав мене Господь і вчинив учасником Своїх безконечних радощів. Амінь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Цілителька»","e":"Prayer to the Theotokos before her icon “The Healer”","secs":[{"h":"Тропар, глас 1","ps":["Любо́вію, Чи́стая Ді́во,Твою́ святу́ю іко́ну почита́ющим, / і Бо́жию Тя і́стинную Ма́тер прославля́ющим, / і ві́рно поклоня́ющим Ті ся / Ціли́тельниця яви́ся, / вся́коє зло і болі́зні от сих удаля́ющая, // я́ко Всемогу́щая."]},{"h":"Молитва перша","ps":["О Пресвята́я Госпоже́ Цари́це Богоро́дице, ви́сшая всіх небе́сних сил і святі́йшая всіх святи́х! Припа́даєм і поклоня́ємся Тебі́ пред всечестни́м і цільбоно́сним о́бразом Твої́м, воспомина́юще ди́вноє явле́ніє Твоє́ боля́щему клирику Викентію, і усе́рдно мо́лим Тя, всеси́льную ро́да на́шего засту́пницю і помо́щницю: я́коже дре́вле подала́ ісціле́ніє тому́ клирику, та́ко і ни́ні ісціли́ на́ша душі́ і тілеса́, болезнующия ра́нами гріхо́в і страсте́й многоразли́чних, ізба́ви нас от вся́ких напа́стей, бід, скорбе́й і ві́чнаго осужде́нія, сохрани́ от душепа́губних уче́ній і безверія, от льсти́вих і наглих нападе́ній неви́димих враго́в, пода́ждь нам христия́нськую кончи́ну, безболі́зненну, ми́рну, непости́дну, Святи́х Та́їн прича́стну і сподо́би нас на нелицеприя́тнім суди́щі Христо́ві ста́ти одесну́ю Всеправеднаго Судії́ і блаже́нний глас Єго́ усли́шати: «Прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра». Амі́нь."]},{"h":"Молитва друга","ps":["Прийми́, о, Всеблагослове́нная і Всемо́щная Госпоже́ Влади́чице Богоро́дице Ді́во, сія́ моли́тви, со слеза́ми Тебі́ ни́ні приноси́мия от нас, недосто́йних раб Твої́х, ко Твоєму́ цільбоно́сному о́бразу пі́ніє возсила́ющих со умиле́нієм, я́ко Тебі́ Само́й зді су́щей і вне́млющей моле́нію на́шему. По коєму́ждо бо проше́нію ісполне́ніє твори́ши, ско́рби облегча́єши, немощни́м здра́віє да́руєши, разсла́бленния і неду́жния ісціля́єши, от бісни́х бі́си прогоня́єши, оби́димия от оби́д ізбавлявши, прокаже́нния очища́єши і ма́лия ді́ти ми́луєши; єще́ же, Госпоже́ Влади́чице Богоро́дице, і от уз і темни́ць свобожда́єши і вся́кия многоразли́чния стра́сті врачу́єши: вся бо суть возмо́жна хода́тайством Твої́м к Си́ну Твоєму́, Христу́ Бо́гу на́шему. О, Всепі́тая Ма́ти, Пресвята́я Богоро́дице! Не преста́й моли́тися о нас недосто́йних раба́х Твої́х, сла́в'ящих Тя і почита́ющих Тя, і поклоняющихся со умиле́нієм Пречи́стому о́бразу Твоєму́, і наде́жду іму́щих невозвра́тну і ві́ру несумне́нну к Тебі́, Присноді́ві Пресла́вній і Непоро́чній, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Економісса» (Домобудівниця)","e":"Prayer to the Theotokos before her icon “Oikonomissa” (Housekeeper)","secs":[{"h":"Тропар, глас 4","ps":["Предста́тельство стра́шноє і непости́дноє, / не пре́зри, Блага́я, моли́тв на́ших, / Всепі́тая Богоро́дице, Ми́лостивая ві́рних Домострої́тельнице, / утверди́ правосла́вних жи́тельство, / спаси́ страну́ на́шу / і всіх правосла́вно живу́щих в ней защити́, зане́ родила́ єси́ Бо́га, Єди́на Благослове́нная."]},{"h":"Молитва","ps":["О Пречиста Владичице Богородице, Всечеснійша наша Мати, Ігуменіє всіх православних святих обителей чернечого життя, що на Святій Горі Афонській і по всій вселенній! Прийми смиренні моління наші й принеси їх до всещедрого Бога нашого, щоб спас душі наші Своєю благодаттю. Поглянь на нас милосердним Твоїм оком і звершуй Сама в Господі наше спасіння, бо без милості Спаса нашого й Твого святого заступництва за нас не зможемо ми, окаянні, звершити свого спасіння, адже ми занечистили життя наше марнотами світськими, бо час жнив Христових наблизився і день Страшного Суду настав. Ми ж, окаянні, гинемо в безодні гріховній через нерадіння наше, за словами святих отців, першопочинателів ангельського в плоті життя, що останні ченці через нерадіння життя свого уподібняться світським людям, що й збулося нині, бо наше останнє чернецтво плаває життям своїм у морі життєвому, серед великої бурі й негоди, бо наші святі обителі в запустінні пробувають, гріхів бо наших ради всеправедний Суддя Господь наш Ісус Христос так благоволив, а ми, недостойні, не маємо, де голову прихилити.","О сладча́йшая на́ша Ма́ти Ігу́меніє! Собери́ ни, разсеянноє ста́до Христо́во, воєди́но і спаси́ правосла́вноє монашество послі́дняго ві́ка сего́, і всіх правосла́вних христия́н сподо́би ра́йськия жи́зні со а́нгели і всі́ми святи́ми во Ца́рствії Христа́ Бо́га на́шего, Єму́же честь і сла́ва, со Безнача́льним Єго́ Отце́м і со Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Примножувальниця хлібів»","e":"Prayer to the Theotokos before her icon “Multiplier of Bread”","secs":[{"h":"Тропар, глас 3","ps":["Пречи́стая Ді́во Марі́є, / Ма́ти Царя́ небесі́ і землі́, / благоутро́бно призи́раєши / на лю́б'ящих Си́на Твоєго́, Христа́ Бо́га на́шего, / і тружда́ющихся во І́м'я Єго́ ві́чнаго ра́ди спасе́нія, / і подає́ши їм вся оби́льно к наслажде́нію. / Спори́тельнице су́щи хлібо́в їм, / ізбавля́я їх вся́кия ну́жди і утісне́нія / і устроя́я їм, рабо́м Твої́м су́щим, // ізбавле́ніє ві́чния му́ки і жизнь ві́чную."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, / предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во Богоро́дице, Преми́лостивая Влади́чице, Цари́це Небесе́ і землі́, вся́каго до́ма і семе́йства христия́нськаго Благоустрої́тельнице, тружда́ющихся благослове́ніє, нужда́ющихся неістощи́моє бога́тство, си́рих і вдови́ць і всіх люде́й Корми́тельнице! Пита́тельнице на́ша, ро́ждшая Пита́теля Вселе́нния і Спорительнице хлі́бов на́ших, Ти, Влади́чице, ниспосилаєши Твоє́ Ма́тернеє благослове́ніє градо́м на́шим, се́лам і ни́вам і коєму́ждо до́му, на Тя упова́ніє іму́щему. Ті́мже с благогові́йним тре́петом і сокруше́нним се́рдцем смире́нно мо́лим Тя: бу́ди і нам, грі́шним і недосто́йним рабо́м Твої́м, му́драя Домострої́тельнице, житіє́ на́ше до́брі устроя́ющая. Вся́коє же соо́бщество, вся́кий дом і семе́йство во благоче́стії і правосла́вії, єдиноми́слії, послуша́нії і дово́льстві соблюди́. Нищія і неімущия пропитай, ста́рость поддержи́, младе́нці воспита́й, всіх вразуми́ преі́скренні взива́ти ко Го́споду: «Хліб наш насу́щний даждь нам днесь». Сохрани́, Пречи́стая Ма́ти, лю́ди Твоя́ от вся́кия ну́жди, болі́зні, гла́да, губи́тельства, гра́да, огня́, от вся́каго зла́го обстоя́нія і вся́каго нестроє́нія. Оби́телі на́шей (ві́си), домам і семействам і вся́кой душі́ христия́нстій і всей страні́ на́шей ісхода́тайствуй мир і ве́лію ми́лость, да сла́вим Тя, Премилостивую Пита́тельницю і Кормительницю на́шу, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Неув’ядаємий Цвіт»","e":"Prayer to the Theotokos before her icon “Unfading Blossom”","secs":[{"h":"Тропар, глас 5","ps":["Ра́дуйся, Богоневі́сто, же́зле та́йний, / Цвіт Неув'яда́ємий процві́тшій, / ра́дуйся, Влади́чице, Є́юже ра́дости наполня́ємся // і жизнь наслі́дствуєм."]},{"h":"Молитва","ps":["О, Пресвята́я і Пренепоро́чная Ма́ти Ді́во, наде́ждо христия́н і прибі́жище грі́шним! Защити́ всіх в несча́стіях к Тебі́ прибіга́ющих, усли́ши стена́нія на́ша, приклони́ у́хо Твоє́ к моле́нію на́шему. Влади́чице і Ма́ти Бо́га на́шего, не пре́зри тре́бующия Твоєя́ по́мощі і не отри́ни нас грі́шних, вразуми́ і научи́ нас, не отступи́ от нас, рабо́в Твої́х, за ропта́ніє на́ше. Бу́ди нам Мать і Покрови́тельниця, вруча́єм себе́ ми́лостивому Покро́ву Твоєму́. Приведи́ нас, грі́шних, к ти́хой і безм'яте́жной жи́зні, да опла́чем гріхи́ на́ші. О, Ма́ти Марі́є, на́ша преблага́я і ско́рая Засту́пнице, покри́й нас Свої́м хода́тайством, защити́ от враго́во ви́димих і неви́димих, ум'ягчи́ сердця́ злих люде́й, возстаю́щих на нас. О, Ма́ти Го́спода Творця́ на́шего! Ти єси́ Ко́рень Ді́вства і Неув'яда́ющий Цвіт чистоти́ і цілому́дрія, пошли́ по́мощ нам немощни́м і обурева́ємим плотськи́ми страстьми́ і блужда́ющими сердця́ми. Просвіти́ на́ші душе́вния о́чі, да ви́дим путі́ пра́вди Бо́жия. Благода́тію Си́на Твоєго́ укріпи́ на́шу сла́бую во́лю во ісполне́ніє за́повідей, да ізба́вимся от вся́кия біди́ і напа́сти і оправда́ни бу́дем Твої́м пречу́дним заступле́нієм на Стра́шнім Суді́ Си́на Твоєго́, Єму́же ми воздає́м сла́ву, честь і поклоне́ніє ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Непорушна Стіна»","e":"Prayer to the Theotokos before her icon “The Unbreakable Wall”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, грі́шнії і смире́ннії, і припаде́м, в покая́нії зову́ще із глубини́ душі́: Влади́чице, помози́, на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тя бо і єди́ну наде́жду і́мами."]},{"h":"Інший тропар, глас 4","ps":["Я́ко Неруши́мую сті́ну і всемо́щний покро́в / стяжа́хом Тя, раби́ Твої́, Влади́чице Богоро́дице, / мрак гріхо́в і скорбе́й отгоня́ющую. / Ті́мже мо́лим Тя: / мир ми́рові Твоєму́ да́руй / і душа́м на́шим світ і спасе́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім с ві́рою притекающим."]},{"h":"Молитва перша","ps":["Царице моя Преблагая, Надіє моя, Богородице. Прихистку сиріт і мандрівних, Заступнице. Скорботних Радосте, Скривджених Покровителько, бачиш мою біду, бачиш мою скорботу. Допоможи мені, бо я немічний, нагодуй мене, бо я мандрівний… Образу мою знаєш, розв’яжи її, як хочеш. Бо не маю іншої помочі, крім Тебе, ні іншої Заступниці, ні благої Утішительки, тільки Тебе, о Богомати… Щоб Ти зберегла мене й покрила, на віки віків. Амінь. Пресвята Богородице, просвіти нас світлом Сина Свого. Алилуя, алилуя, алилуя."]},{"h":"Молитва друга","ps":["О, благода́тная Влади́чице на́ша Богоро́дице, Присноді́во, прийми́ от нас сіє́ благода́рственноє хвале́бноє пі́ніє і вознеси́ ко Творцю́ і Зижди́телю на́шему те́плия моли́тви Твоя́ за нас недосто́йних, да прости́ть Он, Милосе́рдий, нам вся гріхи́ на́ша, по́мисли лука́вия і нечи́стия, діла́ скве́рния. О, Госпожі́ Пресвята́я, умилосе́рдися і низпосли́ дар по коєгожде потре́бі: боля́щия ісціли́, скорб'я́щия уті́ши, заблу́ждшия вразуми́, охрани́ младе́нці, воспита́й і научи́ ю́ния, обо́дри і наста́ви му́жи і жени́, поддержи́ і согрі́й ста́рия, бу́ди нам і зді, і в жи́зні ві́чній Стіно́ Неруши́мая, ізба́ви от вся́ких бід і напа́стей і от ві́чнаго муче́нія, да всегда́ воспіва́юще Твою́ Матери́нськую любо́в, восхваля́єм всім се́рдцем Си́на Твоєго́, со Отце́м Єго́ і Святи́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["І Ти, Владичице, недарма звана «Непорушною Стіною», будь для всіх, хто воює проти мене і задумує чинити мені пакості, воістину неначе якоюсь перепоною й непорушною стіною, що огороджує мене від усякого зла й тяжких утисків. Амінь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Прибавлення ума»","e":"Prayer to the Theotokos before her icon “Increaser of Intellect”","secs":[{"h":"Тропар, глас 4","ps":["О Преславна Мати Христа Бога нашого, Подательки благ, милістю Своєю збережи весь світ, дарунь нам, рабам Твоїм, премудрість і розум, світлом Сина Твого просвіти душі наші, єдина Всеспівана, від Херувимів і Серафимів прославлювана."]},{"h":"Кондак, глас 2","ps":["Я́ко умо́м Христо́вим нас просвіща́ющую, хва́лим Тя, Пречи́стая Ма́ти Го́спода, всю вселе́нную держа́щаго, Красоти́ ми́ра ви́димаго і неви́димаго, луча́ми Жи́зні нас озаря́ющая."]},{"h":"Молитва перша","ps":["О Пресвята Діво! Ти — Наречена Бога Отця й Мати Божественного Його Сина Ісуса Христа! Ти — Цариця Ангелів і спасіння людей, викривальниця грішників і караюча богоодступників. Помилуй і нас, тяжко згрішивших і не виконавших заповідей Божих, порушивших обітниці хрещення й обітниці чернецтва та багато інших, які обіцяли виконувати. Коли Дух Святий відступив від царя Саула, тоді страх і зневіра напали на нього, і темрява розпачу та безрадісний стан душі мучили його. Тепер і ми за гріхи наші всі позбулися благодаті Духа Святого. Розум спустошився марнотою помислів, забуття про Бога затьмарило наші душі, і тепер тиснуть серце всілякі печалі, скорботи, хвороби, ненависть, зло, ворожнеча, мстивість, зловтіха та інші гріхи. І, не маючи радості й утіхи, взиваємо до Тебе, Мати Бога нашого Ісуса Христа, щоб Ти випросила в Сина Твого простити нам усі наші прогрішення і послати до нас Духа Утішителя, як послав Він Його на апостолів, щоб ми, втішені й просвічені Ним, заспівали Тобі подячну пісню: радуйся, Пресвята Богородице, що додала нам розуму на спасіння. Амінь."]},{"h":"Молитва друга","ps":["Цари́це моя́ Преблага́я, Наде́ждо моя́ пресвята́я, прия́телище си́рим і стра́нним засту́пнице, бі́дствующих по́моще і озлобля́ємих покро́ве, зри́ши мою́ напа́сть, зри́ши мою́ скорб; отовсю́ду іскуше́нієм одержи́м єсьм, а заступа́ющаго ність. Ти у́бо Сама́ помози́ мі я́ко не́мощну, окорми́ м'я я́ко стра́нна, наста́ви я́ко заблу́ждша, уврачу́й і спаси́ я́ко безнаде́жна. Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице, Ти нам помози́, на Тебі́ наді́ємся і Тобо́ю хва́лимся, Твої́ бо єсьми́ раби́, да не постиді́мся. Под Твою́ ми́лость прибіга́єм, Богоро́дице Ді́во, моле́ній на́ших не пре́зри в ско́рбіх, но от бід ізба́ви нас, Єди́на чи́стая і благослове́нная. Амі́нь."]},{"h":"Молитва третя","ps":["Богоро́дице Пречи́стая, До́ме, єго́же созда́ Себі́ Прему́дрость Бо́жия, даро́в духо́вних Пода́тельнице, от ми́ра к преми́рним ум наш возводя́щая і всіх к позна́нію ра́зума приводя́щая! Прийми́ моле́бноє пі́ніє от нас, недосто́йних раб Твої́х, с ві́рою і умиле́нієм покланя́ющихся пред пречи́стим о́бразом Твої́м. Умоли́ Си́на Твоєго́ і Бо́га на́шего, да да́руєть власте́м на́шим му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, па́стирем му́дрость духо́вную, ре́вность і бді́ніє о душа́х на́ших, наста́вником смиренному́дріє, ча́дом послуша́ніє, всім же нам дух ра́зума і благоче́стія, дух смире́нія і кро́тости, дух чистоти́ і пра́вди. І ни́ні, Всепі́тая, Вселюби́мая на́ша Ма́ти, пода́й нам ума́ прибавле́ніє, умири́, соєдини́ во вражді́ і разділе́нії су́щия і положи́ їм сою́з любве́ неразрешимий, всіх заблу́ждших от неразу́мія к сві́ту і́стини Христо́ви обрати́, стра́ху Бо́жию, воздержа́нію і трудолю́бію наста́ви, сло́во прему́дрості і душеполе́зноє зна́ніє просящим да́руй, осіни́ нас ві́чною ра́достію, Херуви́мов світлі́йши і Серафи́мов честні́йши су́щая. Ми же, сла́вная діла́ і многоразумную прему́дрость Бо́жию в ми́рі і жи́зні на́шей ви́дяще, устрані́мся земни́я суєти́ і ізли́шніх жите́йських попече́ній, і ум, се́рдце на́ше на Небеса́ возведе́м, я́ко да Твої́м заступле́нієм і по́мощію сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся в Тро́йці сла́вимому Бо́гу і всіх Созда́телю возсила́єм, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це, і чтим о́браз Твой святи́й, і́мже то́чиши ісціле́нія всім, с ві́рою притекающим."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Остробрамська Віленська»","e":"Prayer to the Theotokos before her icon “Ostrobramska” of Vilnius","secs":[{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода ви́шніх сил, Небесе́ і землі́ Цари́це і гра́да на́шего Ки́єва всемо́щная Засту́пнице!","Прийми хвалебну пісню цю від нас недостойних, рабів Твоїх, і піднеси молитви наші до престолу Сина Твого і Бога нашого, щоб милостивий був до нас, грішних, і примножив благість Свою тим, хто шанує Тебе та з вірою й любов’ю вклоняється чудотворному образові Твоєму.","Ко кому́ бо возопії́м Влади́чице? Ко кому́ прибі́гнем в горестях на́ших, а́ще не к Тебі́, Цари́це Небе́сная? Кто плач наш і воздиха́нія на́ша при́йметь, а́ще не Ти, Пренепоро́чная, Наде́ждо христия́н і прибі́жище нам грі́шним? Кто па́че Тебі́ в напа́стіх защи́тить? Тім же мо́лим Тя усе́рдно: покри́й Твої́м хода́тайством на́ша прегріше́нія, защити́ нас от враг ви́димих і неви́димих, ум'ягчи́ се́рдця злих челові́к, возстаю́щих на нас.","О Ма́ти Го́спода на́шего Творця́! Ти єси́ ко́рень ді́вства і неув'яда́ємий цвіт чистоти́. Прими́ недосто́йную моли́тву на́шу і соблюди́ нас в чистоті́ душе́вній, сохрани́ нас от наві́та злих челові́к і от внеза́пния сме́рти, і да́руй нам пре́жде конця́ покая́ніє. Поми́луй нас в дневни́х часі́х і у́тренних і вече́рніх, і во вся́коє вре́м'я сохрани́ нас: стоя́щих, сідя́щих соблюди́, і на вся́ком путі́ ходя́щих, і в нощни́х часі́х спя́щих снабди́, покри́й і заступи́. На вся́ком мі́сті і на вся́коє вре́м'я бу́ди нам, Ма́ти Преблага́я, стіна́ необори́мая і заступле́ніє крі́пкоє. Ти храни́тельниця жи́зні всея́ нам яви́ся, Пречи́стая; Ти нас ізба́ви от бісо́во в час сме́рти; Ти і по сме́рті упокоє́ніє обрісти́ іспроси́ у Си́на Твоєго́ і Бо́га на́шего.","Ми же, грі́шнії, со упова́нієм моле́нія Тебі́ возноси́м і уми́льно вопіє́м: ра́дуйся, Благода́тная; Ра́дуйся, Обра́дованная; ра́дуйся, Преблагослове́нная; Госпо́дь с Тобо́ю, с Тобо́ю с на́ми. К Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рой Засту́пниці на́шей, і Тебі́, я́ко всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш по Христе́ Бо́зі предає́м, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со безнача́льним Єго́ Отце́м, со Пресвяти́м і благи́м і животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О, Всеми́лостивая Госпоже́, Цари́це Богоро́дице, от всіх родо́в ізбра́нная і всі́ми ро́ди небе́сними ублажа́ємая! Воззри́ ми́лостиво на предстоящия пред свято́ю іко́ною Твоє́ю лю́ди сія́, усе́рдно моля́щіяся Тебі́, і сотвори́ предста́тельством Твої́м і заступле́нієм у Си́на Твоєго́ і Бо́га на́шего, да нікто́ же отидеть от мі́ста сего́ тощ упова́нія своєго́ і посра́млен в наде́жді своє́й, но да при́йметь ки́йждо от Тебе́ вся по благо́му ізволе́нію се́рдця своєго́, по ну́жді і потре́бі своє́й, во спасе́ніє душі́ і во здра́віє ті́лу.","Найпа́че же осіни́ і огради́ покро́вом Твої́м, Милосе́рдная Ма́ти, Це́рков Твою́ Святу́ю, ви́шнім Твої́м благослове́нієм архієре́ї на́ші правосла́вния укріпи́, ми́ром огради́, і Святі́й Твоє́й Це́ркві ці́лих, здра́вих, честни́х, долгоде́нствующих пра́во пра́в'ящих сло́во Своєя́ і́стини да́руй, от всіх же ви́димих і неви́димих враг, со всі́ми правосла́вними христия́ни, ми́лостиво ізба́ви, і во правосла́вії і тве́рдій ві́рі до конця́ віко́в непосту́пно і неізмі́нно сохрани́. Призира́й благосе́рдієм, Всепі́тая, і призрі́нієм ми́лостиваго Твоєго́ заступле́нія на всю страну́ на́шу, гра́ди на́ша і град сей [або: храм сей, або: і духовний вертоград, зде сущий], і на сія́ бога́тия Твоя́ ми́лості неоску́дно ізлива́й. Ти бо єси́ всеси́льная Помо́щниця і Засту́пниця всіх нас. Приклони́ся к моли́твам і всіх раб Твої́х, ко святі́й іко́ні Твоє́й зді притека́ющих, усли́ши воздиха́нія і гла́си, і́миже раби́ Твої́ мо́ляться во святі́м мі́сті сем.","А́ще же і інові́рний, і іноплеме́нник, зді преходя́, помо́литься, усли́ши, чадолюби́вая Госпоже́, і сего́ человіколю́бне і ми́лостивно соді́лай, я́же к по́мощі єму́ і ко спасе́нію. Ожесточе́нния же і разсі́янния се́рдці свої́ми во страна́х на́ших на путь і́стини наста́ви: отпадшия от благочести́вия ві́ри обрати́ і па́ки святі́й Правосла́вній Собо́рній і Апо́стольстій Це́ркві сопричти́. В домі́х люде́й Твої́х і во бра́тії святи́я оби́телі сея́ мир огради́ і соблюди́, в ю́них бра́тство і смиренному́дріє утверди́, ста́рость поддержи́, о́троки наста́ви, во во́зрасті соверше́ннім су́щия умудри́, си́рия і вдови́ці заступи́, утісне́нния і в ско́рбіх су́щия уті́ши і охрани́, младе́нці воспита́й, боля́щия уврачу́й, пліне́нния свободи́, огражда́ющи ни при́сно от вся́каго зла бла́гостію Твоє́ю, і уті́ши ми́лостивним Твої́м посіще́нієм і вся благодеющия нам. Да́руй же, Блага́я, землі́ плодоно́сіє, возду́ху благорастворе́ніє і вся, я́же напользу на́шу, да́ри благовре́менния і благопотре́бния, всемо́щним Твої́м предста́тельством пред Всесвято́ю Живонача́льною Тро́йцею.","Пре́жде отше́дшия отці́ і ма́тері, бра́тію і сестри́ на́ша, і вся от літ дре́вніх ко святі́й іко́ні Твоє́й сей припадавшия, упоко́й в селе́ніїх святи́х, в мі́сті зла́чні, в мі́сті поко́йні, іді́же ність печа́ль і воздиха́ніє. Єгда́ же приспі́єть і на́ше от житія́ сего́ отше́ствіє і к ві́чной жи́зні преселе́ніє, предста́ни нам, Преблагослове́нная Ді́во, і да́руй христия́нськую кончи́ну житія́ на́шего, безболі́зненну, непости́дну, ми́рну і Святи́х Та́їн прича́стну, да і в бу́дущем ві́ці сподо́бимся всі, ку́пно со всі́ми святи́ми, безконе́чния блаже́нния жи́зні во Ца́рствії возлю́бленнаго Си́на Твоєго́, Го́спода і Бо́га на́шего Ісу́са Христа́, Єму́же подоба́єть сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Помічниця в пологах»","e":"Prayer to the Theotokos before her icon “Helper in Childbirth”","secs":[{"h":"Тропар, глас 4","ps":["Ма́ти Бо́га на́шего, во утро́бі заче́нши Христа́ Жизнода́вця, по́мощі в рожде́нії Того́ не потре́бовала єси́, ті́мже ле́гці разріши́тися рабо́м Твої́м благослови́ і помози́, і младе́нцев їх во вре́м'я благопотре́бноє роди́тися іму́щих, под покро́в Твой, я́ко Ма́тер, мо́лим, прийми́: Ти бо єси́ в ро́дах Помо́щниця, Засту́пниця рабо́м Твої́м."]},{"h":"Кондак, глас 2","ps":["Слез Є́виних разріше́ніє, проро́чеських писа́ній ісполне́ніє, от Ду́ха Свята́го Богомладе́нця заче́ншая, і во я́сліх Вифлеє́мских Того́ смире́нно роди́вшая, к Тебі́ прибіга́єм я́ко Храни́тельнице жен і младе́нцев, к Тебі́ воздиха́єм і Тя велича́єм: ра́дуйся, Благоутро́бная Ма́ти, в ро́дах Помо́щниця."]},{"h":"Молитва перша","ps":["Прийми́, Госпоже́ Богороди́тельнице, сле́зная моле́нія рабо́в Твої́х, к Тебі́ притека́ющих. Зрим Тя на святі́й іко́ні во чре́ві нося́щую Си́на Твоєго́ і Бо́га на́шего, Го́спода Ісу́са Христа́. А́ще і безболі́зненно родила́ єси́ Єго́, оба́че ма́тернія ско́рби ві́си і не́мощі сино́в і дще́рей челові́чеських зри́ши. Ті́мже те́плі припа́дающе к цільбоно́сному о́бразу Твоєму́ і умиле́нно сей лобиза́юще, мо́лим Тя, Всеми́лостивая Влади́чице: нас, грі́шних, осужде́нних в болі́зніх роди́ти і в печа́ліх пита́ти ча́да на́ша, ми́лостивно пощади́ і сострада́тельно заступи́. Младе́нці же на́ша, та́кожде і роди́вшия їх, от тя́жкаго неду́га і го́ркия ско́рби ізба́ви; да́руй їм здра́віє і благомо́щіє, да і пита́ємії от си́ли в си́лу возраста́ти бу́дуть, і пита́ющия їх іспо́лняться ра́достію і утіше́нієм, я́ко да і ни́ні предста́тельством Твої́м із уст младе́нець і ссу́щих Госпо́дь соверши́ть хвалу́ Свою́.","О Ма́ти Си́на Бо́жия! Умилосе́рдися на ма́тері сино́в челові́чеських і на немощни́я лю́ди Твоя́: постига́ющия нас болі́зні ско́ро ісціли́, належа́щия на нас ско́рби і печа́лі утоли́ і не пре́зри слез і воздиха́ній рабо́в Твої́х. Усли́ши нас в день ско́рби, пред іко́ною Твоє́ю припа́дающих, і в день ра́дости і ізбавле́нія прийми́ благода́рная хвале́нія серде́ць на́ших. Вознеси́ мольби́ на́ша ко Престо́лу Си́на Твоєго́ і Бо́га на́шего, да ми́лостив бу́деть ко гріхо́м і не́мощем на́шим і проба́вить ми́лость Свою́ ві́дущим і́м'я Єго́, я́ко да і ми, і ча́да на́ша, просла́вим Тя, Милосе́рдную Засту́пницю і ві́рную Наде́жду ро́да на́шего, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Пресвята́я Госпоже́ Влади́чице Богоро́дице, в земно́й жи́зні нас не оставля́ющая! Ко кому́ моли́тви вознесу́, ко кому́ сле́зи і воздиха́нія принесу́, а́ще не к Тебі́, всіх ві́рних утіше́ніє! Со стра́хом, ві́рою, любо́вію, Ма́ти Живота́, молю́: да вразуми́ть Госпо́дь лю́ди правосла́вния во спасе́ніє, да дасть ражда́ти нам чад Тебі́ і Си́ну Твоєму́ во благоугожде́ніє, да соблюде́ть нас в чистоті́ смире́нія, в наде́жді о Христі́ спасе́нія, і да́руєть нам всім, в покро́віх благода́ті Твоєя́, земно́є утіше́ніє. Храни́ нас под сі́нію ми́лости Твоєя́, Пречи́стая, моля́щимся о ро́дах помози́, наві́тов злих свободи́, тя́жких бід, напа́стей і смерте́й отврати́. Даждь благода́тноє прозрі́ніє, дух сокруше́нія о грісі́х, даждь зрі́ти всю висоту́ і чистоту́ дарова́ннаго нам Христо́ва уче́нія; храни́ нас от поги́бельнаго отчужде́нія, да всі, благода́рні воспіва́юще вели́чія Твоя́, сподо́бимся Небе́снаго успокоє́нія і та́мо с возлю́бленними Твої́ми, со всі́ми святи́ми просла́вим в Тро́йці Єди́наго Бо́га: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Поглянь на смирення»","e":"Prayer to the Theotokos before her icon “Look Upon My Humility”","secs":[{"h":"Тропар, глас 4","ps":["Необори́мая стіна́ о́браз Твой і істо́чник чуде́с, я́коже дре́вле от Него́ заступле́ніє Твоє́ гра́ду Пско́ву дарова́ла єси́ та́ко і ни́ні нас от всіх бід і скорбе́й ми́лостивно ізба́ви і спаси́ душа́ на́ша я́ко любвеоби́льная Ма́ти."]},{"h":"Кондак, глас 3","ps":["Пренепоро́чная Ді́во, отображе́ніє Ли́ка Твоєго́ чтущия благода́рния да́ри приє́млеши, живи́м і ме́ртвим помога́єши, град і страну́ на́шу спаса́єши, і пред Си́на Твоєго́ моли́тви прино́сиши, і спаса́єши всіх нас."]},{"h":"Молитва","ps":["О, Пресвята́я Госпоже́, Ді́во Богоро́дице, ви́сшая Херуви́м і Честні́йшая Серафи́м, Богоізбра́нная Отрокови́це! При́зри с висоти́ небе́сній ми́лостивним Твої́м о́ком на нас, недосто́йних рабо́в Твої́х, со умиле́нієм і слеза́ми моля́щихся пред Пречи́стим о́бразом Твої́м; не лиши́ нас Твоєго́ заступле́нія і покро́ва Держа́внаго в стра́нствії сем земно́м, многоскорбном і многом'ятежном. Спаси́ нас в поги́белі і ско́рби су́щих, воздви́гни із глубини́ гріхо́вния, просвіти́ ум наш, омраче́нний страстьми́ і уврачу́й я́зви душ і тіле́с на́ших! О, Всеще́драя Ма́ти Человіколюби́ваго Влади́ки! Удиви́ на нас пребога́тия ми́лості Твоя́, укріпи́ немощну́ю во́лю на́шу к ді́ланію за́повідей Христо́вих, ум'ягчи́ окамені́лая се́рдця на́ша любо́вію к Бо́гу і бли́жнім, да́руй нам сокруше́ніє серде́чноє і покая́ніє і́стинноє, да очи́стившеся от скве́рни гріхо́вния, сподо́бимся ми́рния христия́нськия кончи́ни і до́браго отві́та на Стра́шнім і нелицеприятном Суді́ Го́спода на́шего Ісу́са Христа́, Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м, Благи́м і Животворя́щим Ду́хом, подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, Пресвята́я Ді́во, Богоізбра́нная Отрокови́це і чтим святи́я іко́ни Твоєя́ чуде́сноє отображе́ніє."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Аз єсьм з вами, і ніхто же на вы»","e":"Prayer to the Theotokos before her icon “I Am with You, and No One Shall Be Against You”","secs":[{"h":"Тропар, глас 6","ps":["Влади́чице чи́стая, при́зри, Богоро́дице, / виждь на́ших язв болі́зні, / і умилосе́рдися, Пречи́стая, / і ісціли́ со́вістноє жже́ніє, / Твоє́ю ми́лостію ороша́ющи, / і вопію́щи рабо́м Твої́м: / Аз єсьм с ва́ми, // і нікто́же на ви."]},{"h":"Кондак, глас 6","ps":["При́зри на ни, Всепі́тая Богоро́дице, / возсія́й просвіще́ніє сердця́м омраче́нним, / і озари́ ста́до Твоє́, Пречи́стая: / єли́ко бо хо́щеши і мо́жеши, / я́ко Ма́ти су́щи Зижди́теля Твоєго́, / і возопи́й молящим Тя: / аз єсьм с ва́ми, // і нічто́же на ви."]},{"h":"Молитва","ps":["О Всеблага́я Засту́пнице ро́да християнського, Ма́ти вся Держащего десни́цею Своє́й Христа́ Бо́га на́шего! Ізле́й на ни ми́лості і щедро́ти Єго́, і да не убої́мся і не устраші́мся враг ви́димих і неви́димих, я́ко рекла́ єси́ уповающим на Тя: «Аз єсьм с ва́ми і нікто́же на ви.» Сохрани́ і́стинную Святу́ю Правосла́вную Це́рков і оби́тель на́шу от раско́лов і єресе́й і положи́ нача́ло покая́нія наро́да на́шего. Возврати́ Святую Україну на дарова́нний єй Бо́гом путь неповрежденной ві́ри, да напо́лниться фимія́мом моли́тв і расцвететь, а́ки крин се́льний; да поживе́м в благоче́стії і чистоті́, всегда́ храни́ми Тобо́ю от іскуше́нія антихристова, наше́ствія іноплеме́нних, междуусо́бния бра́ні, тру́са, огня́, гла́да і мо́ра; от напра́сния сме́рті, пліне́нія і раздо́ров семе́йних; мона́шеськоє житіє́ укріпи́ і спаси́ ни, Пречи́стая, я́ко упова́єм на Тя по рече́нному тобо́ю: «Аз єсьм с ва́ми і нікто́же на ви.» Моли́ся о нас, Пресвята́я Влади́чице Богоро́дице, ко Го́споду Бо́гу на́шему, ми́лующему і спаса́ющему, да не лиши́ть ни защити і Ца́рствія Своєго́ присвоє́нія, і́же і Сам рече́ ві́рним Свої́м: «Аз єсьм с ва́ми і нікто́же на ви.» Єму́ же сла́ва, держа́ва, честь і поклоне́ніє, си́ла і вели́чіє подоба́єть Отцю́, і Си́ну, і Свято́му Ду́ху ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Мінська»","e":"Prayer to the Theotokos before her icon “Minsk”","secs":[{"h":"Тропар, глас 5","ps":["На дре́ві кре́стнім яви́лася єси́, Пренепоро́чная Отрокови́це, / от Царгра́да і Ки́єва / Богоспаса́ємому гра́ду Ми́нську ми́лость показа́вши. / Просвіти́ нас, грі́шних, сія́нієм Свої́м, / яви́, я́ко при́сно, си́лу Свою́, / спаси́ нас предста́тельством Свої́м / і ізбавля́й от наві́т вра́жиїх, // Тя бо Необори́мую Сті́ну і єди́ну Наде́жду і́мами."]},{"h":"Молитва","ps":["О Всепі́тая і Всеблага́я Ді́во Богоро́дице, Небе́сная на́ша Засту́пнице! К Тебі́ по Бо́зі, я́ко Премилосердней Госпоже́, собо́рні прибіга́єм і вопіє́м: прийми́ сіє́ ма́лоє хвале́бноє пі́ніє, сохрани́ Богоспаса́ємий град сей, єму́ же чудотво́рная іко́на Твоя́ во отра́ду і утіше́ніє даде́ся. Сего́ ра́ди мо́лим Тя: ізба́ви нас от враг ви́димих і неви́димих, от наше́ствія іноплеме́нних і междоусо́бния бра́ні, от зла́го обстоя́нія і ско́рби, от іскуше́ній, бід і болі́зней.","Спаси́ і поми́луй раби́ Твоя́: Вели́каго Господи́на і Отця́ на́шего Святі́йшаго Патріарха Київськаго і всієї України, Преосвяще́нния митрополи́ти, архієпи́скопи, єпи́скопи, весь свяще́нничеський і мона́шеський чин, і весь при́чет церко́вний. Прийми́ под кров Твой вла́сті і во́їнство Богохранимия страни́ на́шея, вразуми́ і наста́ви їх пра́во пра́вити, за́повіді Бо́жия соблюда́юще, да ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́. О Пречи́стая Влади́чице! Не забу́ди нас во вся дні жи́зні на́шея і да пребива́єть с на́ми неотсту́пно о́браз Твой честни́й. Во вре́м'я же ісхо́да на́шего проле́й те́плую Твою́ моли́тва ко Пра́ведному Судії́, да, презрі́в безчи́сленная прегріше́нія, поми́луєть і спасе́ть нас, я́ко Благ і Человіколю́бець. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Знамення» Абалацька","e":"Prayer to the Theotokos before her icon “of the Sign” of Abalak","secs":[{"h":"Тропар, глас 4","ps":["Днесь, я́ко со́лнце незаходи́моє, / сві́тло сія́єть о́браз Твой, Пречи́стая, / во ві́си Абала́кськой на возду́сі / вдови́ці чу́дне яви́вшийся. / І ми, припа́дающе к нему́, / Богоро́дице уми́льно вопіє́м: / о, Всепі́тая Влади́чице, / мир оби́телі Твоє́й да́руй // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Єва́нгелія Христо́ва благові́стник Лука́ / о́брази Твоя́, Пречи́стая, дре́вле ізобрази́, / вдови́ця же, єди́н от них чу́дне узрі́вши, / возвісти́ нам повелі́ніє Твоє́, / да ві́рнії, к Тебі́ притека́юще, зову́ть: / ра́дуйся, Влади́чице, // Зна́меніє ми́лости Твоєя́ нам явля́ющая."]},{"h":"Інший кондак, глас 4","ps":["Абала́кськой іко́ні Влади́чиці на́шей Богоро́диці, / благогові́йно поклоня́ющеся, / со умиле́нієм взива́єм: / спаси́ нас моли́твами Твої́ми, // Пресвята́я Ді́во."]},{"h":"Молитва","ps":["О, Пресвята́я Влади́чице моя́ Богоро́дице, милосе́рдія су́щи істо́чник, покро́ве, упова́ніє і прибі́жище христия́н! Тебі́, Всеси́льній Предста́тельнице і Спору́чнице покая́нія і спасе́нія моєго́, аз, грі́шний раб Твой, вруча́ю ду́шу і ті́ло моє́, вхо́ди і ісхо́ди моя́, ві́ру і жи́тельство моє́, кончи́ну і число́ дній мої́х, глаго́ли і помишле́нія моя́, діла́ і начина́нія моя́; Ти же, ми́лостивая Ма́ти Бо́жия, мно́ю руково́дствуй, покрива́й, соблюда́й і спаса́й м'я от всіх вра́жеських ко́зней невреди́мо, да немо́лчно, до послі́дняго іздиха́нія моєго́, взива́ю Ті: Ра́дуйся, Неві́сто неневі́стная! Ра́дуйся, Свята́я, святи́х бо́льшая! Пресвята́я Богоро́дице, спаси́ м'я! Амі́нь!"]},{"h":"Молитва друга","ps":["О, Пресвята́я Госпоже́, Ді́во Богоро́дице, ви́шшая Херуви́м і Серафи́м, і всіх святи́х Святі́йшая! Ти, Всеблага́я, во Абала́ці іко́ну Твою́ многоціле́бную яви́ти благоволи́ла єси́, і є́ю мно́гая і неізрече́нная чудеса́ соді́лала єси́, і ни́ні содіва́єши по Твоєму́ неізрече́нному к нам милосе́рдію. Тебі́, Преблагослове́нній ро́да на́шего Засту́пнице, припа́даєм і мо́лимся, вку́пі со святи́телем Никола́єм і преподо́бною Марі́єю Єги́петською, да не лиші́мся їх хода́тайства і Твоєго́ заступле́нія і покро́ва держа́внаго. Спаси́ і защити́ нас, Влади́чице, от разжже́нних стріл лука́ваго, укріпи́ не́мощную волю́ на́шу к ді́ланію за́повідей Христо́вих, ум'ягчи́ окамене́нная сердця́ на́ша любо́вію к Бо́гу і бли́жнім, да́руй нам сокруше́ніє серде́чноє і покая́ніє і́стинноє, да очи́стившеся от скве́рни гріхо́вния і ізба́вльшеся от неві́дінія і забве́нія, восста́вше от лі́ності і нераде́нія, возмо́жем принести́ Творцю́ благоуго́дния Єму́ плоди́ до́брих діл і сподо́битися ми́рния христия́нськия кончи́ни і отвіта́ пра́ваго на Стра́шнім і нелицеприя́тнім Суді́ Єго́. О, Госпоже́ Всеми́лостивая! В час гро́зний сме́ртний найпа́че яви́ нам Твоє́ многомо́щноє заступле́ніє, ускори́ тогда́ на по́мощ к нам, і держа́вною руко́ю Твоє́ю ісхити́ нас із вла́сті лю́таго мироде́ржця, і́бо воі́стину мно́го мо́жеть моли́тва Твоя́ пред лице́м Го́спода, і вся возмо́жна суть хода́тайству Твоєму́, а́ще то́кмо восхо́щеши. Ті́мже на святи́й о́браз Твой умиле́нно взира́юще і пред ним Тебі́ покланя́ющеся, со упова́нієм благи́м са́мі себе́, і друг дру́га, і весь живо́т наш Тебі́ по Бо́зі моли́твенно предає́м і Тя велича́єм с ро́ждшимся от Тебе́ Спаси́телем на́шим, Го́сподом Ісу́сом Христо́м, Єму́же, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Новоникитська»","e":"Prayer to the Theotokos before her icon “Novonikitsk”","secs":[{"h":"Тропар, глас 4","ps":["К Богоро́диці прилі́жно ни́ні притеце́м, грі́шнії і смире́ннії, і припаде́м, в покая́нії зову́ще із глубини́ душі́: Влади́чице, помози́ на ни милосе́рдовавши, потщи́ся, погиба́єм от мно́жества прегріше́ній, не отврати́ Твоя́ раби́ тщи, Тя бо і єди́ну наде́жду і́мами."]},{"h":"Кондак, глас 6","ps":["Не і́мами іни́я по́мощі, не і́мами іни́я наде́жди, ра́зві Тебе́, Влади́чице, Ти нам помози́: на Тебі́ наді́ємся і Тобо́ю хва́лимся, Твої́ бо єсьми́ раби́, да не постиді́мся."]},{"h":"Молитва","ps":["Ко кому́ воззову́, Влади́чице, ко кому́ прибі́гну в печа́лі моє́й? Ко кому́ принесу́ сле́зи і воздиха́нія моя́, а́ще не к Тебі́, Цари́це Небесе́ і землі́? Кто істо́ргнеть м'я от ти́ни гріхо́в і беззако́ній, а́ще не Ти, о Ма́ти Живота́, Засту́пнице і Прибі́жище ро́да челові́чеськаго? Усли́ши стена́ніє моє́, уті́ши м'я і поми́луй в го́ресті моє́й, защити́ в біда́х і напа́стіх, ізба́ви от озлобле́ній і скорбе́й, неду́гов і болі́зней і от враг ви́димих і неви́димих; умири́ вражду́ стужа́ющих мні, да ізба́влен бу́ду от клевети́ і зло́би челові́чеськія; та́кожде от своєя́ мі пло́ті гну́сних оби́чаєв свободи́ м'я. Укри́й м'я под сі́нію ми́лости Твоєя́, да обря́щу поко́й і ра́дость і от гріхо́в очище́ніє. Твоєму́ ма́тернему заступле́нію себі́ вруча́ю: бу́ди мні Ма́ти і наде́жда, покро́в і по́мощ, ра́дость і утіше́ніє і ско́рая во всем Помо́щниця. О чу́дная Влади́чице! Всяк, притека́яй к Тебі́, без Твоєя́ всеси́льния по́мощі не отхо́дить. Сего́ ра́ди і аз, недосто́йний, к Тебі́ прибіга́ю, да ізба́влен бу́ду от внеза́пния і лю́тия сме́рті, скре́жета зу́бнаго і ві́чнаго муче́нія, Небе́сноє же Ца́рствіє получи́ти сподо́блюся і Тебі́ во умиле́нії се́рдця реку́: Ра́дуйся, Ма́ти Бо́жия, Предста́тельнице і Засту́пнице на́ша усе́рдная, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Слово плоть бисть» Албазинська","e":"Prayer to the Theotokos before her icon “The Word Was Made Flesh” of Albazin","secs":[{"h":"Тропар, глас 3","ps":["Всеми́лостивая на́ша Засту́пнице, / Ма́ти воплоти́вшагося Бо́га Сло́ва, / явле́й чудото́чний о́браз Свой на Аму́рськой землі́, / із него́ же благода́ть оби́льно ізлива́єши, / подава́я ісціле́ніє неду́гов душе́вних і тіле́сних. / О, Всеблага́я Богороди́тельнице, / непра́здних жен в рода́х Помо́щнице, / і Взбра́нной Воєво́ді побіди́тельная, / от наше́ствія іноплеме́нних Крі́пкий Щі́те, / Правосла́віє в конці́х землі́ Українській укріпи́, / і пода́й душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 6","ps":["Предста́тельство христия́н непости́дноє, / хода́тайство ко Творцю́ непрело́жноє, / не пре́зри грі́шних моле́ній гла́си, / но предвари́, я́ко Блага́я, на по́мощ нас, ві́рно зову́щих Ті: / ускори́ на моли́тву і потщи́ся на умоле́ніє, / предста́тельствующи при́сно, Богоро́дице, чту́щих Тя."]},{"h":"Молитва","ps":["Богоро́дице Ді́во, Пренепоро́чная Ма́ти Христа́ Бо́га на́шего, Засту́пнице ро́да христия́нськаго! Пред чудотво́рною іко́ною Твоє́ю предстоя́ше, отці́ на́ші моли́ша Тя, да яви́ши покро́в Твой і заступле́ніє страні́ Прияму́рстій. Ті́мже і ми ни́ні мо́лим Тя: град наш і страну́ сію́ от нахожде́нія іноплеме́нних соблюди́ і от междоусо́бния бра́ні сохрани́. Да́руй ми́рові мир, землі́ плодо́в ізоби́ліє; сохрани́ во святи́ні па́стирей на́ших, во святи́х хра́міх тружда́ющихся: осіни́ вседержа́вним покро́вом Твої́м строї́телей і благотвори́телей їх. Утверди́ в правові́рії і єдиноми́слії бра́тій на́ших: заблу́ждших же і отсту́пльших от правосла́вния ві́ри вразуми́ і соєдини́ Святі́й Це́ркві Си́на Твоєго́. Бу́ди всім притека́ющим к чудотво́рній іко́ні Твоє́й покро́в, утіше́ніє і приста́нище от вся́ких зол, бід і обстоя́ній, Ти бо єси́ больни́х ісціле́ніє, скорб'я́щих утіше́ніє, заблу́дших ісправле́ніє і вразумле́ніє. Прийми́ моле́нія на́ша і вознеси́ я ко Престо́лу Всеви́шняго, я́ко да твої́м предста́тельством соблюда́єми і покро́вом Твої́м осіня́ємі, просла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Молченська»","e":"Prayer to the Theotokos before her icon “Molchensk”","secs":[{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється сла́вний град Київ і в Пути́влі ликова́ніє ве́ліє, я́ко честву́ють, Богома́ти, ди́вную іко́ну Твою́, ме́дом благода́ті всіх напоя́ющую."]},{"h":"Кондак, глас 6","ps":["Притеце́м, лю́діє, к Влади́чиці на́шей Ді́ві Богоро́диці, іко́ну бо Свою́ Молче́нськую нам дарова́, то́ки ісціле́ній істоча́ющую, вся́кую по́мощ в душе́вних і тіле́сних неду́зіх подаю́щую і к жи́зні ві́чной приводя́щую."]},{"h":"Молитва","ps":["О, Всеми́лостивая, человіколюби́вая Влади́чице на́ша Богоро́дице! Усли́ши сіє́ немощно́є моле́ніє с любо́вію і тре́петом припа́дающих к честні́й і сла́вній Молче́нськой іко́ні Твоє́й. Смире́нно про́сим Тя: бу́ди Стіна́ неруши́мая страні́ на́шей Українській, святу́ю Це́рков Правосла́вную защити́ от неві́рія, єресе́й і раско́лов. Ти бо єси́ всеси́льная христия́н Засту́пниця. Вся́кую ду́шу, к Тебі́ прибіга́ющую, огради́ от зла́го обстоя́нія, ско́рби і болі́зні, удержи́ от паде́ній гріхо́вних, па́дших возста́ви к покая́нію, стра́ждущих душе́вними неду́гами і одержи́мих зли́ми духа́ми ісціли́, пода́ждь уходя́щим в жизнь ві́чную утіше́ніє і наде́жду спасе́нія, і вся потре́бная к благочести́вой жи́зні да́руй. Да сла́вим в Тро́йці Єди́наго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха і Твоє́ ми́лостивноє предста́тельство, ни́ні і при́сно і во ві́ки віко́в."]}],"notes":[]},{"u":"Молитва Пресвятій Богородиці перед іконою «Урюпінська»","e":"Prayer to the Theotokos before her icon “Uryupinsk”","secs":[{"h":"Тропар, глас 3","ps":["Яви́лася єси́ на дре́ві в Донсько́й землі́, / благода́тная Твоя́ іко́на. Богоро́дице, / больни́я ісціля́ти, заблу́ждшия обраща́ти; / ті́мже уми́льно мо́лимся Тебі́: / ізба́ви град наш от вся́каго зла / і спаси́ лю́ди, к Тебі́ притека́ющия."]},{"h":"Кондак, глас 5","ps":["Всеблага́я Чи́стая Богоро́дице, / к Тебі́ прибіга́єм, ві́рнії, / Тобо́ю бо позна́хом ми́лость Бо́жию, / чу́дную іко́ну Твою́, / от нея́ же всі здра́віє і спасе́ніє приє́млем."]},{"h":"Молитва","ps":["О, Пресвята́я, Преблагослове́нная Ма́ти Го́спода на́шего! Припа́даєм і поклоня́ємся Тебі́ пред свято́ю чудотво́рною іко́ною Твоє́ю, воспомина́юще ди́вноє явле́ніє Твоє́ во гра́ді на́шем, смире́нно мо́лим Тя, Блага́я засту́пнице ро́да на́шего, сохрани́ под кро́вом ми́лости Твоєя́ Це́рков Твою́ святу́ю, град наш і всю страну́ на́шу правосла́вную, і всіх притека́ющих к Тебі́ с ві́рою і любо́вію, умиле́нно прося́щих со слеза́ми Твоєго́ заступле́нія. Пода́ждь недугующим цільбу́ і здра́віє, ізба́ви нас от вся́кия ско́рби і печа́лі, огради́ нас от вся́кия напа́сти і злих клеве́ть, ві́ру правосла́вную до конця́ дній на́ших непоро́чною сохрани́, во всіх за́повідях Госпо́дніх наста́ви і сподо́би нас ми́рния, христия́нськая кончи́ни, і до́браго отві́та на Стра́шном Суді́ Си́на Твоєго́ і Бо́га на́шего; Єго́ же умоли́ за нас ма́терніми моли́твами Твої́ми, да не осу́дить нас по беззако́ніям на́шим, но да поми́луєть нас по вели́цій і неізрече́нной ми́лості Своє́й; Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м Ду́хом, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]}];
export default D;
